--
-- Name: add_supplier_payable_attachments(uuid, jsonb); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.add_supplier_payable_attachments(p_payable_id uuid, p_attachments jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare p apticket.supplier_payables; item jsonb; obj storage.objects; v_count integer;
begin
  if auth.uid() is null or not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissão para incluir anexos.';
  end if;
  select * into p from apticket.supplier_payables where id=p_payable_id
    and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found or not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Lançamento indisponível nesta empresa.';
  end if;
  if p_attachments is null or jsonb_typeof(p_attachments)<>'array' then
    raise exception using errcode='22023',message='Informe uma lista válida de anexos.';
  end if;
  select count(*) into v_count from apticket.supplier_payable_attachments where supplier_payable_id=p.id and deleted_at is null;
  if jsonb_array_length(p_attachments)=0 or jsonb_array_length(p_attachments)+v_count>20 then
    raise exception using errcode='22023',message='Inclua ao menos um arquivo e mantenha no máximo 20 anexos no lançamento.';
  end if;
  for item in select value from jsonb_array_elements(p_attachments) loop
    if jsonb_typeof(item)<>'object' or coalesce(item->>'installment_number','')!~'^[1-9][0-9]{0,2}$'
      or (item->>'installment_number')::integer<>coalesce(p.installment_number,1) then
      raise exception using errcode='22023',message='O anexo deve pertencer à parcela selecionada.';
    end if;
    if not apticket_finance_private.can_manage_payable_upload(item->>'storage_path')
      or split_part(item->>'storage_path','/',1)<>p.tenant_id::text
      or split_part(item->>'storage_path','/',2)<>p.operating_company_id::text then
      raise exception using errcode='42501',message='Arquivo indisponível para esta empresa.';
    end if;
    select * into obj from storage.objects where bucket_id='supplier-payable-attachments' and name=item->>'storage_path' for update;
    if not found then raise exception using errcode='23514',message='Envie o arquivo antes de salvar o anexo.'; end if;
    if coalesce(item->>'file_size','')!~'^[1-9][0-9]{0,7}$'
      or (item->>'file_size')::bigint is distinct from (obj.metadata->>'size')::bigint then
      raise exception using errcode='23514',message='O tamanho do anexo não corresponde ao arquivo enviado.';
    end if;
    insert into apticket.supplier_payable_attachments(tenant_id,operating_company_id,supplier_payable_id,
      storage_path,file_name,file_size,content_type,attachment_type,type_description,created_by)
    values(p.tenant_id,p.operating_company_id,p.id,item->>'storage_path',btrim(item->>'file_name'),
      (item->>'file_size')::bigint,coalesce(obj.metadata->>'mimetype','application/octet-stream'),
      item->>'attachment_type',case when item->>'attachment_type'='outros' then nullif(btrim(item->>'type_description'),'') end,auth.uid());
  end loop;
  return true;
end $_$;


ALTER FUNCTION apticket.add_supplier_payable_attachments(p_payable_id uuid, p_attachments jsonb) OWNER TO supabase_admin;

--
-- Name: FUNCTION add_supplier_payable_attachments(p_payable_id uuid, p_attachments jsonb); Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON FUNCTION apticket.add_supplier_payable_attachments(p_payable_id uuid, p_attachments jsonb) IS 'Inclui anexos tipados em um título existente, com limite por lançamento, escopo e validação do arquivo enviado. Não altera valores, status ou aprovações.';


--
-- Name: allocate_financial_amount(numeric, jsonb, jsonb); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.allocate_financial_amount(p_amount numeric, p_categories jsonb, p_centers jsonb) RETURNS TABLE(category_id uuid, category_code text, category_name text, center_id uuid, center_code text, center_name text, amount numeric)
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
with dimensions as (
  select 'category' dimension,value item from jsonb_array_elements(p_categories)
  union all select 'center',value from jsonb_array_elements(p_centers)
), floors as (
  select *,floor(abs(round(p_amount*100))*((item->>'percentage')::numeric/100)) cents,
    row_number() over(partition by dimension order by (item->>'percentage')::numeric desc,item->>'item_id') priority
  from dimensions
), distributed as (
  select *,cents+case when priority=1 then abs(round(p_amount*100))-sum(cents) over(partition by dimension) else 0 end allocated from floors
), intervals as (
  select *,sum(allocated) over(partition by dimension order by item->>'item_id') finish,
    sum(allocated) over(partition by dimension order by item->>'item_id')-allocated start from distributed
)
select (c.item->>'item_id')::uuid,c.item->>'code',c.item->>'name',
  (s.item->>'item_id')::uuid,s.item->>'code',s.item->>'name',
  sign(p_amount)*greatest(0,least(c.finish,s.finish)-greatest(c.start,s.start))/100
from intervals c cross join intervals s where c.dimension='category' and s.dimension='center';
$$;


ALTER FUNCTION apticket.allocate_financial_amount(p_amount numeric, p_categories jsonb, p_centers jsonb) OWNER TO supabase_admin;

--
-- Name: apply_supplier_payable_allocation(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.apply_supplier_payable_allocation(p_supplier_payable_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into p from apticket.supplier_payables where id=p_supplier_payable_id and deleted_at is null;
  if not found then raise exception using errcode='P0002',message='Lancamento nao encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para aplicar o rateio.';
  end if;
  if not apticket_finance_private.apply_fixed_supplier_allocation(p.id) then
    raise exception using errcode='23514',message='Nenhuma regra de rateio valida foi encontrada para esta competencia.';
  end if;
  return true;
end $$;


ALTER FUNCTION apticket.apply_supplier_payable_allocation(p_supplier_payable_id uuid) OWNER TO supabase_admin;

--
-- Name: approve_supplier_payable(uuid, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.approve_supplier_payable(p_request_id uuid, p_comment text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  request apticket.supplier_payable_approval_requests;
  current_step apticket.supplier_payable_approval_steps;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into request from apticket.supplier_payable_approval_requests
    where id=p_request_id for update;
  if not found then raise exception using errcode='P0002',message='Solicitacao de aprovacao nao encontrada.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(
    request.tenant_id,request.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para aprovar este lancamento.';
  end if;
  if request.status<>'pending' then
    raise exception using errcode='23514',message='Esta solicitacao de aprovacao ja foi concluida.';
  end if;
  if p_comment is not null and length(btrim(p_comment)) not between 1 and 1000 then
    raise exception using errcode='23514',message='O comentario deve possuir no maximo mil caracteres.';
  end if;
  select * into current_step from apticket.supplier_payable_approval_steps
    where request_id=request.id and status='pending'
    order by step_order limit 1 for update;
  if not found then
    raise exception using errcode='23514',message='A solicitacao nao possui etapa pendente.';
  end if;
  if current_step.approver_id<>auth.uid() then
    raise exception using errcode='42501',message='A aprovacao aguarda a decisao de outro responsavel.';
  end if;
  update apticket.supplier_payable_approval_steps set status='approved',
    decided_at=clock_timestamp(),decision_comment=nullif(btrim(p_comment),'')
    where id=current_step.id;
  if not exists(select 1 from apticket.supplier_payable_approval_steps
    where request_id=request.id and status='pending') then
    update apticket.supplier_payable_approval_requests set status='approved',
      completed_at=clock_timestamp() where id=request.id;
    update apticket.supplier_payables set status='approved'
      where id=request.supplier_payable_id;
  end if;
  return true;
end $$;


ALTER FUNCTION apticket.approve_supplier_payable(p_request_id uuid, p_comment text) OWNER TO supabase_admin;

--
-- Name: aprovar_medicao_contrato(uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.aprovar_medicao_contrato(p_medicao_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
declare
  v_tenant_id uuid := apticket.current_tenant_id();
  v_medicao apticket.medicoes_contrato;
  v_actor_nome text;
  v_company_id uuid;
  v_conta_id uuid;
  v_ja_aprovada boolean := false;
begin
  if auth.uid() is null
    or v_tenant_id is null
    or not apticket.has_permission(auth.uid(), 'contratos', 'edit') then
    raise exception using errcode = '42501', message = 'Sem permissão para aprovar a medição.';
  end if;

  select profile.name into v_actor_nome
  from apticket.profiles as profile
  where profile.id = auth.uid()
    and profile.tenant_id = v_tenant_id
    and profile.is_active;

  if v_actor_nome is null then
    raise exception using errcode = '42501', message = 'Usuário ativo não encontrado.';
  end if;

  select * into v_medicao
  from apticket.medicoes_contrato
  where id = p_medicao_id
    and tenant_id = v_tenant_id
    and deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Medição não encontrada.';
  end if;

  if v_medicao.status = 'cancelada' then
    raise exception using errcode = '22023', message = 'Uma medição cancelada não pode ser aprovada.';
  elsif v_medicao.status = 'faturada' then
    raise exception using errcode = '22023', message = 'Uma medição faturada não pode ser aprovada novamente.';
  elsif v_medicao.status = 'aprovada' then
    v_ja_aprovada := true;
  elsif v_medicao.status <> 'gerada' then
    raise exception using errcode = '22023', message = 'A medição não está disponível para aprovação.';
  else
    update apticket.medicoes_contrato
    set status = 'aprovada',
        aprovada_em = now(),
        aprovada_por = auth.uid(),
        aprovada_por_nome = v_actor_nome
    where id = p_medicao_id
    returning * into v_medicao;
  end if;

  select company_id into v_company_id
  from apticket.contracts
  where id = v_medicao.contrato_id
    and tenant_id = v_tenant_id;

  if v_company_id is null then
    raise exception using errcode = 'P0002', message = 'Cliente do contrato não encontrado.';
  end if;

  insert into apticket.contas_receber (
    tenant_id, medicao_id, contrato_id, company_id, cliente_nome,
    documento_referencia, descricao, competencia, valor_original,
    valor_aberto, vencimento_em, aprovado_em, aprovado_por
  ) values (
    v_tenant_id,
    v_medicao.id,
    v_medicao.contrato_id,
    v_company_id,
    v_medicao.cliente_nome,
    'MED-' || replace(v_medicao.numero_contrato, '/', '-') || '-' || to_char(v_medicao.competencia, 'YYYYMM'),
    'Medição do contrato ' || v_medicao.numero_contrato || ' - competência ' || to_char(v_medicao.competencia, 'MM/YYYY'),
    v_medicao.competencia,
    v_medicao.valor_total,
    v_medicao.valor_total,
    v_medicao.data_vencimento,
    coalesce(v_medicao.aprovada_em, now()),
    coalesce(v_medicao.aprovada_por, auth.uid())
  )
  on conflict (medicao_id) do nothing
  returning id into v_conta_id;

  if v_conta_id is null then
    select id into v_conta_id
    from apticket.contas_receber
    where medicao_id = v_medicao.id;
  end if;

  return jsonb_build_object(
    'medicao_id', v_medicao.id,
    'conta_receber_id', v_conta_id,
    'status', 'aprovada',
    'ja_aprovada', v_ja_aprovada
  );
end
$$;


ALTER FUNCTION apticket.aprovar_medicao_contrato(p_medicao_id uuid) OWNER TO postgres;

--
-- Name: archive_customer_contract(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_customer_contract(p_contract_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare contract apticket.contracts; begin
  select * into contract from apticket.contracts
    where id=p_contract_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Contrato de cliente nao encontrado.'; end if;
  if auth.uid() is null or contract.tenant_id<>apticket.current_tenant_id()
    or not apticket.has_permission(auth.uid(),'contratos','delete') then
    raise exception using errcode='42501',message='Sem permissao para excluir este contrato.';
  end if;
  if exists(select 1 from apticket.medicoes_contrato where contrato_id=contract.id) then
    raise exception using errcode='23514',message='Este contrato possui medicoes e nao pode ser excluido.';
  end if;
  update apticket.contracts set status='cancelled',deleted_at=clock_timestamp(),updated_at=clock_timestamp()
    where id=contract.id;
  return true;
end
$$;


ALTER FUNCTION apticket.archive_customer_contract(p_contract_id uuid) OWNER TO supabase_admin;

--
-- Name: archive_employee(uuid, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_employee(p_employee_id uuid, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare employee apticket.funcionarios; begin
  select * into employee from apticket.funcionarios where id=p_employee_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Funcionário não encontrado.'; end if;
  if auth.uid() is null or employee.tenant_id<>apticket.current_tenant_id()
    or not apticket.has_permission(auth.uid(),'funcionarios','delete') then
    raise exception using errcode='42501',message='Sem permissão para arquivar funcionários.';
  end if;
  update apticket.funcionarios set status='desligado',data_demissao=coalesce(data_demissao,current_date),
    motivo_desligamento=coalesce(nullif(trim(p_reason),''),motivo_desligamento),deleted_at=clock_timestamp(),
    updated_at=clock_timestamp(),updated_by=auth.uid() where id=p_employee_id;
end $$;


ALTER FUNCTION apticket.archive_employee(p_employee_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: archive_employee_financial_event(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_employee_financial_event(p_event_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_event apticket.funcionario_eventos_financeiros;
begin
  select * into v_event from apticket.funcionario_eventos_financeiros
  where id=p_event_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Evento financeiro não encontrado.'; end if;
  if auth.uid() is null or v_event.tenant_id<>apticket.current_tenant_id()
    or not (apticket.has_permission(auth.uid(),'funcionarios','payroll') or apticket.has_permission(auth.uid(),'funcionarios','edit')) then
    raise exception using errcode='42501',message='Sem permissão para excluir eventos financeiros.';
  end if;
  if v_event.status_integracao<>'pendente' or v_event.conta_pagar_id is not null then
    raise exception using errcode='23514',message='Somente eventos financeiros pendentes e sem vínculo podem ser excluídos.';
  end if;
  update apticket.funcionario_eventos_financeiros_itens
    set deleted_at=clock_timestamp(),updated_at=clock_timestamp()
    where evento_id=v_event.id and deleted_at is null;
  update apticket.funcionario_eventos_financeiros
    set deleted_at=clock_timestamp(),updated_at=clock_timestamp() where id=v_event.id;
end $$;


ALTER FUNCTION apticket.archive_employee_financial_event(p_event_id uuid) OWNER TO supabase_admin;

--
-- Name: archive_employee_position(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_employee_position(p_position_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare position apticket.funcionario_cargos_salarios; replacement apticket.funcionario_cargos_salarios; begin
  select * into position from apticket.funcionario_cargos_salarios where id=p_position_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Cargo e salário não encontrados.'; end if;
  if auth.uid() is null or position.tenant_id<>apticket.current_tenant_id()
    or not apticket.has_permission(auth.uid(),'funcionarios','delete') then
    raise exception using errcode='42501',message='Sem permissão para excluir cargos e salários.';
  end if;
  update apticket.funcionario_cargos_salarios set deleted_at=clock_timestamp(),updated_at=clock_timestamp() where id=position.id;
  if position.vigente_ate is null then
    select * into replacement from apticket.funcionario_cargos_salarios
      where funcionario_id=position.funcionario_id and deleted_at is null order by vigente_de desc,created_at desc limit 1 for update;
    if replacement.id is null then
      update apticket.funcionarios set cargo_atual_id=null,updated_at=clock_timestamp(),updated_by=auth.uid() where id=position.funcionario_id;
    else
      update apticket.funcionario_cargos_salarios set vigente_ate=null,updated_at=clock_timestamp() where id=replacement.id;
      update apticket.funcionarios set cargo_atual_id=replacement.id,updated_at=clock_timestamp(),updated_by=auth.uid() where id=position.funcionario_id;
    end if;
  end if;
end $$;


ALTER FUNCTION apticket.archive_employee_position(p_position_id uuid) OWNER TO supabase_admin;

--
-- Name: archive_financial_dimension(text, uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_financial_dimension(p_dimension text, p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_tenant uuid; v_company uuid; deps jsonb; begin
 if not apticket.has_permission(auth.uid(),'financeiro_fluxo_caixa','edit') then
   raise exception using errcode='42501',message='Sem permissão para esta operação financeira.';
 end if;
 if p_dimension='cost_center' then
   select tenant_id,operating_company_id into v_tenant,v_company from apticket.financial_cost_centers where id=p_id and deleted_at is null;
 elsif p_dimension='category' then
   select tenant_id,operating_company_id into v_tenant,v_company from apticket.financial_categories where id=p_id and deleted_at is null;
 else raise exception using errcode='22023',message='Tipo de cadastro financeiro inválido.'; end if;
 if auth.uid() is null or v_tenant is distinct from apticket.current_tenant_id()
   or not apticket.has_financial_scope(v_tenant,v_company,true) then
   raise exception using errcode='42501',message='Sem permissão financeira para arquivar este cadastro.';
 end if;
 if p_dimension='category' then
   perform pg_advisory_xact_lock(hashtextextended('apticket.category.'||v_tenant::text,0));
   perform 1 from apticket.financial_categories where id=p_id for update;
   deps:=apticket_finance_private.category_dependencies(v_tenant,p_id);
   if (deps->>'children')::int>0 or (deps->>'active_links')::int>0 then
     raise exception using errcode='23514',message='Arquivamento bloqueado: reorganize as subcategorias e os vínculos ativos primeiro.';
   end if;
   update apticket.financial_categories set is_active=false,deleted_at=clock_timestamp(),updated_by=auth.uid(),updated_at=clock_timestamp() where id=p_id and deleted_at is null;
 else
   update apticket.financial_cost_centers set is_active=false,deleted_at=clock_timestamp(),updated_by=auth.uid(),updated_at=clock_timestamp() where id=p_id and deleted_at is null;
 end if;
 return true;
end $$;


ALTER FUNCTION apticket.archive_financial_dimension(p_dimension text, p_id uuid) OWNER TO supabase_admin;

--
-- Name: archive_supplier_approval_policy(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_supplier_approval_policy(p_policy_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_approval_policies; begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into p from apticket.supplier_approval_policies
    where id=p_policy_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Alcada nao encontrada.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para arquivar alcadas.';
  end if;
  if exists(select 1 from apticket.supplier_payable_approval_requests
    where policy_id=p.id and status='pending') then
    raise exception using errcode='23514',message='Conclua as aprovacoes pendentes antes de arquivar esta alcada.';
  end if;
  update apticket.supplier_approval_policies set is_active=false,deleted_at=clock_timestamp(),
    updated_by=auth.uid(),updated_at=clock_timestamp() where id=p.id;
  return true;
end $$;


ALTER FUNCTION apticket.archive_supplier_approval_policy(p_policy_id uuid) OWNER TO supabase_admin;

--
-- Name: archive_supplier_bank_account(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_supplier_bank_account(p_bank_account_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare a apticket.supplier_bank_accounts; v_next uuid; begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into a from apticket.supplier_bank_accounts where id=p_bank_account_id
    and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Dado bancario nao encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(a.tenant_id,a.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para arquivar dados bancarios.';
  end if;
  if exists(select 1 from apticket.supplier_payments where bank_account_id=a.id and status='scheduled') then
    raise exception using errcode='23514',message='Este dado bancario possui pagamento programado.';
  end if;
  update apticket.supplier_bank_accounts set is_default=false,is_active=false,
    deleted_at=clock_timestamp(),updated_by=auth.uid(),updated_at=clock_timestamp() where id=a.id;
  if a.is_default then
    select id into v_next from apticket.supplier_bank_accounts where supplier_id=a.supplier_id
      and is_active and deleted_at is null order by created_at limit 1 for update;
    if found then update apticket.supplier_bank_accounts set is_default=true,updated_by=auth.uid(),
      updated_at=clock_timestamp() where id=v_next; end if;
  end if;
  return true;
end $$;


ALTER FUNCTION apticket.archive_supplier_bank_account(p_bank_account_id uuid) OWNER TO supabase_admin;

--
-- Name: archive_supplier_contract(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.archive_supplier_contract(p_contract_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare contract apticket.supplier_contracts; begin
  select * into contract from apticket.supplier_contracts
    where id=p_contract_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Contrato de fornecedor nao encontrado.'; end if;
  if auth.uid() is null
    or not apticket.has_financial_scope(contract.tenant_id,contract.operating_company_id,true)
    or not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para excluir este contrato.';
  end if;
  if exists(select 1 from apticket.supplier_payables where supplier_contract_id=contract.id) then
    raise exception using errcode='23514',message='Este contrato possui medicoes e nao pode ser excluido.';
  end if;
  update apticket.supplier_contracts set status='cancelled',is_active=false,
    deleted_at=clock_timestamp(),updated_by=auth.uid(),updated_at=clock_timestamp()
    where id=contract.id;
  return true;
end
$$;


ALTER FUNCTION apticket.archive_supplier_contract(p_contract_id uuid) OWNER TO supabase_admin;

--
-- Name: atualizar_cobrancas_vencidas(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.atualizar_cobrancas_vencidas() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid := apticket.current_tenant_id();
  v_avulsas integer := 0;
  v_medicoes integer := 0;
begin
  if v_tenant is null
     or not apticket.has_permission(auth.uid(), 'financeiro', 'view') then
    raise exception 'Sem permissÃ£o para atualizar cobranÃ§as vencidas';
  end if;

  update apticket.tickets_cobranca_avulsa
  set status_cobranca = 'vencido', updated_at = now()
  where tenant_id = v_tenant
    and status_cobranca = 'faturado'
    and vencimento_em < current_date
    and deleted_at is null;
  get diagnostics v_avulsas = row_count;

  update apticket.contas_receber
  set status_cobranca = 'vencido', updated_at = now()
  where tenant_id = v_tenant
    and status_cobranca = 'faturado'
    and vencimento_em < current_date
    and deleted_at is null;
  get diagnostics v_medicoes = row_count;

  return v_avulsas + v_medicoes;
end
$$;


ALTER FUNCTION apticket.atualizar_cobrancas_vencidas() OWNER TO postgres;

