--

CREATE TABLE apticket.medicoes_contrato (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    contrato_id uuid NOT NULL,
    numero_contrato text NOT NULL,
    cliente_nome text NOT NULL,
    tipo_contrato_nome text,
    competencia date NOT NULL,
    data_medicao date DEFAULT CURRENT_DATE NOT NULL,
    modelo_cobranca text NOT NULL,
    valor_total numeric(14,2) NOT NULL,
    emite_nf boolean NOT NULL,
    emite_boleto boolean NOT NULL,
    data_vencimento date NOT NULL,
    status apticket.status_medicao_contrato DEFAULT 'gerada'::apticket.status_medicao_contrato NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    report_token uuid DEFAULT gen_random_uuid() NOT NULL,
    aprovada_em timestamp with time zone,
    aprovada_por uuid,
    aprovada_por_nome text,
    cancelada_em timestamp with time zone,
    cancelada_por uuid,
    cancelada_por_nome text,
    justificativa_cancelamento text,
    operating_company_id uuid NOT NULL,
    billing_type text NOT NULL,
    collection_type text NOT NULL,
    CONSTRAINT contract_measurements_billing_type_check CHECK ((billing_type = ANY (ARRAY['service_invoice'::text, 'invoice'::text, 'simple_receipt'::text]))),
    CONSTRAINT contract_measurements_collection_type_check CHECK ((collection_type = ANY (ARRAY['boleto_pf'::text, 'boleto_inter_pj'::text, 'carteira'::text]))),
    CONSTRAINT medicoes_contrato_competencia_primeiro_dia_check CHECK ((competencia = (date_trunc('month'::text, (competencia)::timestamp with time zone))::date)),
    CONSTRAINT medicoes_contrato_modelo_cobranca_check CHECK ((modelo_cobranca = ANY (ARRAY['hours_package'::text, 'per_equipment'::text, 'per_service'::text]))),
    CONSTRAINT medicoes_contrato_valor_total_check CHECK ((valor_total >= (0)::numeric))
);


