--
-- Name: atualizar_status_medicao_contrato(uuid, apticket.status_medicao_contrato); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.atualizar_status_medicao_contrato(p_medicao_id uuid, p_status apticket.status_medicao_contrato) RETURNS apticket.medicoes_contrato
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
declare
  v_tenant_id uuid := apticket.current_tenant_id();
  v_medicao apticket.medicoes_contrato;
begin
  if auth.uid() is null
    or v_tenant_id is null
    or not apticket.has_permission(auth.uid(), 'contratos', 'edit') then
    raise exception using errcode = '42501', message = 'Sem permissão para alterar o status da medição.';
  end if;

  select * into v_medicao
  from apticket.medicoes_contrato
  where id = p_medicao_id
    and tenant_id = v_tenant_id
    and deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'Medição não encontrada.';
  end if;

  if v_medicao.status = 'cancelada' then
    raise exception using errcode = '22023', message = 'Uma medição cancelada não pode mudar de status.';
  end if;

  if v_medicao.status = 'faturada' and p_status = 'gerada' then
    raise exception using errcode = '22023', message = 'Uma medição faturada não pode voltar para gerada.';
  end if;

  update apticket.medicoes_contrato
  set status = p_status
  where id = p_medicao_id
  returning * into v_medicao;

  return v_medicao;
end
$$;


ALTER FUNCTION apticket.atualizar_status_medicao_contrato(p_medicao_id uuid, p_status apticket.status_medicao_contrato) OWNER TO postgres;

--
-- Name: auditar_cobranca_avulsa(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.auditar_cobranca_avulsa() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if row(
    old.valor_final, old.status_cobranca, old.vencimento_em, old.observacoes,
    old.justificativa_ajuste, old.revisado_em
  ) is distinct from row(
    new.valor_final, new.status_cobranca, new.vencimento_em, new.observacoes,
    new.justificativa_ajuste, new.revisado_em
  ) then
    insert into apticket.tickets_cobranca_avulsa_audit (
      cobranca_id, tenant_id, actor_id, valores_anteriores, valores_novos
    ) values (
      new.id,
      new.tenant_id,
      auth.uid(),
      jsonb_build_object(
        'valor_final', old.valor_final,
        'status_cobranca', old.status_cobranca,
        'vencimento_em', old.vencimento_em,
        'observacoes', old.observacoes,
        'justificativa_ajuste', old.justificativa_ajuste,
        'revisado_em', old.revisado_em
      ),
      jsonb_build_object(
        'valor_final', new.valor_final,
        'status_cobranca', new.status_cobranca,
        'vencimento_em', new.vencimento_em,
        'observacoes', new.observacoes,
        'justificativa_ajuste', new.justificativa_ajuste,
        'revisado_em', new.revisado_em
      )
    );
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket.auditar_cobranca_avulsa() OWNER TO postgres;

