--
-- Name: calcular_vencimento_medicao(date, apticket.tipo_vencimento_contrato, smallint, uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.calcular_vencimento_medicao(p_competencia date, p_tipo_vencimento apticket.tipo_vencimento_contrato, p_dia_vencimento smallint, p_tenant_id uuid) RETURNS date
    LANGUAGE plpgsql STABLE STRICT
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
declare
  v_inicio_mes date := date_trunc('month', p_competencia)::date;
  v_ultimo_dia date := (v_inicio_mes + interval '1 month - 1 day')::date;
  v_data date;
  v_dias_uteis integer := 0;
begin
  if p_dia_vencimento not between 1 and 31 then
    raise exception using errcode = '22023', message = 'O dia de vencimento deve estar entre 1 e 31.';
  end if;

  if p_tipo_vencimento = 'fixo' then
    return make_date(
      extract(year from v_inicio_mes)::integer,
      extract(month from v_inicio_mes)::integer,
      least(p_dia_vencimento::integer, extract(day from v_ultimo_dia)::integer)
    );
  end if;

  v_data := v_inicio_mes;
  loop
    if apticket.eh_dia_util(v_data, p_tenant_id) then
      v_dias_uteis := v_dias_uteis + 1;
      if v_dias_uteis = p_dia_vencimento then
        return v_data;
      end if;
    end if;
    v_data := v_data + 1;
  end loop;

  return v_data;
end
$$;


ALTER FUNCTION apticket.calcular_vencimento_medicao(p_competencia date, p_tipo_vencimento apticket.tipo_vencimento_contrato, p_dia_vencimento smallint, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: cancel_supplier_payment(uuid, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.cancel_supplier_payment(p_payment_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare pay apticket.supplier_payments; v_name text; begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into pay from apticket.supplier_payments where id=p_payment_id for update;
  if not found then raise exception using errcode='P0002',message='Pagamento programado nao encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(pay.tenant_id,pay.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para cancelar pagamentos.';
  end if;
  if pay.status<>'scheduled' then
    raise exception using errcode='23514',message='Somente pagamentos programados podem ser cancelados.';
  end if;
  if length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception using errcode='23514',message='Informe o motivo do cancelamento.';
  end if;
  select name into v_name from apticket.profiles where id=auth.uid() and tenant_id=pay.tenant_id and is_active;
  update apticket.supplier_payments set status='cancelled',cancelled_at=clock_timestamp(),
    cancelled_by=auth.uid(),cancelled_by_name=v_name,cancellation_reason=btrim(p_reason),
    updated_at=clock_timestamp() where id=pay.id;
  return true;
end $$;


ALTER FUNCTION apticket.cancel_supplier_payment(p_payment_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: cancelar_medicao_contrato_confirmada(uuid, text, uuid, uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.cancelar_medicao_contrato_confirmada(p_medicao_id uuid, p_justificativa text, p_actor_id uuid, p_tenant_id uuid) RETURNS apticket.medicoes_contrato
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
declare
  v_medicao apticket.medicoes_contrato;
  v_actor_nome text;
  v_justificativa text := btrim(coalesce(p_justificativa, ''));
begin
  if char_length(v_justificativa) not between 10 and 1000 then
    raise exception using errcode = '22023', message = 'A justificativa deve ter entre 10 e 1000 caracteres.';
  end if;

  select profile.name into v_actor_nome
  from apticket.profiles as profile
  where profile.id = p_actor_id
    and profile.tenant_id = p_tenant_id
    and profile.is_active;

  if v_actor_nome is null
    or not apticket.has_permission(p_actor_id, 'contratos', 'edit') then
    raise exception using errcode = '42501', message = 'UsuÃ¡rio sem permissÃ£o para cancelar a mediÃ§Ã£o.';
  end if;

  select * into v_medicao
  from apticket.medicoes_contrato
  where id = p_medicao_id
    and tenant_id = p_tenant_id
    and deleted_at is null
  for update;

  if not found then
    raise exception using errcode = 'P0002', message = 'MediÃ§Ã£o nÃ£o encontrada.';
  end if;

  if v_medicao.status <> 'gerada' then
    raise exception using errcode = '22023', message = 'Somente uma mediÃ§Ã£o gerada pode ser cancelada.';
  end if;

  update apticket.medicoes_contrato
  set status = 'cancelada',
      cancelada_em = now(),
      cancelada_por = p_actor_id,
      cancelada_por_nome = v_actor_nome,
      justificativa_cancelamento = v_justificativa
  where id = p_medicao_id
  returning * into v_medicao;

  return v_medicao;
end
$$;


ALTER FUNCTION apticket.cancelar_medicao_contrato_confirmada(p_medicao_id uuid, p_justificativa text, p_actor_id uuid, p_tenant_id uuid) OWNER TO postgres;

--
-- Name: automation_dispatch_outbox; Type: TABLE; Schema: apticket; Owner: supabase_admin
--

CREATE TABLE apticket.automation_dispatch_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    trigger_id text NOT NULL,
    company_id uuid NOT NULL,
    related_entity_id uuid NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_count integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT now() NOT NULL,
    claimed_at timestamp with time zone,
    finished_at timestamp with time zone,
    last_error text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT automation_dispatch_outbox_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT automation_dispatch_outbox_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'done'::text, 'error'::text])))
);


ALTER TABLE apticket.automation_dispatch_outbox OWNER TO supabase_admin;

--
-- Name: TABLE automation_dispatch_outbox; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON TABLE apticket.automation_dispatch_outbox IS 'Outbox durável consumida pelo dispatcher genérico de automações da API.';


--
-- Name: claim_automation_dispatches(integer); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.claim_automation_dispatches(p_limit integer DEFAULT 25) RETURNS SETOF apticket.automation_dispatch_outbox
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  return query
  with picked as (
    select id from apticket.automation_dispatch_outbox
    where deleted_at is null
      and status = 'pending'
      and available_at <= now()
    order by created_at
    for update skip locked
    limit greatest(1, least(coalesce(p_limit, 25), 100))
  )
  update apticket.automation_dispatch_outbox outbox
     set status = 'processing', claimed_at = now(), attempt_count = attempt_count + 1
    from picked
   where outbox.id = picked.id
  returning outbox.*;
end $$;


ALTER FUNCTION apticket.claim_automation_dispatches(p_limit integer) OWNER TO supabase_admin;

