--
-- Name: classificar_ticket_antes_insert(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.classificar_ticket_antes_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_result record;
begin
  select * into v_result
  from apticket.resolver_atendimento_ticket(
    new.tenant_id, new.company_id, new.equipment_id, coalesce(new.created_at, now())
  );

  new.tipo_atendimento := v_result.tipo;
  new.motivo_avulso := v_result.motivo;
  new.contract_id := v_result.contrato_id;
  new.sla_policy_id := v_result.sla_id;
  if new.tipo_atendimento = 'avulso' then
    new.sla_first_response_due_at := null;
    new.sla_resolution_due_at := null;
    new.sla_breached := false;
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket.classificar_ticket_antes_insert() OWNER TO postgres;

--
-- Name: classify_financial_entry(text, uuid, uuid, uuid, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.classify_financial_entry(p_source_type text, p_source_id uuid, p_category_id uuid, p_cost_center_id uuid, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid; v_company uuid; v_direction text; v_actual_type text; v_module text;
  category apticket.financial_categories; center apticket.financial_cost_centers;
  v_actor_name text; v_id uuid:=gen_random_uuid();
begin
  if p_source_type in ('measurement_receivable','recurring_receivable','manual_receivable') then
    select r.tenant_id,r.operating_company_id,
      case r.origin_type when 'measurement' then 'measurement_receivable'
        when 'manual' then 'manual_receivable' else 'recurring_receivable' end
      into v_tenant,v_company,v_actual_type from apticket.contas_receber r
      where r.id=p_source_id and r.deleted_at is null for update;
    v_direction:='inflow'; v_module:='financeiro_contas_receber';
  elsif p_source_type='supplier_payable' then
    select p.tenant_id,p.operating_company_id,'supplier_payable' into v_tenant,v_company,v_actual_type
      from apticket.supplier_payables p where p.id=p_source_id and p.deleted_at is null for update;
    v_direction:='outflow'; v_module:='financeiro_contas_pagar';
  elsif p_source_type='bank_transaction' then
    select transaction.tenant_id,transaction.operating_company_id,'bank_transaction',
      case when transaction.amount>0 then 'inflow' else 'outflow' end
      into v_tenant,v_company,v_actual_type,v_direction
      from apticket.bank_statement_transactions transaction
      where transaction.id=p_source_id and transaction.deleted_at is null for update;
    v_module:='financeiro_bancos';
  else raise exception using errcode='22023',message='Origem financeira invalida.';
  end if;
  if v_tenant is null or v_company is null or v_actual_type<>p_source_type then
    raise exception using errcode='P0002',message='Movimento financeiro nao encontrado nesta origem.';
  end if;
  if auth.uid() is null or not apticket.has_financial_scope(v_tenant,v_company,true) or not (
    apticket.has_permission(auth.uid(),v_module,'edit')
    or apticket.has_permission(auth.uid(),'financeiro_fluxo_caixa','edit')
  ) then raise exception using errcode='42501',message='Sem permissao financeira para classificar este movimento.';
  end if;
  select * into category from apticket.financial_categories where id=p_category_id
    and tenant_id=v_tenant and (operating_company_id=v_company or is_global)
    and classification_type='analytic' and is_active and deleted_at is null;
  if not found or category.direction not in (v_direction,'both') then
    raise exception using errcode='23514',message='Selecione uma categoria analitica ativa compativel com o movimento.';
  end if;
  select * into center from apticket.financial_cost_centers where id=p_cost_center_id
    and tenant_id=v_tenant and (operating_company_id=v_company or is_global)
    and classification_type='analytic' and is_active and deleted_at is null;
  if not found then
    raise exception using errcode='23514',message='Selecione um centro de custo analitico ativo desta empresa.';
  end if;
  select name into v_actor_name from apticket.profiles where id=auth.uid() and tenant_id=v_tenant and is_active;
  if v_actor_name is null then raise exception using errcode='42501',message='Usuario responsavel nao esta ativo.'; end if;
  update apticket.financial_entry_classifications set replaced_at=clock_timestamp()
    where source_type=p_source_type and source_id=p_source_id and replaced_at is null;
  insert into apticket.financial_entry_classifications(id,tenant_id,operating_company_id,source_type,
    source_id,direction,financial_category_id,financial_category_code,financial_category_name,
    cost_center_id,cost_center_code,cost_center_name,notes,classified_by,classified_by_name)
  values(v_id,v_tenant,v_company,p_source_type,p_source_id,v_direction,category.id,category.code,
    category.name,center.id,center.code,center.name,nullif(btrim(p_notes),''),auth.uid(),v_actor_name);
  return v_id;
end $$;


ALTER FUNCTION apticket.classify_financial_entry(p_source_type text, p_source_id uuid, p_category_id uuid, p_cost_center_id uuid, p_notes text) OWNER TO supabase_admin;

--
-- Name: classify_financial_entry_allocated(text, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.classify_financial_entry_allocated(p_source_type text, p_source_id uuid, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid; v_company uuid; v_actual_type text; v_direction text; v_module text;
  v_categories jsonb; v_centers jsonb; v_category jsonb; v_center jsonb;
  v_actor_name text; v_id uuid:=gen_random_uuid();
begin
  if auth.uid() is null or apticket.current_tenant_id() is null then
    raise exception using errcode='42501',message='Sem permissão para classificar este movimento.';
  end if;
  if p_source_type in ('measurement_receivable','recurring_receivable','manual_receivable') then
    select r.tenant_id,r.operating_company_id,
      case r.origin_type when 'measurement' then 'measurement_receivable'
        when 'manual' then 'manual_receivable' else 'recurring_receivable' end
      into v_tenant,v_company,v_actual_type from apticket.contas_receber r
      where r.id=p_source_id and r.tenant_id=apticket.current_tenant_id() and r.deleted_at is null for update;
    v_direction:='inflow'; v_module:='financeiro_contas_receber';
  elsif p_source_type='supplier_payable' then
    select p.tenant_id,p.operating_company_id,'supplier_payable' into v_tenant,v_company,v_actual_type
      from apticket.supplier_payables p where p.id=p_source_id and p.tenant_id=apticket.current_tenant_id() and p.deleted_at is null for update;
    v_direction:='outflow'; v_module:='financeiro_contas_pagar';
  elsif p_source_type='bank_transaction' then
    select t.tenant_id,t.operating_company_id,'bank_transaction',case when t.amount>0 then 'inflow' else 'outflow' end
      into v_tenant,v_company,v_actual_type,v_direction from apticket.bank_statement_transactions t
      where t.id=p_source_id and t.tenant_id=apticket.current_tenant_id() and t.deleted_at is null for update;
    v_module:='financeiro_bancos';
  else
    raise exception using errcode='22023',message='Origem financeira inválida.';
  end if;
  if v_tenant is null or v_company is null or v_actual_type<>p_source_type then
    raise exception using errcode='P0002',message='Movimento financeiro não encontrado nesta origem.';
  end if;
  if not apticket.has_financial_scope(v_tenant,v_company,true) or not (
    apticket.has_permission(auth.uid(),v_module,'edit')
    or apticket.has_permission(auth.uid(),'financeiro_fluxo_caixa','edit')
  ) then raise exception using errcode='42501',message='Sem permissão financeira para classificar este movimento.'; end if;
  select name into v_actor_name from apticket.profiles where id=auth.uid() and tenant_id=v_tenant and is_active;
  if v_actor_name is null then raise exception using errcode='42501',message='Usuário responsável não está ativo.'; end if;
  v_categories:=apticket_finance_private.normalize_contract_allocation(p_category_allocations,'category',v_tenant,v_company,v_direction);
  v_centers:=apticket_finance_private.normalize_contract_allocation(p_cost_center_allocations,'cost_center',v_tenant,v_company,v_direction);
  select value into v_category from jsonb_array_elements(v_categories) order by (value->>'percentage')::numeric desc,value->>'item_id' limit 1;
  select value into v_center from jsonb_array_elements(v_centers) order by (value->>'percentage')::numeric desc,value->>'item_id' limit 1;
  update apticket.financial_entry_classifications set replaced_at=clock_timestamp()
    where source_type=p_source_type and source_id=p_source_id and replaced_at is null;
  insert into apticket.financial_entry_classifications(id,tenant_id,operating_company_id,source_type,source_id,direction,
    financial_category_id,financial_category_code,financial_category_name,cost_center_id,cost_center_code,cost_center_name,
    notes,classified_by,classified_by_name,category_allocations,cost_center_allocations)
  values(v_id,v_tenant,v_company,p_source_type,p_source_id,v_direction,
    (v_category->>'item_id')::uuid,v_category->>'code',v_category->>'name',
    (v_center->>'item_id')::uuid,v_center->>'code',v_center->>'name',nullif(btrim(p_notes),''),auth.uid(),v_actor_name,v_categories,v_centers);
  return v_id;
end $$;


ALTER FUNCTION apticket.classify_financial_entry_allocated(p_source_type text, p_source_id uuid, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_notes text) OWNER TO supabase_admin;

--
-- Name: FUNCTION classify_financial_entry_allocated(p_source_type text, p_source_id uuid, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_notes text); Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON FUNCTION apticket.classify_financial_entry_allocated(p_source_type text, p_source_id uuid, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_notes text) IS 'Classificação versionada com rateios de categorias e centros independentes, cada grupo totalizando 100%; usa a mesma normalização dos contratos.';


--
-- Name: clear_financial_budget_entry(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.clear_financial_budget_entry(p_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare entry apticket.financial_budget_entries; begin
  if not apticket.has_permission(auth.uid(),'financeiro_planejamento','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into entry from apticket.financial_budget_entries
    where id=p_id and replaced_at is null for update;
  if not found then
    raise exception using errcode='P0002',message='Item vigente do orcamento nao encontrado.';
  end if;
  if auth.uid() is null
    or not apticket.has_financial_scope(entry.tenant_id,entry.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para remover este orcamento.';
  end if;
  update apticket.financial_budget_entries set replaced_at=clock_timestamp() where id=entry.id;
  return true;
end $$;


ALTER FUNCTION apticket.clear_financial_budget_entry(p_id uuid) OWNER TO supabase_admin;

--
-- Name: clear_financial_entry_classification(text, uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.clear_financial_entry_classification(p_source_type text, p_source_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c apticket.financial_entry_classifications; v_module text; begin
  select * into c from apticket.financial_entry_classifications where source_type=p_source_type
    and source_id=p_source_id and replaced_at is null for update;
  if not found then
    raise exception using errcode='P0002',message='Classificacao atual nao encontrada.';
  end if;
  v_module:=case
    when p_source_type in ('measurement_receivable','recurring_receivable','manual_receivable')
      then 'financeiro_contas_receber'
    when p_source_type='supplier_payable' then 'financeiro_contas_pagar'
    when p_source_type='bank_transaction' then 'financeiro_bancos'
    else null end;
  if v_module is null or auth.uid() is null
    or not apticket.has_financial_scope(c.tenant_id,c.operating_company_id,true)
    or not (
      apticket.has_permission(auth.uid(),v_module,'edit')
      or apticket.has_permission(auth.uid(),'financeiro_fluxo_caixa','edit')
    ) then
    raise exception using errcode='42501',message='Sem permissao financeira para remover esta classificacao.';
  end if;
  update apticket.financial_entry_classifications set replaced_at=clock_timestamp() where id=c.id;
  return true;
end
$$;


ALTER FUNCTION apticket.clear_financial_entry_classification(p_source_type text, p_source_id uuid) OWNER TO supabase_admin;

--
-- Name: close_billing_cycles(uuid, date, integer); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.close_billing_cycles(p_contract_id uuid DEFAULT NULL::uuid, p_as_of date DEFAULT NULL::date, p_limit integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare r record; v_id uuid; v_count integer:=0; v_errors jsonb:='[]'; v_today date:=(now() at time zone 'America/Sao_Paulo')::date;
begin
  if p_limit is null or p_limit<1 or p_limit>100 or coalesce(p_as_of,v_today)>v_today then
    raise exception using errcode='22023',message='Limite deve estar entre 1 e 100 e a data não pode estar no futuro.';
  end if;
  for r in select contract_id from apticket.contract_financial_terms
    where billing_enabled and deleted_at is null and (p_contract_id is null or contract_id=p_contract_id) order by contract_id loop
    loop
      exit when v_count>=p_limit;
      begin
        v_id:=apticket_finance_private.close_next_cycle(r.contract_id,coalesce(p_as_of,v_today));
        exit when v_id is null;
        v_count:=v_count+1;
      exception when others then
        -- Subtransação por ciclo: não deixa cabeçalho/itens/recebível pela metade.
        v_errors:=v_errors||jsonb_build_array(jsonb_build_object('contract_id',r.contract_id,'code',sqlstate,'message',sqlerrm));
        exit;
      end;
    end loop;
    exit when v_count>=p_limit;
  end loop;
  return jsonb_build_object('generated',v_count,'errors',v_errors,'limit_reached',v_count>=p_limit);
end $$;


ALTER FUNCTION apticket.close_billing_cycles(p_contract_id uuid, p_as_of date, p_limit integer) OWNER TO postgres;

