--
-- Name: confirmar_previsao_conta_fixa(uuid, integer, jsonb); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.confirmar_previsao_conta_fixa(p_id uuid, p_expected_revision integer, p_payload jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare o apticket.fixed_payable_occurrences; v jsonb; v_group uuid; v_payable uuid; v_due date:=(p_payload->>'due_date')::date;
begin
  o:=apticket_finance_private.lock_fixed_occurrence(p_id,p_expected_revision);
  v:=apticket_finance_private.normalize_fixed_payload(o.tenant_id,o.operating_company_id,p_payload);
  v_group:=apticket.create_manual_supplier_payable_allocated(o.operating_company_id,(v->>'supplier_id')::uuid,(v->>'document_type_id')::uuid,
    p_payload->>'document_number',v->>'description',o.competence,(v->>'total_amount')::numeric,
    jsonb_build_array(jsonb_build_object('number',1,'due_date',v_due,'amount',(v->>'total_amount')::numeric)),v->'category_allocations',v->'cost_center_allocations',0,v->>'notes');
  perform apticket_finance_private.link_payable_attachments(v_group,coalesce(p_payload->'attachments','[]'::jsonb));
  select id into strict v_payable from apticket.supplier_payables where manual_entry_group_id=v_group;
  update apticket.fixed_payable_occurrences set status='confirmed',confirmed_payable_id=v_payable,confirmed_at=clock_timestamp(),confirmed_by=auth.uid(),
    supplier_id=(v->>'supplier_id')::uuid,supplier_name=v->>'supplier_name',document_type_id=(v->>'document_type_id')::uuid,
    description=v->>'description',total_amount=(v->>'total_amount')::numeric,due_date=v_due,
    category_allocations=v->'category_allocations',cost_center_allocations=v->'cost_center_allocations',notes=v->>'notes' where id=o.id;
  return v_payable;
end $$;


ALTER FUNCTION apticket.confirmar_previsao_conta_fixa(p_id uuid, p_expected_revision integer, p_payload jsonb) OWNER TO supabase_admin;

--
-- Name: create_employee_with_position(jsonb, text, text, numeric); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_employee_with_position(p_data jsonb, p_cargo text, p_nivel text, p_salario numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  tenant uuid := apticket.current_tenant_id();
  employee_id uuid := gen_random_uuid();
  operator_id uuid;
  admission date;
begin
  if auth.uid() is null
    or tenant is null
    or not apticket.has_permission(auth.uid(), 'funcionarios', 'create') then
    raise exception using errcode = '42501', message = 'Sem permissão para cadastrar funcionários.';
  end if;

  operator_id := (p_data->>'operating_company_id')::uuid;
  admission := (p_data->>'data_admissao')::date;

  if not exists (
    select 1
    from apticket.operating_companies
    where id = operator_id
      and tenant_id = tenant
      and is_active
      and deleted_at is null
  ) then
    raise exception using errcode = '23514', message = 'Empresa operadora inválida.';
  end if;

  insert into apticket.funcionarios (
    id, tenant_id, operating_company_id, nome_completo, nome_social, cpf, rg,
    rg_orgao_emissor, data_nascimento, sexo, estado_civil, nacionalidade,
    naturalidade_cidade, naturalidade_uf, nome_mae, nome_pai, pis_pasep,
    ctps_numero, ctps_serie, ctps_uf, titulo_eleitor, certificado_reservista,
    email_pessoal, email_corporativo, telefone_principal, telefone_secundario,
    matricula, departamento, centro_custo_id, data_admissao, tipo_contrato,
    regime_jornada, carga_horaria_semanal, status, gestor_responsavel_id,
    observacoes, created_by, updated_by
  ) values (
    employee_id, tenant, operator_id, btrim(p_data->>'nome_completo'),
    nullif(btrim(p_data->>'nome_social'), ''),
    nullif(btrim(p_data->>'cpf'), ''),
    nullif(btrim(p_data->>'rg'), ''),
    nullif(btrim(p_data->>'rg_orgao_emissor'), ''),
    nullif(p_data->>'data_nascimento', '')::date,
    nullif(p_data->>'sexo', ''),
    nullif(p_data->>'estado_civil', ''),
    coalesce(nullif(btrim(p_data->>'nacionalidade'), ''), 'Brasileira'),
    nullif(btrim(p_data->>'naturalidade_cidade'), ''),
    nullif(p_data->>'naturalidade_uf', ''),
    nullif(btrim(p_data->>'nome_mae'), ''),
    nullif(btrim(p_data->>'nome_pai'), ''),
    nullif(p_data->>'pis_pasep', ''),
    nullif(btrim(p_data->>'ctps_numero'), ''),
    nullif(btrim(p_data->>'ctps_serie'), ''),
    nullif(p_data->>'ctps_uf', ''),
    nullif(btrim(p_data->>'titulo_eleitor'), ''),
    nullif(btrim(p_data->>'certificado_reservista'), ''),
    nullif(lower(btrim(p_data->>'email_pessoal')), ''),
    nullif(lower(btrim(p_data->>'email_corporativo')), ''),
    nullif(btrim(p_data->>'telefone_principal'), ''),
    nullif(btrim(p_data->>'telefone_secundario'), ''),
    coalesce(nullif(btrim(p_data->>'matricula'), ''), ''),
    nullif(btrim(p_data->>'departamento'), ''),
    nullif(p_data->>'centro_custo_id', '')::uuid,
    admission,
    p_data->>'tipo_contrato',
    p_data->>'regime_jornada',
    nullif(p_data->>'carga_horaria_semanal', '')::numeric,
    'ativo',
    nullif(p_data->>'gestor_responsavel_id', '')::uuid,
    nullif(p_data->>'observacoes', ''),
    auth.uid(),
    auth.uid()
  );

  insert into apticket.funcionario_cargos_salarios (
    tenant_id, funcionario_id, cargo, nivel, salario_base, tipo_alteracao,
    motivo, vigente_de, created_by
  ) values (
    tenant, employee_id, btrim(p_cargo), nullif(btrim(p_nivel), ''), p_salario,
    'admissao', 'Cargo e salário de admissão', admission, auth.uid()
  );

  return employee_id;
end
$$;


ALTER FUNCTION apticket.create_employee_with_position(p_data jsonb, p_cargo text, p_nivel text, p_salario numeric) OWNER TO supabase_admin;

--
-- Name: create_financial_category(uuid, uuid, text, text, text, boolean, boolean, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_financial_category(p_operating_company_id uuid, p_parent_id uuid, p_name text, p_direction text, p_description text DEFAULT NULL::text, p_is_global boolean DEFAULT false, p_is_active boolean DEFAULT true, p_classification_type text DEFAULT 'analytic'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare v_tenant uuid; parent_row apticket.financial_categories; v_code text; v_next int;
begin
 select tenant_id into v_tenant from apticket.operating_companies where id=p_operating_company_id and deleted_at is null;
 if auth.uid() is null or v_tenant is distinct from apticket.current_tenant_id()
 or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true)
 or not apticket.has_permission(auth.uid(),'financeiro_fluxo_caixa','edit') then
   raise exception using errcode='42501',message='Sem permissão financeira para cadastrar categorias.';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('apticket.category.'||v_tenant::text,0));
 if p_parent_id is null then
   select coalesce(max(code::int),0)+1 into v_next from apticket.financial_categories
     where tenant_id=v_tenant and code ~ '^[0-9]{2}$';
   if v_next>99 then raise exception using errcode='23514',message='Limite de grupos atingido.'; end if;
   v_code:=lpad(v_next::text,2,'0');
 else
   select * into parent_row from apticket.financial_categories where id=p_parent_id and tenant_id=v_tenant
     and deleted_at is null and is_active and classification_type='synthetic'
     and (is_global or operating_company_id=p_operating_company_id) for share;
   if not found or parent_row.code !~ '^([0-9]{2}|[0-9]{2}\.[0-9]{2})$' then
     raise exception using errcode='23514',message='Selecione um agrupamento ativo de primeiro ou segundo nível.';
   end if;
   select coalesce(max(split_part(code,'.',case when length(parent_row.code)=2 then 2 else 3 end)::int),0)+1
     into v_next from apticket.financial_categories where tenant_id=v_tenant and code like parent_row.code||'.%';
   if v_next>(case when length(parent_row.code)=2 then 99 else 9999 end) then
     raise exception using errcode='23514',message='Limite de subcategorias atingido para este agrupamento.';
   end if;
   v_code:=parent_row.code||'.'||lpad(v_next::text,case when length(parent_row.code)=2 then 2 else 4 end,'0');
 end if;
 return apticket.save_financial_category(null,p_operating_company_id,v_code,p_name,p_direction,p_description,p_is_global,p_is_active,p_classification_type);
end $_$;


ALTER FUNCTION apticket.create_financial_category(p_operating_company_id uuid, p_parent_id uuid, p_name text, p_direction text, p_description text, p_is_global boolean, p_is_active boolean, p_classification_type text) OWNER TO supabase_admin;

--
-- Name: create_manual_receivable(uuid, uuid, uuid, text, text, date, numeric, jsonb, integer, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_manual_receivable(p_operating_company_id uuid, p_company_id uuid, p_document_type_id uuid, p_document_reference text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_customer apticket.companies;
  v_group_id uuid := gen_random_uuid();
  v_document text := btrim(coalesce(p_document_reference, ''));
  v_description text := btrim(coalesce(p_description, ''));
  v_notes text := nullif(btrim(coalesce(p_notes, '')), '');
  v_competence date := date_trunc('month', p_competence)::date;
  v_total numeric(14,2) := round(p_total_amount, 2);
  v_count integer;
  v_sum numeric(14,2) := 0;
  v_expected integer := 1;
  v_item jsonb;
  v_number integer;
  v_due_date date;
  v_amount numeric(14,2);
  v_child_document text;
begin
  select tenant_id into v_tenant from apticket.operating_companies
  where id = p_operating_company_id and deleted_at is null and is_active for share;
  if not found then
    raise exception using errcode = 'P0002', message = 'Empresa operadora ativa nao encontrada.';
  end if;
  if v_actor is null
    or not apticket.has_permission(v_actor, 'financeiro_contas_receber', 'edit')
    or not apticket.has_financial_scope(v_tenant, p_operating_company_id, true) then
    raise exception using errcode = '42501', message = 'Sem permissao para incluir contas a receber nesta empresa.';
  end if;
  select * into v_customer from apticket.companies
  where id = p_company_id and tenant_id = v_tenant for share;
  if not found then
    raise exception using errcode = 'P0002', message = 'Cliente ativo nao encontrado.';
  end if;
  perform 1 from apticket.financial_document_types
  where id = p_document_type_id and tenant_id = v_tenant and deleted_at is null and is_active
    and availability in ('receivable', 'both') for share;
  if not found then
    raise exception using errcode = '23514', message = 'Selecione um tipo de documento ativo para contas a receber.';
  end if;
  if length(v_document) not between 2 and 80 then
    raise exception using errcode = '23514', message = 'O numero do documento deve ter entre 2 e 80 caracteres.';
  end if;
  if length(v_description) not between 2 and 500 then
    raise exception using errcode = '23514', message = 'A descricao deve ter entre 2 e 500 caracteres.';
  end if;
  if p_competence is null or p_competence <> v_competence then
    raise exception using errcode = '23514', message = 'Informe uma competencia valida.';
  end if;
  if p_total_amount is null or v_total <= 0 or v_total > 999999999.99 then
    raise exception using errcode = '23514', message = 'Informe um valor total entre R$ 0,01 e R$ 999.999.999,99.';
  end if;
  if v_notes is not null and length(v_notes) > 4000 then
    raise exception using errcode = '23514', message = 'As observacoes devem ter no maximo 4.000 caracteres.';
  end if;
  if jsonb_typeof(p_installments) <> 'array' then
    raise exception using errcode = '23514', message = 'Informe as parcelas do lancamento.';
  end if;
  v_count := jsonb_array_length(p_installments);
  if v_count not between 1 and 120 then
    raise exception using errcode = '23514', message = 'A quantidade de parcelas deve estar entre 1 e 120.';
  end if;
  if (v_count = 1 and coalesce(p_installment_interval_days, 0) <> 0)
    or (v_count > 1 and coalesce(p_installment_interval_days, 0) not between 1 and 3650) then
    raise exception using errcode = '23514', message = 'Informe um intervalo valido entre as parcelas.';
  end if;

  for v_item in select value from jsonb_array_elements(p_installments)
  loop
    if coalesce(v_item->>'number', '') !~ '^[0-9]+$'
      or coalesce(v_item->>'due_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
      or coalesce(v_item->>'amount', '') !~ '^\d+(\.\d{1,2})?$' then
      raise exception using errcode = '23514', message = 'Uma das parcelas possui numero, vencimento ou valor invalido.';
    end if;
  end loop;

  for v_item in
    select value from jsonb_array_elements(p_installments)
    order by (value->>'number')::integer
  loop
    v_number := (v_item->>'number')::integer;
    v_due_date := (v_item->>'due_date')::date;
    v_amount := round((v_item->>'amount')::numeric, 2);
    if v_number <> v_expected then
      raise exception using errcode = '23514', message = 'A numeracao das parcelas deve ser sequencial e iniciar em 1.';
    end if;
    if v_due_date < v_competence then
      raise exception using errcode = '23514', message = 'O vencimento das parcelas nao pode anteceder a competencia.';
    end if;
    if v_amount <= 0 or v_amount > 999999999.99 then
      raise exception using errcode = '23514', message = 'Todas as parcelas devem possuir valor maior que zero.';
    end if;
    v_sum := v_sum + v_amount;
    v_expected := v_expected + 1;
  end loop;
  if v_sum <> v_total then
    raise exception using errcode = '23514', message = 'A soma das parcelas deve ser exatamente igual ao valor total do documento.';
  end if;

  insert into apticket.financial_manual_entry_groups(
    id, tenant_id, operating_company_id, direction, company_id, document_type_id,
    document_number, description, competence, total_amount, installment_count,
    installment_interval_days, notes, created_by
  ) values (
    v_group_id, v_tenant, p_operating_company_id, 'receivable', v_customer.id,
    p_document_type_id, v_document, v_description, v_competence, v_total, v_count,
    coalesce(p_installment_interval_days, 0), v_notes, v_actor
  );

  for v_item in
    select value from jsonb_array_elements(p_installments)
    order by (value->>'number')::integer
  loop
    v_number := (v_item->>'number')::integer;
    v_due_date := (v_item->>'due_date')::date;
    v_amount := round((v_item->>'amount')::numeric, 2);
    v_child_document := case when v_count = 1 then v_document
      else format('%s - %s/%s', v_document, v_number, v_count) end;
    if length(v_child_document) > 80 then
      raise exception using errcode = '23514', message = 'O numero do documento e muito longo para identificar as parcelas.';
    end if;
    insert into apticket.contas_receber(
      tenant_id, operating_company_id, medicao_id, billing_cycle_id, contrato_id,
      company_id, cliente_nome, document_type_id, documento_referencia,
      document_base_number, manual_entry_group_id, installment_number, installment_count,
      descricao, competencia, valor_original, valor_aberto, vencimento_em,
      status_cobranca, observacoes, aprovado_em, aprovado_por
    ) values (
      v_tenant, p_operating_company_id, null, null, null,
      v_customer.id, v_customer.name, p_document_type_id, v_child_document,
      v_document, v_group_id, v_number, v_count,
      v_description, v_competence, v_amount, v_amount, v_due_date,
      'a_faturar', v_notes, clock_timestamp(), v_actor
    );
  end loop;
  return v_group_id;
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'Ja existe este documento manual para o cliente e a empresa operadora selecionados.';
end
$_$;


ALTER FUNCTION apticket.create_manual_receivable(p_operating_company_id uuid, p_company_id uuid, p_document_type_id uuid, p_document_reference text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer, p_notes text) OWNER TO supabase_admin;

--
-- Name: create_manual_receivable_allocated(uuid, uuid, uuid, text, text, date, numeric, jsonb, jsonb, jsonb, integer, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_manual_receivable_allocated(p_operating_company_id uuid, p_company_id uuid, p_document_type_id uuid, p_document_reference text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_installment_interval_days integer DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_group uuid; item record;
begin
  v_group:=apticket.create_manual_receivable(p_operating_company_id,p_company_id,p_document_type_id,
    p_document_reference,p_description,p_competence,p_total_amount,p_installments,p_installment_interval_days,p_notes);
  for item in select id from apticket.contas_receber where manual_entry_group_id=v_group loop
    perform apticket.classify_financial_entry_allocated('manual_receivable',item.id,p_category_allocations,p_cost_center_allocations,'Rateios informados no lançamento manual');
  end loop;
  return v_group;
end $$;


ALTER FUNCTION apticket.create_manual_receivable_allocated(p_operating_company_id uuid, p_company_id uuid, p_document_type_id uuid, p_document_reference text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_installment_interval_days integer, p_notes text) OWNER TO supabase_admin;

--
-- Name: create_manual_receivable_classified(uuid, uuid, uuid, text, text, date, numeric, jsonb, integer, text, uuid, uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_manual_receivable_classified(p_operating_company_id uuid, p_company_id uuid, p_document_type_id uuid, p_document_reference text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer DEFAULT 0, p_notes text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_group uuid; item record; begin
  if (p_category_id is null)<>(p_cost_center_id is null) then
    raise exception using errcode='23514',message='Informe a categoria financeira e o centro de custo em conjunto.';
  end if;
  v_group:=apticket.create_manual_receivable(
    p_operating_company_id,p_company_id,p_document_type_id,p_document_reference,p_description,
    p_competence,p_total_amount,p_installments,p_installment_interval_days,p_notes
  );
  if p_category_id is not null then
    for item in select id from apticket.contas_receber where manual_entry_group_id=v_group loop
      perform apticket.classify_financial_entry(
        'manual_receivable',item.id,p_category_id,p_cost_center_id,'Classificacao informada no lancamento manual'
      );
    end loop;
  end if;
  return v_group;
end
$$;


ALTER FUNCTION apticket.create_manual_receivable_classified(p_operating_company_id uuid, p_company_id uuid, p_document_type_id uuid, p_document_reference text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer, p_notes text, p_category_id uuid, p_cost_center_id uuid) OWNER TO supabase_admin;

--
-- Name: create_manual_supplier_payable(uuid, uuid, uuid, text, text, date, numeric, jsonb, integer, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_manual_supplier_payable(p_operating_company_id uuid, p_supplier_id uuid, p_document_type_id uuid, p_document_number text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_tenant uuid;
  v_supplier apticket.suppliers;
  v_group_id uuid := gen_random_uuid();
  v_document text := btrim(coalesce(p_document_number, ''));
  v_description text := btrim(coalesce(p_description, ''));
  v_notes text := nullif(btrim(coalesce(p_notes, '')), '');
  v_competence date := date_trunc('month', p_competence)::date;
  v_total numeric(14,2) := round(p_total_amount, 2);
  v_count integer;
  v_sum numeric(14,2) := 0;
  v_expected integer := 1;
  v_item jsonb;
  v_number integer;
  v_due_date date;
  v_amount numeric(14,2);
  v_child_document text;
begin
  select tenant_id into v_tenant from apticket.operating_companies
  where id = p_operating_company_id and deleted_at is null and is_active for share;
  if not found then
    raise exception using errcode = 'P0002', message = 'Empresa operadora ativa nao encontrada.';
  end if;
  if v_actor is null
    or not apticket.has_permission(v_actor, 'financeiro_contas_pagar', 'edit')
    or not apticket.has_financial_scope(v_tenant, p_operating_company_id, true) then
    raise exception using errcode = '42501', message = 'Sem permissao para incluir contas a pagar nesta empresa.';
  end if;
  select * into v_supplier from apticket.suppliers
  where id = p_supplier_id and tenant_id = v_tenant and deleted_at is null and is_active for share;
  if not found then
    raise exception using errcode = 'P0002', message = 'Fornecedor ativo nao encontrado.';
  end if;
  perform 1 from apticket.financial_document_types
  where id = p_document_type_id and tenant_id = v_tenant and deleted_at is null and is_active
    and availability in ('payable', 'both') for share;
  if not found then
    raise exception using errcode = '23514', message = 'Selecione um tipo de documento ativo para contas a pagar.';
  end if;
  if length(v_document) not between 2 and 80 then
    raise exception using errcode = '23514', message = 'O numero do documento deve ter entre 2 e 80 caracteres.';
  end if;
  if length(v_description) not between 2 and 500 then
    raise exception using errcode = '23514', message = 'A descricao deve ter entre 2 e 500 caracteres.';
  end if;
  if p_competence is null or p_competence <> v_competence then
    raise exception using errcode = '23514', message = 'Informe uma competencia valida.';
  end if;
  if p_total_amount is null or v_total <= 0 or v_total > 999999999.99 then
    raise exception using errcode = '23514', message = 'Informe um valor total entre R$ 0,01 e R$ 999.999.999,99.';
  end if;
  if v_notes is not null and length(v_notes) > 4000 then
    raise exception using errcode = '23514', message = 'As observacoes devem ter no maximo 4.000 caracteres.';
  end if;
  if jsonb_typeof(p_installments) <> 'array' then
    raise exception using errcode = '23514', message = 'Informe as parcelas do lancamento.';
  end if;
  v_count := jsonb_array_length(p_installments);
  if v_count not between 1 and 120 then
    raise exception using errcode = '23514', message = 'A quantidade de parcelas deve estar entre 1 e 120.';
  end if;
  if (v_count = 1 and coalesce(p_installment_interval_days, 0) <> 0)
    or (v_count > 1 and coalesce(p_installment_interval_days, 0) not between 1 and 3650) then
    raise exception using errcode = '23514', message = 'Informe um intervalo valido entre as parcelas.';
  end if;

  for v_item in select value from jsonb_array_elements(p_installments)
  loop
    if coalesce(v_item->>'number', '') !~ '^[0-9]+$'
      or coalesce(v_item->>'due_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
      or coalesce(v_item->>'amount', '') !~ '^\d+(\.\d{1,2})?$' then
      raise exception using errcode = '23514', message = 'Uma das parcelas possui numero, vencimento ou valor invalido.';
    end if;
  end loop;

  for v_item in
    select value from jsonb_array_elements(p_installments)
    order by (value->>'number')::integer
  loop
    v_number := (v_item->>'number')::integer;
    v_due_date := (v_item->>'due_date')::date;
    v_amount := round((v_item->>'amount')::numeric, 2);
    if v_number <> v_expected then
      raise exception using errcode = '23514', message = 'A numeracao das parcelas deve ser sequencial e iniciar em 1.';
    end if;
    if v_due_date < v_competence then
      raise exception using errcode = '23514', message = 'O vencimento das parcelas nao pode anteceder a competencia.';
    end if;
    if v_amount <= 0 or v_amount > 999999999.99 then
      raise exception using errcode = '23514', message = 'Todas as parcelas devem possuir valor maior que zero.';
    end if;
    v_sum := v_sum + v_amount;
    v_expected := v_expected + 1;
  end loop;
  if v_sum <> v_total then
    raise exception using errcode = '23514', message = 'A soma das parcelas deve ser exatamente igual ao valor total do documento.';
  end if;

  insert into apticket.financial_manual_entry_groups(
    id, tenant_id, operating_company_id, direction, supplier_id, document_type_id,
    document_number, description, competence, total_amount, installment_count,
    installment_interval_days, notes, created_by
  ) values (
    v_group_id, v_tenant, p_operating_company_id, 'payable', v_supplier.id,
    p_document_type_id, v_document, v_description, v_competence, v_total, v_count,
    coalesce(p_installment_interval_days, 0), v_notes, v_actor
  );

  for v_item in
    select value from jsonb_array_elements(p_installments)
    order by (value->>'number')::integer
  loop
    v_number := (v_item->>'number')::integer;
    v_due_date := (v_item->>'due_date')::date;
    v_amount := round((v_item->>'amount')::numeric, 2);
    v_child_document := case when v_count = 1 then v_document
      else format('%s - %s/%s', v_document, v_number, v_count) end;
    if length(v_child_document) > 80 then
      raise exception using errcode = '23514', message = 'O numero do documento e muito longo para identificar as parcelas.';
    end if;
    insert into apticket.supplier_payables(
      tenant_id, operating_company_id, supplier_id, supplier_contract_id,
      document_type_id, document_number, document_base_number, manual_entry_group_id,
      installment_number, installment_count, description, cycle_start, cycle_end,
      due_date, billing_unit, measured_quantity, unit_price, total_amount,
      allocation_status, status, terms_snapshot, created_by
    ) values (
      v_tenant, p_operating_company_id, v_supplier.id, null,
      p_document_type_id, v_child_document, v_document, v_group_id,
      v_number, v_count, v_description, v_competence, (v_competence + interval '1 month')::date,
      v_due_date, 'fixed', 1, v_amount, v_amount,
      'complete', 'scheduled', jsonb_build_object(
        'origin', 'manual',
        'supplier_name', coalesce(v_supplier.trade_name, v_supplier.legal_name),
        'supplier_tax_id', v_supplier.tax_id,
        'document_type_id', p_document_type_id,
        'document_base_number', v_document,
        'installment_number', v_number,
        'installment_count', v_count,
        'notes', v_notes
      ), v_actor
    );
  end loop;
  return v_group_id;
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'Ja existe este documento manual para o fornecedor e a empresa operadora selecionados.';
end
$_$;


