--
-- Name: create_manual_supplier_payable_classified(uuid, uuid, uuid, text, text, date, numeric, jsonb, integer, text, uuid, uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_manual_supplier_payable_classified(p_operating_company_id uuid, p_supplier_id uuid, p_document_type_id uuid, p_document_number text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer DEFAULT 0, p_notes text DEFAULT NULL::text, p_category_id uuid DEFAULT NULL::uuid, p_cost_center_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_group uuid; item record; begin
  if (p_category_id is null)<>(p_cost_center_id is null) then
    raise exception using errcode='23514',message='Informe a categoria financeira e o centro de custo em conjunto.';
  end if;
  v_group:=apticket.create_manual_supplier_payable(
    p_operating_company_id,p_supplier_id,p_document_type_id,p_document_number,p_description,
    p_competence,p_total_amount,p_installments,p_installment_interval_days,p_notes
  );
  if p_category_id is not null then
    for item in select id from apticket.supplier_payables where manual_entry_group_id=v_group loop
      perform apticket.classify_financial_entry(
        'supplier_payable',item.id,p_category_id,p_cost_center_id,'Classificacao informada no lancamento manual'
      );
    end loop;
  end if;
  return v_group;
end
$$;


ALTER FUNCTION apticket.create_manual_supplier_payable_classified(p_operating_company_id uuid, p_supplier_id uuid, p_document_type_id uuid, p_document_number text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_installment_interval_days integer, p_notes text, p_category_id uuid, p_cost_center_id uuid) OWNER TO supabase_admin;

--
-- Name: create_manual_supplier_payable_with_attachments(uuid, uuid, uuid, text, text, date, numeric, jsonb, jsonb, jsonb, jsonb, integer, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.create_manual_supplier_payable_with_attachments(p_operating_company_id uuid, p_supplier_id uuid, p_document_type_id uuid, p_document_number text, p_description text, p_competence date, p_total_amount numeric, p_installments jsonb, p_category_allocations jsonb, p_cost_center_allocations jsonb, p_attachments jsonb, p_installment_interval_days integer DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_group uuid;
begin
  if auth.uid() is null then raise exception using errcode='42501',message='Sessão obrigatória.'; end if;
  -- Keep the original, validated creation flow and attach within its transaction.
  v_group:=apticket.create_manual_supplier_payable_allocated(p_operating_company_id,p_supplier_id,p_document_type_id,
    p_document_number,p_description,p_competence,p_total_amount,p_installments,p_category_allocations,
    p_cost_center_allocations,p_installment_interval_days,p_notes);
  perform apticket_finance_private.link_payable_attachments(v_group,p_attachments);
  return v_group;
end $$;


