--
-- Name: data_pascoa(integer); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.data_pascoa(p_ano integer) RETURNS date
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $$
declare
  a integer;
  b integer;
  c integer;
  d integer;
  e integer;
  f integer;
  g integer;
  h integer;
  i integer;
  k integer;
  l integer;
  m integer;
  mes integer;
  dia integer;
begin
  a := p_ano % 19;
  b := p_ano / 100;
  c := p_ano % 100;
  d := b / 4;
  e := b % 4;
  f := (b + 8) / 25;
  g := (b - f + 1) / 3;
  h := (19 * a + b - d - g + 15) % 30;
  i := c / 4;
  k := c % 4;
  l := (32 + 2 * e + 2 * i - h - k) % 7;
  m := (a + 11 * h + 22 * l) / 451;
  mes := (h + l - 7 * m + 114) / 31;
  dia := ((h + l - 7 * m + 114) % 31) + 1;
  return make_date(p_ano, mes, dia);
end
$$;


ALTER FUNCTION apticket.data_pascoa(p_ano integer) OWNER TO postgres;

--
-- Name: delete_fixed_payable(uuid, integer); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.delete_fixed_payable(p_id uuid, p_expected_revision integer) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare t apticket.fixed_payables; begin
  select * into t from apticket.fixed_payables where id=p_id and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Conta fixa não encontrada.'; end if;
  perform apticket_finance_private.require_fixed_access(t.tenant_id,t.operating_company_id);
  if p_expected_revision is null or t.revision<>p_expected_revision then raise exception using errcode='40001',message='Esta conta fixa foi alterada. Atualize a lista.'; end if;
  update apticket.fixed_payables set deleted_at=clock_timestamp(),is_active=false where id=p_id;
  update apticket.fixed_payable_occurrences set deleted_at=clock_timestamp(),deletion_reason='template_deleted' where fixed_payable_id=p_id and status='forecast' and deleted_at is null;
  return true;
end $$;


ALTER FUNCTION apticket.delete_fixed_payable(p_id uuid, p_expected_revision integer) OWNER TO supabase_admin;

--
-- Name: delete_supplier_payable(uuid, integer, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.delete_supplier_payable(p_id uuid, p_expected_revision integer, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; v_context text:=coalesce(current_setting('apticket.payable_mutation',true),'');
begin
  p:=apticket_finance_private.prepare_payable_mutation(p_id,p_expected_revision);
  if length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception using errcode='22023',message='Informe o motivo da exclusão, com 3 a 1.000 caracteres.';
  end if;
  perform apticket_finance_private.cancel_payable_approvals(p.id,'Lançamento excluído: '||btrim(p_reason));
  perform set_config('apticket.payable_mutation',p.id::text,true);
  update apticket.supplier_payables set status='cancelled',deleted_at=clock_timestamp(),last_change_reason=btrim(p_reason) where id=p.id;
  update apticket.supplier_payable_allocations set deleted_at=clock_timestamp() where supplier_payable_id=p.id and deleted_at is null;
  perform set_config('apticket.payable_mutation',v_context,true);
  return true;
end $$;


ALTER FUNCTION apticket.delete_supplier_payable(p_id uuid, p_expected_revision integer, p_reason text) OWNER TO supabase_admin;

