-- Name: FUNCTION delete_supplier_payable(p_id uuid, p_expected_revision integer, p_reason text); Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON FUNCTION apticket.delete_supplier_payable(p_id uuid, p_expected_revision integer, p_reason text) IS 'Exclui logicamente um lançamento/parcela e seus rateios, preservando histórico e auditoria.';


--
-- Name: eh_dia_util(date, uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.eh_dia_util(p_data date, p_tenant_id uuid) RETURNS boolean
    LANGUAGE sql STABLE STRICT
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
  select
    extract(isodow from p_data) not in (6, 7)
    and not exists (
      select 1
      from apticket.feriados
      where data = p_data
        and (tenant_id is null or tenant_id = p_tenant_id)
    );
$$;


ALTER FUNCTION apticket.eh_dia_util(p_data date, p_tenant_id uuid) OWNER TO postgres;

