-- Name: enforce_service_remote_only(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.enforce_service_remote_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_remote boolean;
begin
  select includes_remote into v_remote
  from apticket.provided_services
  where id = new.provided_service_id;

  if v_remote is not true then
    raise exception 'Serviço selecionado não está disponível para Suporte Remoto';
  end if;

  return new;
end;
$$;


