--
-- Name: enqueue_document_automation(); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.enqueue_document_automation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.deleted_at is null then
    insert into apticket.automation_dispatch_outbox (
      tenant_id, trigger_id, company_id, related_entity_id, payload
    ) values (
      new.tenant_id,
      'documentos_disponibilizados',
      new.company_id,
      new.publication_batch_id,
      jsonb_build_object('competencia', new.competencia, 'document_type', new.document_type)
    ) on conflict (tenant_id, trigger_id, related_entity_id) do update
      set payload = apticket.automation_dispatch_outbox.payload ||
        jsonb_build_object('document_count',
          coalesce((apticket.automation_dispatch_outbox.payload->>'document_count')::integer, 1) + 1);
  end if;
  return new;
end $$;


ALTER FUNCTION apticket.enqueue_document_automation() OWNER TO supabase_admin;

--
-- Name: evaluate_collection_policy(uuid, date); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.evaluate_collection_policy(p_company uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_tenant uuid:=apticket.current_tenant_id();
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null or not apticket.has_financial_scope(v_tenant,p_company,true) then
    raise exception using errcode='42501',message='Você não possui permissão para processar a régua de cobrança.';
  end if;
  return apticket_finance_private.evaluate_collection_policy(v_tenant,p_company,p_as_of);
end $$;


ALTER FUNCTION apticket.evaluate_collection_policy(p_company uuid, p_as_of date) OWNER TO supabase_admin;

