CREATE FUNCTION apticket.finish_automation_dispatch(p_dispatch_id uuid, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  update apticket.automation_dispatch_outbox
     set status = case when p_success then 'done' else 'error' end,
         finished_at = now(),
         last_error = left(p_error, 2000)
   where id = p_dispatch_id and deleted_at is null;
end $$;


