--
-- Name: generate_supplier_measurement(uuid, date); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.generate_supplier_measurement(p_supplier_contract_id uuid, p_competence date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_id uuid; v_contract apticket.supplier_contracts;
begin
  select * into v_contract from apticket.supplier_contracts
    where id=p_supplier_contract_id and deleted_at is null;
  if not found then raise exception using errcode='P0002',message='Contrato de fornecedor nao encontrado.'; end if;
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role'
    and (auth.uid() is null or not apticket.has_financial_scope(
      v_contract.tenant_id,v_contract.operating_company_id,true
    )) then raise exception using errcode='42501',message='Sem permissao financeira para gerar a medicao.'; end if;
  v_id:=apticket.generate_supplier_payable(p_supplier_contract_id,p_competence);
  if v_contract.billing_unit<>'fixed' then
    update apticket.supplier_payable_allocations set deleted_at=clock_timestamp()
      where supplier_payable_id=v_id and deleted_at is null;
  end if;
  if not apticket_finance_private.apply_fixed_supplier_allocation(v_id) then
    raise exception using errcode='23514',message='Informe o rateio percentual da medicao antes de gera-la.';
  end if;
  return v_id;
end $$;


ALTER FUNCTION apticket.generate_supplier_measurement(p_supplier_contract_id uuid, p_competence date) OWNER TO supabase_admin;

--
-- Name: generate_supplier_payable(uuid, date); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.generate_supplier_payable(p_supplier_contract_id uuid, p_competence date DEFAULT CURRENT_DATE) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  c apticket.supplier_contracts;
  s apticket.suppliers;
  v_actor uuid:=auth.uid();
  v_role text:=coalesce(current_setting('request.jwt.claim.role',true),'');
  v_competence date:=date_trunc('month',coalesce(p_competence,current_date))::date;
  v_anchor date;
  v_start date;
  v_end date;
  v_due date;
  v_id uuid;
  v_total numeric(14,2);
  v_quantity numeric(18,6);
  v_count integer;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if p_supplier_contract_id is null then
    raise exception using errcode='22023',message='Informe o contrato do fornecedor.';
  end if;
  select * into c from apticket.supplier_contracts
    where id=p_supplier_contract_id and deleted_at is null for update;
  if not found or not c.is_active then
    raise exception using errcode='P0002',message='Contrato de fornecedor ativo nao encontrado.';
  end if;
  if v_role<>'service_role' and (v_actor is null
    or not apticket.has_financial_scope(c.tenant_id,c.operating_company_id,true)) then
    raise exception using errcode='42501',message='Sem permissao financeira para gerar o lancamento.';
  end if;
  select * into s from apticket.suppliers where id=c.supplier_id and deleted_at is null and is_active;
  if not found then
    raise exception using errcode='23514',message='O fornecedor deste contrato nao esta ativo.';
  end if;
  v_anchor:=date_trunc('month',c.starts_at)::date;
  if v_competence<v_anchor or mod(
    (extract(year from age(v_competence,v_anchor))::integer*12)+extract(month from age(v_competence,v_anchor))::integer,
    c.billing_interval_months)<>0 then
    raise exception using errcode='23514',message='A competencia nao corresponde a periodicidade deste contrato.';
  end if;
  v_start:=greatest(v_competence,c.starts_at);
  v_end:=(v_competence+(c.billing_interval_months||' months')::interval)::date;
  if c.ends_at is not null then v_end:=least(v_end,c.ends_at+1); end if;
  if v_start>=v_end then
    raise exception using errcode='23514',message='A competencia esta fora da vigencia do contrato.';
  end if;
  select id into v_id from apticket.supplier_payables
    where supplier_contract_id=c.id and cycle_start=v_start and deleted_at is null;
  if found then return v_id; end if;
  v_due:=v_competence+(least(c.due_day,extract(day from
    (v_competence+interval '1 month - 1 day'))::integer)-1);
  v_id:=gen_random_uuid();
  if c.billing_unit='fixed' then
    v_quantity:=1; v_total:=c.base_amount;
  else
    select count(*),coalesce(sum(x.measured_quantity),0),
      coalesce(sum(round(x.measured_quantity*c.unit_price,2)),0)
      into v_count,v_quantity,v_total
    from apticket.consumption_snapshots x
    where x.tenant_id=c.tenant_id and x.operating_company_id=c.operating_company_id
      and x.metric=c.billing_unit and x.cycle_start>=v_start and x.cycle_end<=v_end
      and x.deleted_at is null;
    if v_count=0 then
      raise exception using errcode='23514',message='O consumo desta competencia ainda nao foi apurado.';
    end if;
  end if;
  insert into apticket.supplier_payables(id,tenant_id,operating_company_id,supplier_id,
    supplier_contract_id,document_number,description,cycle_start,cycle_end,due_date,billing_unit,
    measured_quantity,unit_price,total_amount,allocation_status,terms_snapshot,created_by)
  values(v_id,c.tenant_id,c.operating_company_id,c.supplier_id,c.id,
    'PAG-'||to_char(v_competence,'YYYYMM')||'-'||upper(substr(v_id::text,1,8)),
    c.description,v_start,v_end,v_due,c.billing_unit,v_quantity,
    case when c.billing_unit='fixed' then c.base_amount else c.unit_price end,v_total,
    case when c.billing_unit='fixed' then 'pending_rule' else 'complete' end,
    jsonb_build_object('supplier_name',coalesce(s.trade_name,s.legal_name),'supplier_tax_id',s.tax_id,
      'contract_description',c.description,'billing_interval_months',c.billing_interval_months,
      'base_amount',c.base_amount,'unit_price',c.unit_price,'due_day',c.due_day),v_actor);
  if c.billing_unit<>'fixed' then
    insert into apticket.supplier_payable_allocations(tenant_id,operating_company_id,
      supplier_payable_id,customer_contract_id,consumption_snapshot_id,customer_name,contract_number,
      metric,quantity,unit_price,source_snapshot)
    select c.tenant_id,c.operating_company_id,v_id,x.contract_id,x.id,company.name,client_contract.numero_contrato,x.metric,
      x.measured_quantity,c.unit_price,
      jsonb_build_object('snapshot_id',x.id,'cycle_start',x.cycle_start,'cycle_end',x.cycle_end,
        'measured_quantity',x.measured_quantity,'source_type',x.source_type,'source_items',x.source_items)
    from apticket.consumption_snapshots x
    join apticket.contracts client_contract on client_contract.id=x.contract_id and client_contract.tenant_id=x.tenant_id
    join apticket.companies company on company.id=client_contract.company_id and company.tenant_id=x.tenant_id
    where x.tenant_id=c.tenant_id and x.operating_company_id=c.operating_company_id
      and x.metric=c.billing_unit and x.cycle_start>=v_start and x.cycle_end<=v_end
      and x.deleted_at is null;
  end if;
  return v_id;
end $$;


ALTER FUNCTION apticket.generate_supplier_payable(p_supplier_contract_id uuid, p_competence date) OWNER TO supabase_admin;

--
-- Name: generate_ticket_closing_report(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.generate_ticket_closing_report() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'apticket'
    AS $$
begin
  if new.status in ('resolved', 'closed') and (old.status is distinct from new.status) then
    insert into apticket.ticket_closing_reports (tenant_id, ticket_id, token, generated_by)
    values (new.tenant_id, new.id, encode(extensions.gen_random_bytes(20), 'hex'), auth.uid())
    on conflict (ticket_id) do update
      set generated_at = now(),
          generated_by = excluded.generated_by;
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket.generate_ticket_closing_report() OWNER TO postgres;

--
-- Name: gerar_medicoes_contrato(uuid, date, boolean); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.gerar_medicoes_contrato(p_contrato_id uuid DEFAULT NULL::uuid, p_competencia date DEFAULT CURRENT_DATE, p_forcar boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
declare
  v_tenant_id uuid := apticket.current_tenant_id();
  v_role text := coalesce(
    nullif(current_setting('request.jwt.claim.role', true), ''),
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    ''
  );
  v_servico boolean := v_role = 'service_role';
  v_competencia date := date_trunc('month', coalesce(p_competencia, current_date))::date;
  v_contrato record;
  v_ultima_competencia date;
  v_intervalo_meses integer;
  v_elegivel boolean;
  v_medicao_id uuid;
  v_quantidade integer;
  v_valor_unitario numeric(14,2);
  v_valor_total numeric(14,2);
  v_data_vencimento date;
  v_processados integer := 0;
  v_geradas integer := 0;
  v_ignoradas integer := 0;
  v_erros integer := 0;
  v_detalhes jsonb := '[]'::jsonb;
begin
  if not v_servico then
    if auth.uid() is null or v_tenant_id is null then
      raise exception using errcode = '42501', message = 'Sessão inválida para gerar medições.';
    end if;

    if not apticket.has_permission(auth.uid(), 'contratos', 'edit') then
      raise exception using errcode = '42501', message = 'Sem permissão para gerar medições de contratos.';
    end if;
  end if;

  for v_contrato in
    select
      c.*,
      company.name as cliente_nome,
      contract_type.name as tipo_contrato_nome
    from apticket.contracts as c
    join apticket.companies as company on company.id = c.company_id
    left join apticket.contract_types as contract_type on contract_type.id = c.contract_type_id
    where c.status = 'active'
      and (p_contrato_id is null or c.id = p_contrato_id)
      and (v_servico or c.tenant_id = v_tenant_id)
      and c.starts_at <= (v_competencia + interval '1 month - 1 day')::date
      and date_trunc('month', c.ends_at)::date >= v_competencia
    order by c.tenant_id, c.created_at, c.id
  loop
    v_processados := v_processados + 1;

    begin
      select max(competencia)
      into v_ultima_competencia
      from apticket.medicoes_contrato
      where contrato_id = v_contrato.id
        and deleted_at is null;

      v_intervalo_meses := case v_contrato.tipo_medicao
        when 'mensal' then 1
        when 'trimestral' then 3
        when 'semestral' then 6
        when 'anual' then 12
        else null
      end;

      if p_forcar then
        v_elegivel := true;
      elsif v_contrato.tipo_medicao = 'unica' then
        v_elegivel := v_ultima_competencia is null and current_date >= v_contrato.starts_at;
      elsif v_ultima_competencia is null then
        v_elegivel := v_competencia >= date_trunc('month', v_contrato.starts_at)::date;
      else
        v_elegivel := v_competencia >= (v_ultima_competencia + make_interval(months => v_intervalo_meses))::date;
      end if;

      if not v_elegivel then
        v_ignoradas := v_ignoradas + 1;
        v_detalhes := v_detalhes || jsonb_build_array(jsonb_build_object(
          'contrato_id', v_contrato.id,
          'numero_contrato', v_contrato.numero_contrato,
          'resultado', 'fora_do_ciclo'
        ));
        continue;
      end if;

      if exists (
        select 1 from apticket.medicoes_contrato
        where contrato_id = v_contrato.id and competencia = v_competencia
      ) then
        v_ignoradas := v_ignoradas + 1;
        v_detalhes := v_detalhes || jsonb_build_array(jsonb_build_object(
          'contrato_id', v_contrato.id,
          'numero_contrato', v_contrato.numero_contrato,
          'resultado', 'ja_medida'
        ));
        continue;
      end if;

      if v_contrato.billing_model = 'per_equipment' then
        select count(*)::integer
        into v_quantidade
        from apticket.contract_equipments as link
        join apticket.equipments as equipment on equipment.id = link.equipment_id
        where link.contract_id = v_contrato.id
          and link.tenant_id = v_contrato.tenant_id
          and equipment.tenant_id = v_contrato.tenant_id
          and equipment.status = 'active';

        if v_quantidade = 0 then
          raise exception 'O contrato por equipamento não possui equipamentos ativos vinculados.';
        end if;

        select (tier ->> 'price')::numeric(14,2)
        into v_valor_unitario
        from jsonb_array_elements(v_contrato.equipment_tiers) as tier
        where v_quantidade between (tier ->> 'min')::integer and (tier ->> 'max')::integer
        order by (tier ->> 'min')::integer desc
        limit 1;

        if v_valor_unitario is null then
          raise exception 'A quantidade de equipamentos (%) não está coberta por uma faixa de preço.', v_quantidade;
        end if;

        v_valor_total := round(v_quantidade * v_valor_unitario, 2);
      elsif v_contrato.billing_model = 'per_service' then
        if jsonb_array_length(v_contrato.service_items) = 0 then
          raise exception 'O contrato por serviço não possui serviços vinculados.';
        end if;

        select coalesce(sum(
          coalesce((item ->> 'quantity')::numeric, 0)
          * coalesce((item ->> 'price')::numeric, 0)
        ), 0)::numeric(14,2)
        into v_valor_total
        from jsonb_array_elements(v_contrato.service_items) as item;
      elsif v_contrato.billing_model = 'hours_package' then
        v_valor_total := v_contrato.monthly_value::numeric(14,2);
      else
        raise exception 'Modelo de cobrança não suportado: %.', v_contrato.billing_model;
      end if;

      v_data_vencimento := apticket.calcular_vencimento_medicao(
        v_competencia,
        v_contrato.tipo_vencimento,
        v_contrato.dia_vencimento,
        v_contrato.tenant_id
      );

      insert into apticket.medicoes_contrato (
        tenant_id,
        contrato_id,
        numero_contrato,
        cliente_nome,
        tipo_contrato_nome,
        competencia,
        data_medicao,
        modelo_cobranca,
        valor_total,
        emite_nf,
        emite_boleto,
        data_vencimento
      ) values (
        v_contrato.tenant_id,
        v_contrato.id,
        v_contrato.numero_contrato,
        v_contrato.cliente_nome,
        v_contrato.tipo_contrato_nome,
        v_competencia,
        current_date,
        v_contrato.billing_model,
        v_valor_total,
        v_contrato.emite_nf,
        v_contrato.emite_boleto,
        v_data_vencimento
      )
      returning id into v_medicao_id;

      if v_contrato.billing_model = 'per_equipment' then
        insert into apticket.medicao_itens (
          tenant_id, medicao_id, tipo_item, referencia_id, referencia,
          descricao, quantidade, valor_unitario, valor_total
        )
        select
          v_contrato.tenant_id,
          v_medicao_id,
          'equipamento',
          equipment.id,
          coalesce(equipment.asset_tag, equipment.serial_number),
          concat_ws(' - ', equipment.name, nullif(equipment.asset_tag, ''), nullif(equipment.serial_number, '')),
          1,
          v_valor_unitario,
          v_valor_unitario
        from apticket.contract_equipments as link
        join apticket.equipments as equipment on equipment.id = link.equipment_id
        where link.contract_id = v_contrato.id
          and link.tenant_id = v_contrato.tenant_id
          and equipment.tenant_id = v_contrato.tenant_id
          and equipment.status = 'active'
        order by equipment.name, equipment.id;
      elsif v_contrato.billing_model = 'per_service' then
        insert into apticket.medicao_itens (
          tenant_id, medicao_id, tipo_item, referencia, descricao,
          quantidade, valor_unitario, valor_total
        )
        select
          v_contrato.tenant_id,
          v_medicao_id,
          'servico',
          nullif(item ->> 'reference', ''),
          coalesce(nullif(item ->> 'description', ''), nullif(item ->> 'reference', ''), 'Serviço vinculado'),
          (item ->> 'quantity')::numeric(10,2),
          (item ->> 'price')::numeric(14,2),
          round((item ->> 'quantity')::numeric * (item ->> 'price')::numeric, 2)
        from jsonb_array_elements(v_contrato.service_items) as item;
      else
        insert into apticket.medicao_itens (
          tenant_id, medicao_id, tipo_item, descricao,
          quantidade, valor_unitario, valor_total
        ) values (
          v_contrato.tenant_id,
          v_medicao_id,
          'pacote_horas',
          format('Pacote de %s horas', v_contrato.hours_monthly_quota),
          1,
          v_valor_total,
          v_valor_total
        );
      end if;

      v_geradas := v_geradas + 1;
      v_detalhes := v_detalhes || jsonb_build_array(jsonb_build_object(
        'contrato_id', v_contrato.id,
        'numero_contrato', v_contrato.numero_contrato,
        'medicao_id', v_medicao_id,
        'resultado', 'gerada',
        'valor_total', v_valor_total
      ));
    exception
      when unique_violation then
        v_ignoradas := v_ignoradas + 1;
        v_detalhes := v_detalhes || jsonb_build_array(jsonb_build_object(
          'contrato_id', v_contrato.id,
          'numero_contrato', v_contrato.numero_contrato,
          'resultado', 'ja_medida'
        ));
      when others then
        v_erros := v_erros + 1;
        v_detalhes := v_detalhes || jsonb_build_array(jsonb_build_object(
          'contrato_id', v_contrato.id,
          'numero_contrato', v_contrato.numero_contrato,
          'resultado', 'erro',
          'mensagem', sqlerrm,
          'codigo', sqlstate
        ));
    end;
  end loop;

  if p_contrato_id is not null and v_processados = 0 then
    raise exception using errcode = 'P0002', message = 'Contrato ativo e vigente não encontrado para a competência.';
  end if;

  return jsonb_build_object(
    'competencia', to_char(v_competencia, 'YYYY-MM-DD'),
    'processados', v_processados,
    'geradas', v_geradas,
    'ignoradas', v_ignoradas,
    'erros', v_erros,
    'detalhes', v_detalhes
  );
end
$$;


ALTER FUNCTION apticket.gerar_medicoes_contrato(p_contrato_id uuid, p_competencia date, p_forcar boolean) OWNER TO postgres;

--
-- Name: gerar_numero_contrato(uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.gerar_numero_contrato(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
declare
  v_numero integer;
begin
  if p_tenant_id is null then
    raise exception using errcode = '22004', message = 'Tenant do contrato não informado.';
  end if;

  insert into apticket.contrato_sequencia (tenant_id, ultimo_numero)
  values (p_tenant_id, 1)
  on conflict (tenant_id)
  do update set ultimo_numero = apticket.contrato_sequencia.ultimo_numero + 1
  returning ultimo_numero into v_numero;

  if v_numero > 999999 then
    raise exception using errcode = '22003', message = 'Limite de numeração de contratos atingido para o tenant.';
  end if;

  return lpad(v_numero::text, 6, '0') || '/' || to_char(current_date, 'YYYY');
end
$$;


ALTER FUNCTION apticket.gerar_numero_contrato(p_tenant_id uuid) OWNER TO postgres;

--
-- Name: gerar_previsoes_conta_fixa(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.gerar_previsoes_conta_fixa(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare t apticket.fixed_payables; begin
  select * into t from apticket.fixed_payables where id=p_id and tenant_id=apticket.current_tenant_id() and deleted_at is null;
  if not found then raise exception using errcode='P0002',message='Conta fixa não encontrada.'; end if;
  perform apticket_finance_private.require_fixed_access(t.tenant_id,t.operating_company_id);
  return apticket_finance_private.generate_fixed_forecasts(t.id);
end $$;


ALTER FUNCTION apticket.gerar_previsoes_conta_fixa(p_id uuid) OWNER TO supabase_admin;

--
-- Name: get_closing_report_by_token(text); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.get_closing_report_by_token(_token text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'apticket'
    AS $$
declare
  result jsonb;
begin
  if _token is null or length(_token) < 16 then
    return null;
  end if;

  select jsonb_build_object(
    'report_number', 'F-' || lpad(t.number::text, 6, '0'),
    'generated_at', r.generated_at,
    'ticket_number', t.number,
    'subject', coalesce(nullif(t.resolution_summary, ''), t.subject),
    'diagnosis_html', t.resolution_diagnosis,
    'status', t.status,
    'opened_at', t.created_at,
    'closed_at', t.closed_at,
    'resolved_at', t.resolved_at,
    'client_name', comp.name,
    'contact_name', cont.name,
    'contract_name', cty.name,
    'equipment_name', eq.name,
    'agent_name', ag.name,
    'total_minutes', coalesce(te.total_minutes, 0),
    'time_entries', coalesce(te.entries, '[]'::jsonb),
    'services', coalesce(svc.items, '[]'::jsonb),
    'tenant_name', ten.name
  )
  into result
  from apticket.ticket_closing_reports r
  join apticket.tickets t on t.id = r.ticket_id
  left join apticket.companies comp on comp.id = t.company_id
  left join apticket.contacts cont on cont.id = t.contact_id
  left join apticket.contracts ctr on ctr.id = t.contract_id
  left join apticket.contract_types cty on cty.id = ctr.contract_type_id
  left join apticket.equipments eq on eq.id = t.equipment_id
  left join apticket.profiles ag on ag.id = t.assigned_to
  left join apticket.tenants ten on ten.id = t.tenant_id
  left join lateral (
    select
      sum(te2.minutes) as total_minutes,
      jsonb_agg(jsonb_build_object(
        'started_at', te2.started_at,
        'minutes', te2.minutes,
        'description', te2.description,
        'agent_name', tp.name
      ) order by te2.created_at) as entries
    from apticket.time_entries te2
    left join apticket.profiles tp on tp.id = te2.agent_id
    where te2.ticket_id = t.id
  ) te on true
  left join lateral (
    select jsonb_agg(jsonb_build_object(
      'description', ps.description,
      'complement', tsp.complement
    ) order by tsp.created_at) as items
    from apticket.ticket_services_performed tsp
    join apticket.provided_services ps on ps.id = tsp.provided_service_id
    where tsp.ticket_id = t.id
  ) svc on true
  where r.token = _token;

  return result;
end;
$$;


ALTER FUNCTION apticket.get_closing_report_by_token(_token text) OWNER TO postgres;

--
-- Name: get_collection_policy(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.get_collection_policy(p_company uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_tenant uuid:=apticket.current_tenant_id(); v_policy apticket.collection_policies; v_configured boolean;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','view') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null or not apticket.has_financial_scope(v_tenant,p_company) then
    raise exception using errcode='42501',message='Você não possui permissão para consultar a régua de cobrança.';
  end if;
  select * into v_policy from apticket.collection_policies where tenant_id=v_tenant
    and operating_company_id=p_company and deleted_at is null;
  v_configured:=found;
  return jsonb_build_object(
    'company_id',p_company,'configured',v_configured,'enabled',coalesce(v_policy.enabled,false),
    'suspend_after_days',v_policy.suspend_after_days,
    'steps',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'position',s.position,
      'days_after_due',s.days_after_due,'channel',s.channel,'subject',s.subject,
      'message_template',s.message_template,'enabled',s.enabled) order by s.position)
      from apticket.collection_policy_steps s where s.policy_id=v_policy.id and s.deleted_at is null),'[]'::jsonb),
    'pending_actions',coalesce((select count(*) from apticket.collection_actions a
      where a.policy_id=v_policy.id and a.status='pending'),0),
    'failed_actions',coalesce((select count(*) from apticket.collection_actions a
      where a.policy_id=v_policy.id and a.status='failed'),0),
    'pending_events',coalesce((select count(*) from apticket.financial_domain_events e
      where e.tenant_id=v_tenant and e.operating_company_id=p_company and e.status='pending'),0),
    'updated_at',v_policy.updated_at
  );
end $$;


ALTER FUNCTION apticket.get_collection_policy(p_company uuid) OWNER TO supabase_admin;

--
-- Name: get_contract_measurement_report_by_token(uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.get_contract_measurement_report_by_token(_token uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
  select jsonb_build_object(
    'report_number',
      'BM-' || replace(m.numero_contrato, '/', '-') || '-' || to_char(m.competencia, 'YYYYMM'),
    'generated_at', m.created_at,
    'measurement_date', m.data_medicao,
    'competence', m.competencia,
    'due_date', m.data_vencimento,
    'contract_number', m.numero_contrato,
    'client_name', m.cliente_nome,
    'contract_type_name', m.tipo_contrato_nome,
    'billing_model', m.modelo_cobranca,
    'status', m.status,
    'billing_type', m.billing_type,
    'collection_type', m.collection_type,
    'issues_invoice', m.emite_nf,
    'issues_bank_slip', m.emite_boleto,
    'total_value', m.valor_total,
    'tenant_name', tenant.name,
    'items', coalesce(
      (
        select jsonb_agg(
          jsonb_build_object(
            'type', item.tipo_item,
            'reference', item.referencia,
            'description', item.descricao,
            'quantity', item.quantidade,
            'unit_value', item.valor_unitario,
            'total_value', item.valor_total
          )
          order by item.created_at, item.id
        )
        from apticket.medicao_itens as item
        where item.medicao_id = m.id
      ),
      '[]'::jsonb
    )
  )
  from apticket.medicoes_contrato as m
  join apticket.tenants as tenant on tenant.id = m.tenant_id
  where m.report_token = _token
    and m.deleted_at is null;
$$;


ALTER FUNCTION apticket.get_contract_measurement_report_by_token(_token uuid) OWNER TO postgres;

