--
-- Name: grant_automation_permissions_to_admin_role(); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.grant_automation_permissions_to_admin_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if lower(new.name) = 'admin' then
    insert into apticket.role_permissions(role_id, permission_id)
    select new.id, permission.id
    from apticket.permissions permission
    where permission.module = 'automacoes'
    on conflict do nothing;
  end if;
  return new;
end $$;


