--
-- Name: protect_last_active_admin_profile(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.protect_last_active_admin_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if old.is_active
     and (tg_op = 'DELETE' or not new.is_active)
     and exists (
       select 1
       from apticket.user_roles ur
       join apticket.roles r on r.id = ur.role_id
       where ur.user_id = old.id and r.is_system
     )
     and not exists (
       select 1
       from apticket.profiles p
       join apticket.user_roles ur on ur.user_id = p.id
       join apticket.roles r on r.id = ur.role_id
       where p.tenant_id = old.tenant_id
         and p.is_active
         and p.id <> old.id
         and r.is_system
     ) then
    raise exception 'nao e possivel remover ou desativar o ultimo administrador ativo';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION apticket.protect_last_active_admin_profile() OWNER TO postgres;

--
-- Name: protect_last_active_admin_role(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.protect_last_active_admin_role() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if exists (
       select 1 from apticket.roles r
       where r.id = old.role_id and r.is_system
     )
     and exists (
       select 1 from apticket.profiles p
       where p.id = old.user_id and p.is_active
     )
     and not exists (
       select 1
       from apticket.profiles p
       join apticket.user_roles ur on ur.user_id = p.id
       join apticket.roles r on r.id = ur.role_id
       where p.tenant_id = old.tenant_id
         and p.is_active
         and p.id <> old.user_id
         and r.is_system
     ) then
    raise exception 'nao e possivel rebaixar o ultimo administrador ativo';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


ALTER FUNCTION apticket.protect_last_active_admin_role() OWNER TO postgres;

