--
-- Name: proteger_conta_receber(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.proteger_conta_receber() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'apticket'
    AS $$
begin
  if row(
    new.tenant_id, new.medicao_id, new.contrato_id, new.company_id,
    new.cliente_nome, new.documento_referencia, new.descricao,
    new.competencia, new.valor_original, new.aprovado_em, new.aprovado_por,
    new.created_at
  ) is distinct from row(
    old.tenant_id, old.medicao_id, old.contrato_id, old.company_id,
    old.cliente_nome, old.documento_referencia, old.descricao,
    old.competencia, old.valor_original, old.aprovado_em, old.aprovado_por,
    old.created_at
  ) then
    raise exception using errcode = '55000', message = 'A origem da conta a receber nÃ£o pode ser alterada.';
  end if;
  new.updated_at := now();
  return new;
end
$$;


ALTER FUNCTION apticket.proteger_conta_receber() OWNER TO postgres;

--
-- Name: proteger_edicao_cobranca_avulsa(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.proteger_edicao_cobranca_avulsa() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  new.ticket_id := old.ticket_id;
  new.tenant_id := old.tenant_id;
  new.created_at := old.created_at;
  new.updated_at := now();

  if pg_trigger_depth() = 1 then
    new.tabela_preco_id := old.tabela_preco_id;
    new.limite_valor_fixo_minutos := old.limite_valor_fixo_minutos;
    new.valor_fixo_snapshot := old.valor_fixo_snapshot;
    new.valor_hora_snapshot := old.valor_hora_snapshot;
    new.minutos_apurados := old.minutos_apurados;
    new.valor_base := old.valor_base;
    new.deleted_at := old.deleted_at;
    new.valor_ajustado_manualmente := old.valor_ajustado_manualmente;
    if new.valor_final is distinct from old.valor_final then
      if nullif(trim(coalesce(new.justificativa_ajuste, '')), '') is null then
        raise exception 'Informe a justificativa para ajustar o valor final';
      end if;
      new.valor_ajustado_manualmente := true;
    end if;
    new.atualizado_por := auth.uid();
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket.proteger_edicao_cobranca_avulsa() OWNER TO postgres;

