--
-- Name: recalcular_cobranca_avulsa(uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.recalcular_cobranca_avulsa(_ticket_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_minutos integer;
  v_cobranca apticket.tickets_cobranca_avulsa%rowtype;
  v_base numeric(12,2);
begin
  select * into v_cobranca
  from apticket.tickets_cobranca_avulsa
  where ticket_id = _ticket_id and deleted_at is null;
  if not found then return; end if;

  select coalesce(sum(minutes), 0)::integer into v_minutos
  from apticket.time_entries where ticket_id = _ticket_id;

  v_base := case
    when v_minutos <= v_cobranca.limite_valor_fixo_minutos
      then v_cobranca.valor_fixo_snapshot
    else round((v_minutos::numeric / 60) * v_cobranca.valor_hora_snapshot, 2)
  end;

  update apticket.tickets_cobranca_avulsa
  set minutos_apurados = v_minutos,
      valor_base = v_base,
      valor_final = case when valor_ajustado_manualmente then valor_final else v_base end,
      revisado_em = case
        when v_base is distinct from v_cobranca.valor_base
          and status_cobranca not in ('recebido', 'cancelado') then null
        else revisado_em
      end,
      revisado_por = case
        when v_base is distinct from v_cobranca.valor_base
          and status_cobranca not in ('recebido', 'cancelado') then null
        else revisado_por
      end,
      updated_at = now()
  where id = v_cobranca.id;
end;
$$;


ALTER FUNCTION apticket.recalcular_cobranca_avulsa(_ticket_id uuid) OWNER TO postgres;

--
-- Name: recalcular_cobranca_por_apontamento(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.recalcular_cobranca_por_apontamento() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op = 'DELETE' then
    perform apticket.recalcular_cobranca_avulsa(old.ticket_id);
    return old;
  end if;
  perform apticket.recalcular_cobranca_avulsa(new.ticket_id);
  return new;
end;
$$;


ALTER FUNCTION apticket.recalcular_cobranca_por_apontamento() OWNER TO postgres;

--
-- Name: recalcular_cobranca_por_status(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.recalcular_cobranca_por_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.tipo_atendimento = 'avulso'
     and new.status in ('resolved', 'closed')
     and new.status is distinct from old.status then
    perform apticket.recalcular_cobranca_avulsa(new.id);
    update apticket.tickets_cobranca_avulsa
      set revisado_em = null, revisado_por = null, updated_at = now()
      where ticket_id = new.id and status_cobranca <> 'cancelado';
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket.recalcular_cobranca_por_status() OWNER TO postgres;

--
-- Name: reconcile_bank_transaction(uuid, text, uuid, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.reconcile_bank_transaction(p_transaction_id uuid, p_source_type text, p_source_id uuid, p_notes text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare tx apticket.bank_statement_transactions; v_amount numeric(14,2); v_document text;
  v_counterparty text; v_actual_type text; v_name text; begin
  if not apticket.has_permission(auth.uid(),'financeiro_bancos','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into tx from apticket.bank_statement_transactions where id=p_transaction_id
    and reconciliation_status='pending_review' and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Movimento pendente não encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(tx.tenant_id,tx.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissão para conciliar este movimento.';
  end if;
  if tx.amount>0 and p_source_type in ('measurement_receivable','recurring_receivable','manual_receivable') then
    select receivable.valor_aberto,receivable.documento_referencia,receivable.cliente_nome,
      case receivable.origin_type when 'measurement' then 'measurement_receivable' when 'manual' then 'manual_receivable' else 'recurring_receivable' end
      into v_amount,v_document,v_counterparty,v_actual_type
    from apticket.contas_receber receivable where receivable.id=p_source_id
      and receivable.tenant_id=tx.tenant_id and receivable.operating_company_id=tx.operating_company_id
      and receivable.deleted_at is null and receivable.valor_aberto>0;
  elsif tx.amount<0 and p_source_type='supplier_payment' then
    select payment.scheduled_amount,payable.document_number,
      coalesce(payable.terms_snapshot->>'supplier_name','Fornecedor'),'supplier_payment'
      into v_amount,v_document,v_counterparty,v_actual_type
    from apticket.supplier_payments payment join apticket.supplier_payables payable
      on payable.id=payment.supplier_payable_id
    where payment.id=p_source_id and payment.tenant_id=tx.tenant_id
      and payment.operating_company_id=tx.operating_company_id and payment.status='scheduled';
  else raise exception using errcode='23514',message='A natureza do lançamento não corresponde ao movimento bancário.';
  end if;
  if v_amount is null or v_actual_type<>p_source_type then
    raise exception using errcode='P0002',message='Lançamento financeiro disponível não encontrado.';
  end if;
  if exists(select 1 from apticket.bank_statement_transactions previous
    where previous.tenant_id=tx.tenant_id and previous.operating_company_id=tx.operating_company_id
      and previous.match_source_type=p_source_type and previous.match_source_id=p_source_id
      and previous.reconciliation_status in ('matched_auto','matched_manual')
      and previous.deleted_at is null) then
    raise exception using errcode='23505',message='Este lançamento já está conciliado com outro movimento.';
  end if;
  select name into v_name from apticket.profiles where id=auth.uid()
    and tenant_id=tx.tenant_id and is_active;
  update apticket.bank_statement_transactions set reconciliation_status='matched_manual',
    match_source_type=p_source_type,match_source_id=p_source_id,match_document_number=v_document,
    match_counterparty_name=v_counterparty,matched_amount=v_amount,
    difference_amount=abs(tx.amount)-v_amount,confidence_percent=null,reconciled_by=auth.uid(),
    reconciled_by_name=v_name,reconciled_at=clock_timestamp(),
    resolution_notes=nullif(btrim(p_notes),''),updated_at=clock_timestamp() where id=tx.id;
  perform apticket_finance_private.refresh_statement_import(tx.import_id);
  return true;
end $$;


ALTER FUNCTION apticket.reconcile_bank_transaction(p_transaction_id uuid, p_source_type text, p_source_id uuid, p_notes text) OWNER TO supabase_admin;

--
-- Name: refresh_employee_compliance(); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.refresh_employee_compliance() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare docs integer; vacations integer; tenant uuid:=apticket.current_tenant_id(); begin
  if auth.uid() is null or tenant is null or not apticket.has_permission(auth.uid(),'funcionarios','view') then
    raise exception using errcode='42501',message='Sem permissão para atualizar alertas de funcionários.';
  end if;
  update apticket.funcionario_documentos set status='vencido',updated_at=clock_timestamp()
    where tenant_id=tenant and deleted_at is null and data_validade<current_date and status not in ('vencido','rejeitado'); get diagnostics docs=row_count;
  update apticket.funcionario_ferias set status=case
      when data_inicio_gozo<=current_date and data_fim_gozo>=current_date then 'em_gozo'
      when data_fim_gozo<current_date then 'gozadas'
      when data_inicio_gozo>current_date then 'agendadas'
      when periodo_concessivo_limite<current_date then 'vencidas'
      when periodo_concessivo_limite<=current_date+interval '60 days' then 'vencendo'
      else 'nao_vencidas' end,updated_at=clock_timestamp()
    where tenant_id=tenant and deleted_at is null and status<>'pagas'; get diagnostics vacations=row_count;
  return jsonb_build_object('documents',docs,'vacations',vacations);
end $$;


ALTER FUNCTION apticket.refresh_employee_compliance() OWNER TO supabase_admin;

--
-- Name: reject_supplier_payable(uuid, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.reject_supplier_payable(p_request_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  request apticket.supplier_payable_approval_requests;
  current_step apticket.supplier_payable_approval_steps;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into request from apticket.supplier_payable_approval_requests
    where id=p_request_id for update;
  if not found then raise exception using errcode='P0002',message='Solicitacao de aprovacao nao encontrada.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(
    request.tenant_id,request.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para rejeitar este lancamento.';
  end if;
  if request.status<>'pending' then
    raise exception using errcode='23514',message='Esta solicitacao de aprovacao ja foi concluida.';
  end if;
  if length(btrim(coalesce(p_reason,''))) not between 3 and 1000 then
    raise exception using errcode='23514',message='Informe o motivo da rejeicao com ate mil caracteres.';
  end if;
  select * into current_step from apticket.supplier_payable_approval_steps
    where request_id=request.id and status='pending'
    order by step_order limit 1 for update;
  if not found then
    raise exception using errcode='23514',message='A solicitacao nao possui etapa pendente.';
  end if;
  if current_step.approver_id<>auth.uid() then
    raise exception using errcode='42501',message='A aprovacao aguarda a decisao de outro responsavel.';
  end if;
  update apticket.supplier_payable_approval_steps set status='rejected',
    decided_at=clock_timestamp(),decision_comment=btrim(p_reason)
    where id=current_step.id;
  update apticket.supplier_payable_approval_requests set status='rejected',
    rejection_reason=btrim(p_reason),completed_at=clock_timestamp() where id=request.id;
  update apticket.supplier_payables set status='scheduled'
    where id=request.supplier_payable_id;
  return true;
end $$;


ALTER FUNCTION apticket.reject_supplier_payable(p_request_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: remove_supplier_payable_attachment(uuid, uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.remove_supplier_payable_attachment(p_payable_id uuid, p_attachment_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; a apticket.supplier_payable_attachments;
begin
  if auth.uid() is null or not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissão para excluir anexos.';
  end if;
  -- Same lock order as inclusion, so the count and concurrent changes remain consistent.
  select * into p from apticket.supplier_payables where id=p_payable_id
    and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found or not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Lançamento indisponível nesta empresa.';
  end if;
  select * into a from apticket.supplier_payable_attachments where id=p_attachment_id
    and supplier_payable_id=p.id and tenant_id=p.tenant_id and operating_company_id=p.operating_company_id for update;
  if not found then raise exception using errcode='P0002',message='Anexo não encontrado neste lançamento.'; end if;
  if a.deleted_at is null then
    update apticket.supplier_payable_attachments set deleted_at=clock_timestamp(),deleted_by=auth.uid() where id=a.id;
  end if;
  return true;
end $$;


ALTER FUNCTION apticket.remove_supplier_payable_attachment(p_payable_id uuid, p_attachment_id uuid) OWNER TO supabase_admin;

--
-- Name: FUNCTION remove_supplier_payable_attachment(p_payable_id uuid, p_attachment_id uuid); Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON FUNCTION apticket.remove_supplier_payable_attachment(p_payable_id uuid, p_attachment_id uuid) IS 'Retira um anexo do lançamento e do acesso normal ao Storage, preservando documento privado e auditoria.';


