--
-- Name: resolver_atendimento_ticket(uuid, uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.resolver_atendimento_ticket(_tenant_id uuid, _company_id uuid, _equipment_id uuid DEFAULT NULL::uuid, _aberto_em timestamp with time zone DEFAULT now()) RETURNS TABLE(tipo apticket.tipo_atendimento, motivo apticket.motivo_avulso, contrato_id uuid, sla_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_data date := (_aberto_em at time zone 'America/Sao_Paulo')::date;
begin
  if _company_id is null or not exists (
    select 1
    from apticket.contracts c
    where c.tenant_id = _tenant_id
      and c.company_id = _company_id
      and c.status = 'active'
      and v_data between c.starts_at and c.ends_at
  ) then
    return query select
      'avulso'::apticket.tipo_atendimento,
      'cliente_sem_contrato'::apticket.motivo_avulso,
      null::uuid,
      null::uuid;
    return;
  end if;

  if _equipment_id is not null then
    return query
    select
      'contratual'::apticket.tipo_atendimento,
      null::apticket.motivo_avulso,
      c.id,
      c.sla_policy_id
    from apticket.contracts c
    join apticket.contract_equipments ce
      on ce.contract_id = c.id
     and ce.equipment_id = _equipment_id
     and ce.tenant_id = _tenant_id
    where c.tenant_id = _tenant_id
      and c.company_id = _company_id
      and c.status = 'active'
      and v_data between c.starts_at and c.ends_at
    order by c.starts_at desc
    limit 1;

    if found then return; end if;

    return query select
      'avulso'::apticket.tipo_atendimento,
      'equipamento_sem_contrato'::apticket.motivo_avulso,
      null::uuid,
      null::uuid;
    return;
  end if;

  return query
  select
    'contratual'::apticket.tipo_atendimento,
    null::apticket.motivo_avulso,
    c.id,
    c.sla_policy_id
  from apticket.contracts c
  where c.tenant_id = _tenant_id
    and c.company_id = _company_id
    and c.status = 'active'
    and v_data between c.starts_at and c.ends_at
  order by c.starts_at desc
  limit 1;
end;
$$;


ALTER FUNCTION apticket.resolver_atendimento_ticket(_tenant_id uuid, _company_id uuid, _equipment_id uuid, _aberto_em timestamp with time zone) OWNER TO postgres;

--
-- Name: resume_paused_ticket_on_customer_message(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.resume_paused_ticket_on_customer_message() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_pause apticket.ticket_pauses%rowtype;
  v_now timestamptz := clock_timestamp();
  v_elapsed interval;
  v_seconds bigint;
begin
  if new.author_type <> 'contact' then return new; end if;

  select * into v_pause from apticket.ticket_pauses
  where ticket_id = new.ticket_id and ended_at is null
  for update;
  if not found then return new; end if;

  v_elapsed := v_now - v_pause.started_at;
  v_seconds := greatest(0, floor(extract(epoch from v_elapsed))::bigint);
  update apticket.ticket_pauses set
    ended_at = v_now, resumed_by = null, resume_source = 'customer_interaction'
  where id = v_pause.id and ended_at is null;
  update apticket.tickets set
    sla_paused_at = null,
    total_sla_paused_seconds = total_sla_paused_seconds + v_seconds,
    sla_first_response_due_at = case when sla_first_response_due_at is null then null else sla_first_response_due_at + v_elapsed end,
    sla_resolution_due_at = case when sla_resolution_due_at is null then null else sla_resolution_due_at + v_elapsed end
  where id = new.ticket_id;
  return new;
end;
$$;


ALTER FUNCTION apticket.resume_paused_ticket_on_customer_message() OWNER TO postgres;

--
-- Name: resume_ticket(uuid); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.resume_ticket(_ticket_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_ticket apticket.tickets%rowtype;
  v_pause apticket.ticket_pauses%rowtype;
  v_now timestamptz := clock_timestamp();
  v_elapsed interval;
  v_seconds bigint;
begin
  if auth.uid() is null then raise exception 'Sessao expirada'; end if;

  select * into v_ticket from apticket.tickets
  where id = _ticket_id and tenant_id = apticket.current_tenant_id()
  for update;
  if not found then raise exception 'Ticket nao encontrado'; end if;
  if v_ticket.assigned_to is distinct from auth.uid() then
    raise exception 'Somente o tecnico responsavel pode retomar o ticket';
  end if;

  select * into v_pause from apticket.ticket_pauses
  where ticket_id = _ticket_id and ended_at is null
  for update;
  if not found then raise exception 'Este ticket nao esta pausado'; end if;

  v_elapsed := v_now - v_pause.started_at;
  v_seconds := greatest(0, floor(extract(epoch from v_elapsed))::bigint);

  update apticket.ticket_pauses
  set ended_at = v_now,
      resumed_by = auth.uid(),
      resume_source = 'manual'
  where id = v_pause.id;

  update apticket.tickets
  set sla_paused_at = null,
      total_sla_paused_seconds = total_sla_paused_seconds + v_seconds,
      sla_first_response_due_at = case
        when sla_first_response_due_at is null then null
        else sla_first_response_due_at + v_elapsed
      end,
      sla_resolution_due_at = case
        when sla_resolution_due_at is null then null
        else sla_resolution_due_at + v_elapsed
      end,
      status = 'in_progress',
      pending_type = case
        when channel in ('chat', 'whatsapp', 'email', 'portal') then 'in_progress'
        else null
      end
  where id = _ticket_id;
end;
$$;


ALTER FUNCTION apticket.resume_ticket(_ticket_id uuid) OWNER TO postgres;

