--
-- Name: save_financial_budget_entry(uuid, date, text, uuid, uuid, numeric, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_financial_budget_entry(p_operating_company_id uuid, p_period_month date, p_direction text, p_category_id uuid, p_cost_center_id uuid, p_budgeted_amount numeric, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid; category apticket.financial_categories; center apticket.financial_cost_centers;
  v_actor_name text; v_revision integer; v_id uuid:=gen_random_uuid();
begin
  select tenant_id into v_tenant from apticket.operating_companies
    where id=p_operating_company_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Empresa operadora nao encontrada.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para alterar o orcamento.';
  end if;
  if p_period_month is null or p_period_month<>date_trunc('month',p_period_month)::date
    or extract(year from p_period_month) not between 2000 and 2100 then
    raise exception using errcode='23514',message='Informe uma competencia mensal valida.';
  end if;
  if p_direction not in ('inflow','outflow') then
    raise exception using errcode='23514',message='Informe uma natureza valida para o orcamento.';
  end if;
  if p_budgeted_amount is null or p_budgeted_amount<=0 or p_budgeted_amount>999999999999.99 then
    raise exception using errcode='23514',message='Informe um valor orcado maior que zero.';
  end if;
  if p_notes is not null and length(btrim(p_notes))>1000 then
    raise exception using errcode='22001',message='As observacoes devem ter no maximo 1000 caracteres.';
  end if;
  select * into category from apticket.financial_categories where id=p_category_id
    and tenant_id=v_tenant and (operating_company_id=p_operating_company_id or is_global)
    and classification_type='analytic' and is_active and deleted_at is null;
  if not found or category.direction not in (p_direction,'both') then
    raise exception using errcode='23514',message='Selecione uma categoria analitica ativa compativel com a natureza.';
  end if;
  select * into center from apticket.financial_cost_centers where id=p_cost_center_id
    and tenant_id=v_tenant and (operating_company_id=p_operating_company_id or is_global)
    and classification_type='analytic' and is_active and deleted_at is null;
  if not found then
    raise exception using errcode='23514',message='Selecione um centro de custo analitico ativo desta empresa.';
  end if;
  select name into v_actor_name from apticket.profiles where id=auth.uid() and tenant_id=v_tenant and is_active;
  if v_actor_name is null then raise exception using errcode='42501',message='Usuario responsavel nao esta ativo.'; end if;
  select coalesce(max(revision),0)+1 into v_revision from apticket.financial_budget_entries
    where tenant_id=v_tenant and operating_company_id=p_operating_company_id
      and period_month=p_period_month and direction=p_direction
      and financial_category_id=p_category_id and cost_center_id=p_cost_center_id;
  update apticket.financial_budget_entries set replaced_at=clock_timestamp()
    where tenant_id=v_tenant and operating_company_id=p_operating_company_id
      and period_month=p_period_month and direction=p_direction
      and financial_category_id=p_category_id and cost_center_id=p_cost_center_id and replaced_at is null;
  insert into apticket.financial_budget_entries(
    id,tenant_id,operating_company_id,period_month,direction,
    financial_category_id,financial_category_code,financial_category_name,
    cost_center_id,cost_center_code,cost_center_name,budgeted_amount,notes,
    revision,created_by,created_by_name
  ) values(
    v_id,v_tenant,p_operating_company_id,p_period_month,p_direction,
    category.id,category.code,category.name,center.id,center.code,center.name,
    round(p_budgeted_amount,2),nullif(btrim(p_notes),''),v_revision,auth.uid(),v_actor_name
  );
  return v_id;
end $$;


ALTER FUNCTION apticket.save_financial_budget_entry(p_operating_company_id uuid, p_period_month date, p_direction text, p_category_id uuid, p_cost_center_id uuid, p_budgeted_amount numeric, p_notes text) OWNER TO supabase_admin;

--
-- Name: save_financial_category(uuid, uuid, text, text, text, text, boolean, boolean, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_financial_category(p_id uuid, p_operating_company_id uuid, p_code text, p_name text, p_direction text, p_description text DEFAULT NULL::text, p_is_global boolean DEFAULT false, p_is_active boolean DEFAULT true, p_classification_type text DEFAULT 'analytic'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare v_tenant uuid; v_id uuid; current_row apticket.financial_categories;
 parent_row apticket.financial_categories; v_parent text; deps jsonb;
begin
 select tenant_id into v_tenant from apticket.operating_companies
 where id=p_operating_company_id and deleted_at is null;
 if auth.uid() is null or v_tenant is distinct from apticket.current_tenant_id()
 or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true)
 or not apticket.has_permission(auth.uid(),'financeiro_fluxo_caixa','edit') then
   raise exception using errcode='42501',message='Sem permissão financeira para configurar categorias.';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('apticket.category.'||v_tenant::text,0));
 p_code:=btrim(p_code); p_name:=btrim(regexp_replace(p_name,'\s+',' ','g'));
 if p_code is null or p_name is null or length(p_name) not between 2 and 150
 or p_direction is null or p_direction not in ('inflow','outflow','both')
 or p_classification_type is null or p_classification_type not in ('analytic','synthetic')
 or p_is_global is null or p_is_active is null or length(coalesce(p_description,''))>1000
 or (p_classification_type='synthetic' and p_code !~ '^([0-9]{2}|[0-9]{2}\.[0-9]{2}|[0-9]{2}\.[0-9]{2}\.[0-9]{4})$')
 or (p_classification_type='analytic' and p_code !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{4}$') then
   raise exception using errcode='23514',message='Revise código, nome, natureza e tipo da categoria.';
 end if;
 if exists(select 1 from apticket.financial_categories c where c.tenant_id=v_tenant
   and c.id is distinct from p_id and c.deleted_at is null and c.code=p_code
   and (c.is_global or p_is_global or c.operating_company_id=p_operating_company_id)) then
   raise exception using errcode='23505',message='Já existe uma categoria com este código no escopo informado.';
 end if;
 v_parent:=case when position('.' in p_code)>0 then regexp_replace(p_code,'\.[^.]+$','') end;
 if v_parent is not null then
   select * into parent_row from apticket.financial_categories c where c.tenant_id=v_tenant
     and c.deleted_at is null and c.code=v_parent and c.classification_type='synthetic'
     and (c.is_global or c.operating_company_id=p_operating_company_id) for share;
   if not found or (p_is_active and not parent_row.is_active) then
     raise exception using errcode='23514',message='Selecione um agrupamento sintético ativo para a categoria.';
   end if;
   if (p_is_global and not parent_row.is_global) or parent_row.direction not in (p_direction,'both') then
     raise exception using errcode='23514',message='A natureza e a abrangência devem ser compatíveis com a categoria pai.';
   end if;
 end if;
 if p_id is not null then
   select * into current_row from apticket.financial_categories where id=p_id and tenant_id=v_tenant and deleted_at is null for update;
   if not found or (current_row.operating_company_id<>p_operating_company_id and not current_row.is_global) then
     raise exception using errcode='P0002',message='Categoria financeira não encontrada.';
   end if;
   deps:=apticket_finance_private.category_dependencies(v_tenant,p_id);
   if (deps->>'children')::int>0 and row(current_row.code,current_row.direction,current_row.is_global,current_row.classification_type)
     is distinct from row(p_code,p_direction,p_is_global,p_classification_type) then
     raise exception using errcode='23514',message='Este grupo possui subcategorias. Reorganize os filhos antes de alterar código, natureza, abrangência ou tipo.';
   end if;
   if ((deps->>'active_links')::int+(deps->>'history_links')::int)>0
     and row(current_row.code,current_row.name,current_row.direction,current_row.is_global,current_row.classification_type)
     is distinct from row(p_code,p_name,p_direction,p_is_global,p_classification_type) then
     raise exception using errcode='23514',message='Categoria com vínculos: preserve código, nome, natureza, abrangência e tipo. A descrição pode ser atualizada.';
   end if;
   if not p_is_active and ((deps->>'active_children')::int>0 or (deps->>'active_links')::int>0) then
     raise exception using errcode='23514',message='Desvincule os cadastros ativos e desative as subcategorias antes de inativar este grupo.';
   end if;
   update apticket.financial_categories set code=p_code,name=p_name,direction=p_direction,
     description=nullif(btrim(p_description),''),is_global=p_is_global,is_active=p_is_active,
     classification_type=p_classification_type,updated_by=auth.uid(),updated_at=clock_timestamp() where id=p_id;
   return p_id;
 end if;
 insert into apticket.financial_categories(tenant_id,operating_company_id,code,name,direction,description,
   is_global,is_active,classification_type,created_by,updated_by)
 values(v_tenant,p_operating_company_id,p_code,p_name,p_direction,nullif(btrim(p_description),''),
   p_is_global,p_is_active,p_classification_type,auth.uid(),auth.uid()) returning id into v_id;
 return v_id;
end $_$;


ALTER FUNCTION apticket.save_financial_category(p_id uuid, p_operating_company_id uuid, p_code text, p_name text, p_direction text, p_description text, p_is_global boolean, p_is_active boolean, p_classification_type text) OWNER TO supabase_admin;

--
-- Name: save_financial_cost_center(uuid, uuid, text, text, text, boolean, boolean, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_financial_cost_center(p_id uuid, p_operating_company_id uuid, p_code text, p_name text, p_description text DEFAULT NULL::text, p_is_global boolean DEFAULT false, p_is_active boolean DEFAULT true, p_classification_type text DEFAULT 'analytic'::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare v_tenant uuid; v_id uuid; current_row apticket.financial_cost_centers; begin
  select tenant_id into v_tenant from apticket.operating_companies
    where id=p_operating_company_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Empresa operadora nao encontrada.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para configurar centros de custo.';
  end if;
  if coalesce(btrim(p_code),'') !~ '^([0-9]{2}|[0-9]{2}\.[0-9]{2}|[0-9]{2}\.[0-9]{2}\.[0-9]{4})$'
    or length(btrim(coalesce(p_name,''))) not between 2 and 150
    or p_classification_type not in ('analytic','synthetic') then
    raise exception using errcode='23514',message='Informe codigo no formato 99.99.9999, nome e tipo validos para o centro de custo.';
  end if;
  if (p_classification_type='synthetic' and coalesce(btrim(p_code),'') !~ '^([0-9]{2}|[0-9]{2}\.[0-9]{2}|[0-9]{2}\.[0-9]{2}\.[0-9]{4})$')
    or (p_classification_type='analytic' and coalesce(btrim(p_code),'') !~ '^[0-9]{2}\.[0-9]{2}\.[0-9]{4}$') then
    raise exception using errcode='23514',message='Use codigos 99, 99.99 ou 99.99.9999 para centros de custo sinteticos e 99.99.9999 para centros de custo analiticos.';
  end if;
  if exists(
    select 1 from apticket.financial_cost_centers item
    where item.tenant_id=v_tenant and item.id is distinct from p_id and item.deleted_at is null
      and lower(item.code)=lower(btrim(p_code))
      and (item.is_global or p_is_global or item.operating_company_id=p_operating_company_id)
  ) then
    raise exception using errcode='23505',message='Ja existe um centro de custo com este codigo no escopo informado.';
  end if;
  if p_id is null then
    v_id:=gen_random_uuid();
    insert into apticket.financial_cost_centers(
      id,tenant_id,operating_company_id,code,name,description,is_global,is_active,classification_type,created_by,updated_by
    ) values(
      v_id,v_tenant,p_operating_company_id,btrim(p_code),btrim(p_name),nullif(btrim(p_description),''),
      p_is_global,p_is_active,p_classification_type,auth.uid(),auth.uid()
    );
  else
    select * into current_row from apticket.financial_cost_centers
      where id=p_id and tenant_id=v_tenant and deleted_at is null for update;
    if not found or (current_row.operating_company_id<>p_operating_company_id and not current_row.is_global) then
      raise exception using errcode='P0002',message='Centro de custo nao encontrado.';
    end if;
    if exists(select 1 from apticket.financial_entry_classifications where cost_center_id=p_id)
      and row(current_row.code,current_row.name,current_row.description,current_row.is_global,current_row.classification_type)
        is distinct from row(btrim(p_code),btrim(p_name),nullif(btrim(p_description),''),p_is_global,p_classification_type) then
      raise exception using errcode='23514',message='Este centro de custo ja foi utilizado; somente o status Ativo pode ser alterado.';
    end if;
    update apticket.financial_cost_centers set code=btrim(p_code),name=btrim(p_name),
      description=nullif(btrim(p_description),''),is_global=p_is_global,is_active=p_is_active,
      classification_type=p_classification_type,updated_by=auth.uid(),updated_at=clock_timestamp()
      where id=p_id;
    v_id:=p_id;
  end if;
  return v_id;
end $_$;


ALTER FUNCTION apticket.save_financial_cost_center(p_id uuid, p_operating_company_id uuid, p_code text, p_name text, p_description text, p_is_global boolean, p_is_active boolean, p_classification_type text) OWNER TO supabase_admin;

--
-- Name: save_financial_document_type(uuid, text, text, text, boolean); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_financial_document_type(p_id uuid, p_code text, p_name text, p_availability text, p_is_active boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_tenant uuid := apticket.current_tenant_id();
  v_id uuid := coalesce(p_id, gen_random_uuid());
  v_code text := btrim(coalesce(p_code, ''));
  v_name text := btrim(coalesce(p_name, ''));
begin
  if v_actor is null or v_tenant is null or not (
    apticket.has_permission(v_actor, 'financeiro_contas_receber', 'edit')
    or apticket.has_permission(v_actor, 'financeiro_contas_pagar', 'edit')
  ) then
    raise exception using errcode = '42501', message = 'Sem permissao para manter tipos de documento.';
  end if;
  if length(v_code) not between 2 and 20 or v_code !~ '^[A-Za-z0-9][A-Za-z0-9._/-]*$' then
    raise exception using errcode = '23514', message = 'O codigo deve ter de 2 a 20 caracteres, usando letras, numeros, ponto, barra, hifen ou sublinhado.';
  end if;
  if length(v_name) not between 2 and 100 then
    raise exception using errcode = '23514', message = 'A descricao deve ter entre 2 e 100 caracteres.';
  end if;
  if p_availability not in ('receivable', 'payable', 'both') then
    raise exception using errcode = '23514', message = 'Selecione onde o tipo de documento ficara disponivel.';
  end if;

  if p_id is null then
    insert into apticket.financial_document_types(
      id, tenant_id, code, name, availability, is_active, created_by
    ) values (
      v_id, v_tenant, v_code, v_name, p_availability, coalesce(p_is_active, true), v_actor
    );
  else
    update apticket.financial_document_types
    set code = v_code,
        name = v_name,
        availability = p_availability,
        is_active = coalesce(p_is_active, true)
    where id = p_id and tenant_id = v_tenant and deleted_at is null;
    if not found then
      raise exception using errcode = 'P0002', message = 'Tipo de documento nao encontrado.';
    end if;
  end if;
  return v_id;
exception
  when unique_violation then
    raise exception using errcode = '23505', message = 'Ja existe um tipo de documento com este codigo.';
end
$_$;


ALTER FUNCTION apticket.save_financial_document_type(p_id uuid, p_code text, p_name text, p_availability text, p_is_active boolean) OWNER TO supabase_admin;

--
-- Name: save_financial_settings(boolean, boolean); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_financial_settings(p_use_payable_approvals boolean, p_use_collection_rules boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_tenant uuid:=apticket.current_tenant_id();
begin
  if auth.uid() is null or v_tenant is null
    or not exists(select 1 from apticket.profiles where id=auth.uid() and tenant_id=v_tenant and is_active)
    or not apticket.has_permission(auth.uid(),'configuracoes','view')
    or not apticket.has_permission(auth.uid(),'configuracoes','edit') then
    raise exception using errcode='42501',message='Sem permissão para alterar as configurações financeiras.';
  end if;
  if p_use_payable_approvals is null or p_use_collection_rules is null then
    raise exception using errcode='22023',message='Informe Sim ou Não para as duas funcionalidades financeiras.';
  end if;
  insert into apticket.financial_settings(tenant_id,use_payable_approvals,use_collection_rules,updated_by)
    values(v_tenant,p_use_payable_approvals,p_use_collection_rules,auth.uid())
    on conflict(tenant_id) do update set use_payable_approvals=excluded.use_payable_approvals,
      use_collection_rules=excluded.use_collection_rules,updated_by=auth.uid(),updated_at=clock_timestamp();
  return true;
end $$;


ALTER FUNCTION apticket.save_financial_settings(p_use_payable_approvals boolean, p_use_collection_rules boolean) OWNER TO supabase_admin;

--
-- Name: save_fixed_payable(uuid, integer, jsonb, boolean); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_fixed_payable(p_id uuid, p_expected_revision integer, p_payload jsonb, p_apply_future boolean DEFAULT true) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare t apticket.fixed_payables; v_tenant uuid:=apticket.current_tenant_id(); v_id uuid:=coalesce(p_id,gen_random_uuid());
  v_company uuid:=(p_payload->>'operating_company_id')::uuid; v jsonb;
  v_start date:=(p_payload->>'start_month')::date; v_end date:=nullif(p_payload->>'end_month','')::date; v_day integer:=(p_payload->>'due_day')::integer;
begin
  perform apticket_finance_private.require_fixed_access(v_tenant,v_company);
  if p_id is not null then
    select * into t from apticket.fixed_payables where id=p_id and tenant_id=v_tenant and deleted_at is null for update;
    if not found then raise exception using errcode='P0002',message='Conta fixa não encontrada.'; end if;
    if t.operating_company_id is distinct from v_company then raise exception using errcode='22023',message='A empresa de uma conta fixa não pode ser alterada.'; end if;
    if p_expected_revision is null or t.revision<>p_expected_revision then raise exception using errcode='40001',message='Esta conta fixa foi alterada. Reabra o cadastro.'; end if;
  end if;
  if v_start is null or not isfinite(v_start) or v_start<>date_trunc('month',v_start)::date
    or (v_end is not null and (not isfinite(v_end) or v_end<>date_trunc('month',v_end)::date or v_end<v_start))
    or v_day is null or v_day not between 1 and 31 then
    raise exception using errcode='22023',message='Informe início, dia de vencimento e lançar até igual ou posterior ao início.';
  end if;
  v:=apticket_finance_private.normalize_fixed_payload(v_tenant,v_company,p_payload);
  if p_id is null then
    insert into apticket.fixed_payables(id,tenant_id,operating_company_id,supplier_id,supplier_name,document_type_id,description,total_amount,due_day,start_month,end_month,category_allocations,cost_center_allocations,notes,created_by)
    values(v_id,v_tenant,v_company,(v->>'supplier_id')::uuid,v->>'supplier_name',(v->>'document_type_id')::uuid,v->>'description',(v->>'total_amount')::numeric,v_day,v_start,v_end,v->'category_allocations',v->'cost_center_allocations',v->>'notes',auth.uid());
  else
    update apticket.fixed_payables set supplier_id=(v->>'supplier_id')::uuid,supplier_name=v->>'supplier_name',document_type_id=(v->>'document_type_id')::uuid,
      description=v->>'description',total_amount=(v->>'total_amount')::numeric,due_day=v_day,start_month=v_start,end_month=v_end,
      category_allocations=v->'category_allocations',cost_center_allocations=v->'cost_center_allocations',notes=v->>'notes' where id=v_id;
    update apticket.fixed_payable_occurrences set deleted_at=clock_timestamp(),deletion_reason='range_changed'
      where fixed_payable_id=v_id and status='forecast' and deleted_at is null and (competence<v_start or (v_end is not null and competence>v_end));
    if coalesce(p_apply_future,true) then
      update apticket.fixed_payable_occurrences set supplier_id=(v->>'supplier_id')::uuid,supplier_name=v->>'supplier_name',document_type_id=(v->>'document_type_id')::uuid,
        description=v->>'description',total_amount=(v->>'total_amount')::numeric,
        due_date=least((competence+(v_day-1)*interval '1 day')::date,(competence+interval '1 month - 1 day')::date),
        category_allocations=v->'category_allocations',cost_center_allocations=v->'cost_center_allocations',notes=v->>'notes'
        where fixed_payable_id=v_id and status='forecast' and deleted_at is null and competence>=date_trunc('month',timezone('America/Sao_Paulo',clock_timestamp()))::date;
    end if;
  end if;
  perform apticket_finance_private.generate_fixed_forecasts(v_id); return v_id;
end $$;


ALTER FUNCTION apticket.save_fixed_payable(p_id uuid, p_expected_revision integer, p_payload jsonb, p_apply_future boolean) OWNER TO supabase_admin;

--
-- Name: save_fixed_payable_occurrence(uuid, integer, jsonb); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_fixed_payable_occurrence(p_id uuid, p_expected_revision integer, p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare o apticket.fixed_payable_occurrences; v jsonb; v_due date:=(p_payload->>'due_date')::date; begin
  o:=apticket_finance_private.lock_fixed_occurrence(p_id,p_expected_revision);
  v:=apticket_finance_private.normalize_fixed_payload(o.tenant_id,o.operating_company_id,p_payload);
  if v_due is null or not isfinite(v_due) or v_due<o.competence then raise exception using errcode='22023',message='Vencimento inválido para esta competência.'; end if;
  update apticket.fixed_payable_occurrences set supplier_id=(v->>'supplier_id')::uuid,supplier_name=v->>'supplier_name',document_type_id=(v->>'document_type_id')::uuid,
    description=v->>'description',total_amount=(v->>'total_amount')::numeric,due_date=v_due,
    category_allocations=v->'category_allocations',cost_center_allocations=v->'cost_center_allocations',notes=v->>'notes' where id=p_id;
  return true;
end $$;


ALTER FUNCTION apticket.save_fixed_payable_occurrence(p_id uuid, p_expected_revision integer, p_payload jsonb) OWNER TO supabase_admin;

--
-- Name: save_operating_bank_account(uuid, uuid, text, text, text, text, text, text, numeric, boolean); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_operating_bank_account(p_id uuid, p_operating_company_id uuid, p_name text, p_bank_code text, p_bank_name text, p_branch text, p_account_number text, p_account_type text, p_opening_balance numeric, p_is_default boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare v_tenant uuid; v_actor uuid:=auth.uid(); v_id uuid:=coalesce(p_id,gen_random_uuid()); begin
  if not apticket.has_permission(auth.uid(),'financeiro_bancos','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select tenant_id into v_tenant from apticket.operating_companies
    where id=p_operating_company_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Empresa operadora não encontrada.'; end if;
  if v_actor is null or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissão para configurar contas bancárias.';
  end if;
  if length(btrim(coalesce(p_name,''))) not between 2 and 100
    or length(btrim(coalesce(p_bank_name,''))) not between 2 and 120
    or length(btrim(coalesce(p_account_number,''))) not between 1 and 30
    or p_account_type not in ('checking','savings','payment') then
    raise exception using errcode='23514',message='Informe corretamente os dados da conta bancária.';
  end if;
  if p_bank_code is not null and btrim(p_bank_code)!~'^[0-9]{3}$' then
    raise exception using errcode='23514',message='O código do banco deve possuir três dígitos.';
  end if;
  if p_is_default then
    update apticket.operating_bank_accounts set is_default=false,updated_by=v_actor,
      updated_at=clock_timestamp() where tenant_id=v_tenant
      and operating_company_id=p_operating_company_id and is_default;
  end if;
  if p_id is null then
    insert into apticket.operating_bank_accounts(id,tenant_id,operating_company_id,name,bank_code,
      bank_name,branch,account_number,account_type,opening_balance,is_default,created_by,updated_by)
    values(v_id,v_tenant,p_operating_company_id,btrim(p_name),nullif(btrim(p_bank_code),''),
      btrim(p_bank_name),nullif(btrim(p_branch),''),btrim(p_account_number),p_account_type,
      round(coalesce(p_opening_balance,0),2),coalesce(p_is_default,false),v_actor,v_actor);
  else
    if exists(select 1 from apticket.bank_statement_imports where bank_account_id=p_id) then
      raise exception using errcode='23514',message='Conta com extrato importado não pode ser reescrita. Cadastre uma nova conta.';
    end if;
    update apticket.operating_bank_accounts set name=btrim(p_name),
      bank_code=nullif(btrim(p_bank_code),''),bank_name=btrim(p_bank_name),
      branch=nullif(btrim(p_branch),''),account_number=btrim(p_account_number),
      account_type=p_account_type,opening_balance=round(coalesce(p_opening_balance,0),2),
      is_default=coalesce(p_is_default,false),is_active=true,updated_by=v_actor,
      updated_at=clock_timestamp() where id=p_id and tenant_id=v_tenant
      and operating_company_id=p_operating_company_id and deleted_at is null;
    if not found then raise exception using errcode='P0002',message='Conta bancária não encontrada.'; end if;
  end if;
  if not exists(select 1 from apticket.operating_bank_accounts where tenant_id=v_tenant
    and operating_company_id=p_operating_company_id and is_default and deleted_at is null) then
    update apticket.operating_bank_accounts set is_default=true,updated_by=v_actor,
      updated_at=clock_timestamp() where id=v_id;
  end if;
  return v_id;
exception when unique_violation then
  raise exception using errcode='23505',message='Esta conta bancária já está cadastrada.';
end $_$;


ALTER FUNCTION apticket.save_operating_bank_account(p_id uuid, p_operating_company_id uuid, p_name text, p_bank_code text, p_bank_name text, p_branch text, p_account_number text, p_account_type text, p_opening_balance numeric, p_is_default boolean) OWNER TO supabase_admin;

--
-- Name: save_supplier_allocation_rules(uuid, date, jsonb); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_supplier_allocation_rules(p_supplier_contract_id uuid, p_effective_from date, p_rules jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare c apticket.supplier_contracts; v_actor uuid:=auth.uid(); v_set_id uuid;
  v_count integer; v_distinct integer; v_total numeric; v_invalid integer; pending_record record;
begin
  select * into c from apticket.supplier_contracts
    where id=p_supplier_contract_id and deleted_at is null for update;
  if not found or not c.is_active then
    raise exception using errcode='23514',message='Selecione um contrato de fornecedor ativo.';
  end if;
  if v_actor is null or not apticket.has_financial_scope(c.tenant_id,c.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para configurar o rateio.';
  end if;
  if p_effective_from is null or p_effective_from<>date_trunc('month',p_effective_from)::date then
    raise exception using errcode='23514',message='A competencia do rateio deve iniciar no primeiro dia do mes.';
  end if;
  if p_rules is null or jsonb_typeof(p_rules)<>'array' or jsonb_array_length(p_rules)=0 then
    raise exception using errcode='23514',message='Informe ao menos um contrato para o rateio.';
  end if;
  select count(*),count(distinct customer_contract_id),coalesce(sum(percentage),0),
    count(*) filter(where customer_contract_id is null or percentage is null or percentage<=0 or percentage>100)
    into v_count,v_distinct,v_total,v_invalid
  from jsonb_to_recordset(p_rules) as item(customer_contract_id uuid,percentage numeric);
  if v_invalid>0 or v_count<>v_distinct then
    raise exception using errcode='23514',message='Os contratos do rateio devem ser unicos e possuir percentual valido.';
  end if;
  if v_total<>100 then
    raise exception using errcode='23514',message='A soma dos percentuais do rateio deve ser exatamente 100%.';
  end if;
  select count(*) into v_invalid
  from jsonb_to_recordset(p_rules) as item(customer_contract_id uuid,percentage numeric)
  where not exists(select 1 from apticket.contract_financial_terms f
    where f.contract_id=item.customer_contract_id and f.tenant_id=c.tenant_id
      and f.operating_company_id=c.operating_company_id and f.deleted_at is null);
  if v_invalid>0 then
    raise exception using errcode='23514',message='Um contrato de cliente nao pertence a esta empresa operadora.';
  end if;
  select id into v_set_id from apticket.supplier_allocation_rule_sets
    where supplier_contract_id=c.id and effective_from=p_effective_from and deleted_at is null for update;
  if found then
    if exists(select 1 from apticket.supplier_payable_allocations a
      join apticket.supplier_allocation_rules r on r.id=a.allocation_rule_id
      where r.rule_set_id=v_set_id and a.deleted_at is null) then
      raise exception using errcode='23514',message='O rateio desta medicao ja foi utilizado e nao pode ser alterado.';
    end if;
    update apticket.supplier_allocation_rules set deleted_at=clock_timestamp()
      where rule_set_id=v_set_id and deleted_at is null;
  else
    v_set_id:=gen_random_uuid();
    insert into apticket.supplier_allocation_rule_sets(id,tenant_id,operating_company_id,
      supplier_contract_id,effective_from,created_by)
    values(v_set_id,c.tenant_id,c.operating_company_id,c.id,p_effective_from,v_actor);
  end if;
  insert into apticket.supplier_allocation_rules(tenant_id,operating_company_id,rule_set_id,
    customer_contract_id,percentage,created_by)
  select c.tenant_id,c.operating_company_id,v_set_id,item.customer_contract_id,item.percentage,v_actor
  from jsonb_to_recordset(p_rules) as item(customer_contract_id uuid,percentage numeric);
  for pending_record in select id from apticket.supplier_payables
    where supplier_contract_id=c.id and allocation_status='pending_rule'
      and cycle_start>=p_effective_from and deleted_at is null for update
  loop perform apticket_finance_private.apply_fixed_supplier_allocation(pending_record.id); end loop;
  return v_set_id;
end $$;


ALTER FUNCTION apticket.save_supplier_allocation_rules(p_supplier_contract_id uuid, p_effective_from date, p_rules jsonb) OWNER TO supabase_admin;

--
-- Name: save_supplier_approval_policy(uuid, uuid, text, numeric, numeric, jsonb); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_supplier_approval_policy(p_policy_id uuid, p_operating_company_id uuid, p_name text, p_minimum_amount numeric, p_maximum_amount numeric, p_approver_ids jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid;
  v_actor uuid:=auth.uid();
  v_id uuid;
  v_count integer;
  v_distinct integer;
  v_invalid integer;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select tenant_id into v_tenant from apticket.operating_companies
    where id=p_operating_company_id and deleted_at is null for update;
  if not found then
    raise exception using errcode='P0002',message='Empresa operadora nao encontrada.';
  end if;
  if v_actor is null or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para configurar alcadas.';
  end if;
  if length(btrim(coalesce(p_name,''))) not between 2 and 150 then
    raise exception using errcode='23514',message='Informe um nome valido para a alcada.';
  end if;
  if p_minimum_amount is null or p_minimum_amount<0
     or (p_maximum_amount is not null and p_maximum_amount<p_minimum_amount) then
    raise exception using errcode='23514',message='Informe uma faixa de valores valida.';
  end if;
  if p_approver_ids is null or jsonb_typeof(p_approver_ids)<>'array'
     or jsonb_array_length(p_approver_ids)=0 then
    raise exception using errcode='23514',message='Informe ao menos um aprovador.';
  end if;
  select count(*),count(distinct value::uuid) into v_count,v_distinct
    from jsonb_array_elements_text(p_approver_ids);
  if v_count<>v_distinct or v_count>50 then
    raise exception using errcode='23514',message='Os aprovadores devem ser unicos e limitados a cinquenta etapas.';
  end if;
  select count(*) into v_invalid
  from jsonb_array_elements_text(p_approver_ids) item
  where not exists (
    select 1 from apticket.profiles profile
    where profile.id=item.value::uuid and profile.tenant_id=v_tenant and profile.is_active
      and exists(select 1 from apticket.financial_access access
        where access.user_id=profile.id and access.tenant_id=v_tenant and access.can_write
          and access.deleted_at is null
          and (access.operating_company_id is null or access.operating_company_id=p_operating_company_id))
      and coalesce(
        (select permission_override.granted from apticket.user_permissions permission_override
          join apticket.permissions permission on permission.id=permission_override.permission_id
          where permission_override.user_id=profile.id and permission.module='financeiro'
            and permission.action='edit'),
        exists(select 1 from apticket.user_roles user_role
          join apticket.role_permissions role_permission on role_permission.role_id=user_role.role_id
          join apticket.permissions permission on permission.id=role_permission.permission_id
          where user_role.user_id=profile.id and permission.module='financeiro'
            and permission.action='edit'),false));
  if v_invalid>0 then
    raise exception using errcode='23514',message='Todos os aprovadores devem estar ativos e possuir escrita financeira nesta empresa.';
  end if;
  if exists(select 1 from apticket.supplier_approval_policies policy
    where policy.tenant_id=v_tenant and policy.operating_company_id=p_operating_company_id
      and policy.is_active and policy.deleted_at is null and policy.id is distinct from p_policy_id
      and coalesce(policy.maximum_amount,99999999999999.99)>=p_minimum_amount
      and coalesce(p_maximum_amount,99999999999999.99)>=policy.minimum_amount) then
    raise exception using errcode='23514',message='A faixa informada se sobrepoe a outra alcada ativa.';
  end if;
  if p_policy_id is not null then
    select id into v_id from apticket.supplier_approval_policies
      where id=p_policy_id and tenant_id=v_tenant
        and operating_company_id=p_operating_company_id and deleted_at is null for update;
    if not found then
      raise exception using errcode='P0002',message='Alcada nao encontrada.';
    end if;
    if exists(select 1 from apticket.supplier_payable_approval_requests
      where policy_id=v_id) then
      raise exception using errcode='23514',message='Esta alcada ja foi utilizada e nao pode ser alterada. Arquive-a e crie outra.';
    end if;
    update apticket.supplier_approval_policies set name=btrim(p_name),
      minimum_amount=p_minimum_amount,maximum_amount=p_maximum_amount,is_active=true,
      updated_by=v_actor,updated_at=clock_timestamp() where id=v_id;
    update apticket.supplier_approval_policy_steps set deleted_at=clock_timestamp()
      where policy_id=v_id and deleted_at is null;
  else
    v_id:=gen_random_uuid();
    insert into apticket.supplier_approval_policies(id,tenant_id,operating_company_id,name,
      minimum_amount,maximum_amount,created_by,updated_by)
    values(v_id,v_tenant,p_operating_company_id,btrim(p_name),p_minimum_amount,
      p_maximum_amount,v_actor,v_actor);
  end if;
  insert into apticket.supplier_approval_policy_steps(tenant_id,operating_company_id,
    policy_id,step_order,approver_id)
  select v_tenant,p_operating_company_id,v_id,item.ordinality,item.value::uuid
    from jsonb_array_elements_text(p_approver_ids) with ordinality item(value,ordinality);
  return v_id;
exception when invalid_text_representation then
  raise exception using errcode='23514',message='A lista de aprovadores possui um identificador invalido.';
end $$;


ALTER FUNCTION apticket.save_supplier_approval_policy(p_policy_id uuid, p_operating_company_id uuid, p_name text, p_minimum_amount numeric, p_maximum_amount numeric, p_approver_ids jsonb) OWNER TO supabase_admin;

--
-- Name: save_supplier_bank_account(uuid, uuid, uuid, text, text, text, text, text, text, text, text, text, text, text, boolean); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_supplier_bank_account(p_bank_account_id uuid, p_supplier_id uuid, p_operating_company_id uuid, p_label text, p_holder_name text, p_holder_tax_id text, p_bank_code text, p_bank_name text, p_branch text, p_account_number text, p_account_digit text, p_account_type text, p_pix_key_type text, p_pix_key text, p_is_default boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  s apticket.suppliers; v_id uuid;
  v_tax text:=regexp_replace(coalesce(p_holder_tax_id,''),'[^0-9]','','g');
  v_bank_code text:=nullif(regexp_replace(coalesce(p_bank_code,''),'[^0-9]','','g'),'');
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into s from apticket.suppliers where id=p_supplier_id and deleted_at is null for update;
  if not found or not s.is_active then raise exception using errcode='P0002',message='Fornecedor ativo nao encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(s.tenant_id,p_operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para alterar dados bancarios.';
  end if;
  if not exists(select 1 from apticket.operating_companies where id=p_operating_company_id
    and tenant_id=s.tenant_id and deleted_at is null and is_active) then
    raise exception using errcode='23514',message='Empresa operadora invalida.';
  end if;
  if length(btrim(coalesce(p_label,''))) not between 2 and 80
    or length(btrim(coalesce(p_holder_name,''))) not between 2 and 250
    or v_tax !~ '^[0-9]{11}([0-9]{3})?$' then
    raise exception using errcode='23514',message='Informe identificacao, titular e CPF ou CNPJ validos.';
  end if;
  if p_pix_key_type is not null and p_pix_key_type not in ('cpf','cnpj','email','phone','random') then
    raise exception using errcode='23514',message='O tipo da chave PIX e invalido.';
  end if;
  if (nullif(btrim(coalesce(p_pix_key,'')),'') is null)<>(p_pix_key_type is null) then
    raise exception using errcode='23514',message='Informe o tipo e a chave PIX em conjunto.';
  end if;
  if p_account_type is not null and p_account_type not in ('checking','savings','payment') then
    raise exception using errcode='23514',message='O tipo da conta bancaria e invalido.';
  end if;
  if nullif(btrim(coalesce(p_pix_key,'')),'') is null and
    (v_bank_code is null or length(v_bank_code)<>3 or nullif(btrim(coalesce(p_bank_name,'')),'') is null
      or nullif(btrim(coalesce(p_branch,'')),'') is null
      or nullif(btrim(coalesce(p_account_number,'')),'') is null or p_account_type is null) then
    raise exception using errcode='23514',message='Informe uma chave PIX ou os dados completos da conta bancaria.';
  end if;
  if p_is_default then
    update apticket.supplier_bank_accounts set is_default=false,updated_by=auth.uid(),updated_at=clock_timestamp()
    where supplier_id=s.id and operating_company_id=p_operating_company_id and is_default and deleted_at is null;
  end if;
  if p_bank_account_id is null then
    v_id:=gen_random_uuid();
    insert into apticket.supplier_bank_accounts(id,tenant_id,operating_company_id,supplier_id,label,
      holder_name,holder_tax_id,bank_code,bank_name,branch,account_number,account_digit,account_type,
      pix_key_type,pix_key,is_default,created_by,updated_by)
    values(v_id,s.tenant_id,p_operating_company_id,s.id,btrim(p_label),btrim(p_holder_name),v_tax,
      v_bank_code,nullif(btrim(p_bank_name),''),nullif(btrim(p_branch),''),
      nullif(btrim(p_account_number),''),nullif(btrim(p_account_digit),''),p_account_type,
      p_pix_key_type,nullif(btrim(p_pix_key),''),p_is_default,auth.uid(),auth.uid());
  else
    select id into v_id from apticket.supplier_bank_accounts where id=p_bank_account_id
      and supplier_id=s.id and operating_company_id=p_operating_company_id and deleted_at is null for update;
    if not found then raise exception using errcode='P0002',message='Dado bancario nao encontrado.'; end if;
    if exists(select 1 from apticket.supplier_payments where bank_account_id=v_id) then
      raise exception using errcode='23514',message='O dado bancario ja foi utilizado e nao pode ser alterado. Cadastre uma nova conta.';
    end if;
    update apticket.supplier_bank_accounts set label=btrim(p_label),holder_name=btrim(p_holder_name),
      holder_tax_id=v_tax,bank_code=v_bank_code,bank_name=nullif(btrim(p_bank_name),''),
      branch=nullif(btrim(p_branch),''),account_number=nullif(btrim(p_account_number),''),
      account_digit=nullif(btrim(p_account_digit),''),account_type=p_account_type,
      pix_key_type=p_pix_key_type,pix_key=nullif(btrim(p_pix_key),''),is_default=p_is_default,
      is_active=true,updated_by=auth.uid(),updated_at=clock_timestamp() where id=v_id;
  end if;
  if not exists(select 1 from apticket.supplier_bank_accounts where supplier_id=s.id
    and operating_company_id=p_operating_company_id and is_default and is_active and deleted_at is null) then
    update apticket.supplier_bank_accounts set is_default=true,updated_by=auth.uid(),updated_at=clock_timestamp()
    where id=v_id;
  end if;
  return v_id;
end $_$;


ALTER FUNCTION apticket.save_supplier_bank_account(p_bank_account_id uuid, p_supplier_id uuid, p_operating_company_id uuid, p_label text, p_holder_name text, p_holder_tax_id text, p_bank_code text, p_bank_name text, p_branch text, p_account_number text, p_account_digit text, p_account_type text, p_pix_key_type text, p_pix_key text, p_is_default boolean) OWNER TO supabase_admin;

--
-- Name: save_tenant_inter_configuration(uuid, uuid, uuid, text, text, jsonb, timestamp with time zone, text, boolean, boolean, integer); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.save_tenant_inter_configuration(p_actor uuid, p_tenant uuid, p_company uuid, p_environment text, p_account text, p_credentials jsonb, p_expires_at timestamp with time zone, p_fingerprint text, p_activate boolean, p_production_confirmed boolean, p_version integer) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare existing apticket.tenant_inter_configurations; credentials jsonb; secret uuid; k text;
begin
  if not exists(select 1 from apticket.profiles where id=p_actor and tenant_id=p_tenant and is_active)
    or not apticket_finance_private.actor_has_permission(p_actor,p_tenant,'empresa_operadora','edit')
    or not apticket_finance_private.actor_has_permission(p_actor,p_tenant,'configuracoes','view') or not apticket_finance_private.actor_has_permission(p_actor,p_tenant,'financeiro_bancos','edit')
    or not exists(select 1 from apticket.operating_companies where id=p_company and tenant_id=p_tenant and is_active and deleted_at is null)
    or not exists(select 1 from apticket.user_roles ur join apticket.roles r on r.id=ur.role_id and r.tenant_id=ur.tenant_id
      where ur.user_id=p_actor and ur.tenant_id=p_tenant and r.name in ('Admin','Financeiro')) then
    raise exception using errcode='42501',message='Sem permissao para configurar o banco desta empresa operadora.';
  end if;
  if p_environment not in ('sandbox','production') or p_account !~ '^[1-9][0-9]{0,19}$'
    or p_activate is null or p_version is null or (p_activate and p_environment='production' and not coalesce(p_production_confirmed,false))
    or p_credentials is null or jsonb_typeof(p_credentials)<>'object' then
    raise exception using errcode='22023',message='Configuracao invalida.';
  end if;
  perform 1 from apticket.operating_companies where id=p_company and tenant_id=p_tenant for update;
  select * into existing from apticket.tenant_inter_configurations
    where tenant_id=p_tenant and operating_company_id=p_company and environment=p_environment;
  if coalesce(existing.version,0)<>p_version then raise exception using errcode='40001',message='Configuracao alterada por outro usuario.'; end if;
  if existing.secret_id is not null then select decrypted_secret::jsonb into credentials from vault.decrypted_secrets where id=existing.secret_id; end if;
  if exists(select 1 from jsonb_object_keys(p_credentials) key where key not in ('client_id','client_secret','certificate','private_key')) then
    raise exception using errcode='22023',message='Campo invalido.';
  end if;
  credentials:=coalesce(credentials,'{}')||p_credentials;
  foreach k in array array['client_id','client_secret','certificate','private_key'] loop
    if jsonb_typeof(credentials->k) is distinct from 'string' or length(btrim(credentials->>k))=0 or length(credentials->>k)>32768 then
      raise exception using errcode='22023',message='Credenciais incompletas.';
    end if;
  end loop;
  if coalesce(p_expires_at,existing.certificate_expires_at,now())<=now() or coalesce(p_fingerprint,existing.certificate_fingerprint,'')='' then
    raise exception using errcode='22023',message='Certificado invalido.';
  end if;
  if existing.secret_id is null then
    select vault.create_secret(credentials::text,'apticket_inter_'||p_tenant||'_'||p_company||'_'||p_environment) into secret;
  else secret:=existing.secret_id; perform vault.update_secret(secret,credentials::text); end if;
  if p_activate then
    insert into apticket.inter_configuration_audit(tenant_id,operating_company_id,actor_id,environment,action)
      select tenant_id,operating_company_id,p_actor,environment,'deselected' from apticket.tenant_inter_configurations
      where tenant_id=p_tenant and operating_company_id=p_company and environment<>p_environment and is_active;
    update apticket.tenant_inter_configurations set is_active=false,version=version+1,updated_by=p_actor,updated_at=now()
      where tenant_id=p_tenant and operating_company_id=p_company and environment<>p_environment and is_active;
  end if;
  insert into apticket.tenant_inter_configurations(tenant_id,operating_company_id,environment,account,secret_id,
    certificate_expires_at,certificate_fingerprint,is_active,updated_by,version)
  values(p_tenant,p_company,p_environment,p_account,secret,coalesce(p_expires_at,existing.certificate_expires_at),
    coalesce(p_fingerprint,existing.certificate_fingerprint),p_activate,p_actor,p_version+1)
  on conflict(tenant_id,operating_company_id,environment) do update set account=excluded.account,
    certificate_expires_at=excluded.certificate_expires_at,certificate_fingerprint=excluded.certificate_fingerprint,
    is_active=excluded.is_active,updated_by=excluded.updated_by,updated_at=now(),version=excluded.version;
  insert into apticket.inter_configuration_audit(tenant_id,operating_company_id,actor_id,environment,action)
    values(p_tenant,p_company,p_actor,p_environment,case when p_activate then 'selected' else 'saved' end);
end $_$;


ALTER FUNCTION apticket.save_tenant_inter_configuration(p_actor uuid, p_tenant uuid, p_company uuid, p_environment text, p_account text, p_credentials jsonb, p_expires_at timestamp with time zone, p_fingerprint text, p_activate boolean, p_production_confirmed boolean, p_version integer) OWNER TO supabase_admin;

--
-- Name: schedule_collection_policies(date, integer); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.schedule_collection_policies(p_as_of date DEFAULT CURRENT_DATE, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_policy record; v_result jsonb; v_policies int:=0; v_actions int:=0; v_events int:=0;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then
    raise exception using errcode='42501',message='A rotina automática exige credencial de serviço.';
  end if;
  if p_as_of>current_date or p_limit not between 1 and 500 then
    raise exception using errcode='22023',message='Data ou limite inválido para processar a régua.';
  end if;
  for v_policy in select tenant_id,operating_company_id from apticket.collection_policies
    where enabled and deleted_at is null
      and apticket_finance_private.financial_feature_enabled(tenant_id,'collection_rules')
    order by updated_at limit p_limit
  loop
    v_result:=apticket_finance_private.evaluate_collection_policy(v_policy.tenant_id,v_policy.operating_company_id,p_as_of);
    v_policies:=v_policies+1;
    v_actions:=v_actions+coalesce((v_result->>'actions')::int,0);
    v_events:=v_events+coalesce((v_result->>'events')::int,0);
  end loop;
  return jsonb_build_object('policies',v_policies,'actions',v_actions,'events',v_events,
    'limit_reached',v_policies=p_limit);
end $$;


ALTER FUNCTION apticket.schedule_collection_policies(p_as_of date, p_limit integer) OWNER TO supabase_admin;

--
-- Name: schedule_supplier_payment(uuid, uuid, date, text, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.schedule_supplier_payment(p_supplier_payable_id uuid, p_bank_account_id uuid, p_scheduled_date date, p_payment_method text, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; a apticket.supplier_bank_accounts; v_id uuid; v_name text; begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into p from apticket.supplier_payables where id=p_supplier_payable_id
    and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Lancamento nao encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para programar pagamentos.';
  end if;
  -- Sem alçada, a liberação ocorre na mesma transação do agendamento.
  -- Solicitações já em aprovação continuam pelo fluxo original.
  if p.status='scheduled' and p.allocation_status='complete'
    and not apticket_finance_private.financial_feature_enabled(p.tenant_id,'payable_approvals') then
    update apticket.supplier_payables set status='approved' where id=p.id;
    p.status:='approved';
  end if;
  if p.status<>'approved' then
    raise exception using errcode='23514',message='Somente lancamentos aprovados podem ser programados para pagamento.';
  end if;
  if p_scheduled_date is null then
    raise exception using errcode='23514',message='Informe a data programada para o pagamento.';
  end if;
  if p_payment_method not in ('pix','bank_transfer','boleto','other') then
    raise exception using errcode='23514',message='A forma de pagamento e invalida.';
  end if;
  select * into a from apticket.supplier_bank_accounts where id=p_bank_account_id
    and supplier_id=p.supplier_id and tenant_id=p.tenant_id and operating_company_id=p.operating_company_id
    and is_active and deleted_at is null;
  if not found then
    raise exception using errcode='23514',message='Selecione um dado bancario ativo deste fornecedor.';
  end if;
  select id into v_id from apticket.supplier_payments where supplier_payable_id=p.id
    and status in ('scheduled','paid');
  if found then return v_id; end if;
  select name into v_name from apticket.profiles where id=auth.uid() and tenant_id=p.tenant_id and is_active;
  if v_name is null then raise exception using errcode='42501',message='Usuario responsavel nao esta ativo.'; end if;
  v_id:=gen_random_uuid();
  insert into apticket.supplier_payments(id,tenant_id,operating_company_id,supplier_id,
    supplier_payable_id,bank_account_id,payment_method,scheduled_date,scheduled_amount,
    bank_snapshot,scheduling_notes,scheduled_by,scheduled_by_name)
  values(v_id,p.tenant_id,p.operating_company_id,p.supplier_id,p.id,a.id,p_payment_method,
    p_scheduled_date,p.total_amount,
    jsonb_build_object('label',a.label,'holder_name',a.holder_name,'holder_tax_id',a.holder_tax_id,
      'bank_code',a.bank_code,'bank_name',a.bank_name,'branch',a.branch,
      'account_number',a.account_number,'account_digit',a.account_digit,
      'account_type',a.account_type,'pix_key_type',a.pix_key_type,'pix_key',a.pix_key),
    nullif(btrim(p_notes),''),auth.uid(),v_name);
  return v_id;
end $$;


ALTER FUNCTION apticket.schedule_supplier_payment(p_supplier_payable_id uuid, p_bank_account_id uuid, p_scheduled_date date, p_payment_method text, p_notes text) OWNER TO supabase_admin;

