--
-- Name: set_contact_companies(uuid, uuid[]); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.set_contact_companies(p_contact_id uuid, p_company_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid;
  v_ids uuid[];
begin
  select tenant_id into v_tenant from apticket.contacts where id = p_contact_id for update;
  if v_tenant is null or auth.uid() is null or v_tenant <> apticket.current_tenant_id()
     or not (
       apticket.has_permission(auth.uid(), 'contatos', 'edit')
       or apticket.has_permission(auth.uid(), 'contatos', 'create')
     ) then
    raise exception using errcode='42501', message='Sem permissão para alterar os clientes do contato.';
  end if;

  select coalesce(array_agg(value order by first_position), '{}'::uuid[]) into v_ids
  from (
    select value, min(position) as first_position
    from unnest(coalesce(p_company_ids, '{}'::uuid[])) with ordinality as items(value, position)
    group by value
  ) ordered_ids;
  if cardinality(v_ids) = 0 then
    raise exception using errcode='23514', message='Selecione ao menos um cliente.';
  end if;
  if exists (
    select 1 from unnest(v_ids) company_id
    left join apticket.companies company on company.id = company_id and company.tenant_id = v_tenant
    where company.id is null
  ) then
    raise exception using errcode='23503', message='Um dos clientes selecionados é inválido.';
  end if;

  update apticket.contacts set company_id = v_ids[1] where id = p_contact_id;
  delete from apticket.contact_companies
  where contact_id = p_contact_id and not (company_id = any(v_ids));
  insert into apticket.contact_companies(contact_id, company_id, tenant_id)
  select p_contact_id, company_id, v_tenant from unnest(v_ids) company_id
  on conflict do nothing;
end $$;


ALTER FUNCTION apticket.set_contact_companies(p_contact_id uuid, p_company_ids uuid[]) OWNER TO supabase_admin;

--
-- Name: set_fixed_payable_active(uuid, integer, boolean); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.set_fixed_payable_active(p_id uuid, p_expected_revision integer, p_active boolean) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare t apticket.fixed_payables; begin
  select * into t from apticket.fixed_payables where id=p_id and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Conta fixa não encontrada.'; end if;
  perform apticket_finance_private.require_fixed_access(t.tenant_id,t.operating_company_id);
  if p_expected_revision is null or t.revision<>p_expected_revision then raise exception using errcode='40001',message='Esta conta fixa foi alterada. Reabra o cadastro.'; end if;
  if p_active is null then raise exception using errcode='22023',message='Informe a situação da conta fixa.'; end if;
  update apticket.fixed_payables set is_active=p_active where id=p_id;
  if p_active then perform apticket_finance_private.generate_fixed_forecasts(p_id); end if;
  return true;
end $$;


ALTER FUNCTION apticket.set_fixed_payable_active(p_id uuid, p_expected_revision integer, p_active boolean) OWNER TO supabase_admin;

