--
-- Name: submit_csat(text, integer, text); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.submit_csat(_token text, _rating integer, _comment text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'apticket'
    AS $$
BEGIN
  IF _token IS NULL OR length(_token) < 16 THEN
    RAISE EXCEPTION 'invalid token';
  END IF;
  IF _rating IS NULL OR _rating < 1 OR _rating > 5 THEN
    RAISE EXCEPTION 'invalid rating';
  END IF;
  UPDATE apticket.csat_responses
    SET rating = _rating,
        comment = NULLIF(_comment, ''),
        responded_at = now()
    WHERE token = _token AND responded_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'not found or already answered';
  END IF;
END;
$$;


ALTER FUNCTION apticket.submit_csat(_token text, _rating integer, _comment text) OWNER TO postgres;

--
-- Name: submit_supplier_payable_for_approval(uuid); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.submit_supplier_payable_for_approval(p_supplier_payable_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  p apticket.supplier_payables;
  policy apticket.supplier_approval_policies;
  v_request_id uuid:=gen_random_uuid();
  v_actor_name text;
  v_steps integer;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into p from apticket.supplier_payables
    where id=p_supplier_payable_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Lancamento nao encontrado.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissao financeira para enviar o lancamento.';
  end if;
  if not apticket_finance_private.financial_feature_enabled(p.tenant_id,'payable_approvals') then
    raise exception using errcode='23514',message='A alçada de aprovação está desativada nas configurações financeiras.';
  end if;
  if p.status<>'scheduled' then
    raise exception using errcode='23514',message='Somente lancamentos agendados podem ser enviados para aprovacao.';
  end if;
  if p.allocation_status<>'complete' then
    raise exception using errcode='23514',message='Conclua o rateio antes de enviar o lancamento para aprovacao.';
  end if;
  select * into policy from apticket.supplier_approval_policies candidate
    where candidate.tenant_id=p.tenant_id and candidate.operating_company_id=p.operating_company_id
      and candidate.is_active and candidate.deleted_at is null
      and p.total_amount>=candidate.minimum_amount
      and (candidate.maximum_amount is null or p.total_amount<=candidate.maximum_amount)
    order by candidate.minimum_amount desc limit 1 for update;
  if not found then
    raise exception using errcode='23514',message='Nenhuma alcada ativa contempla o valor deste lancamento.';
  end if;
  select name into v_actor_name from apticket.profiles
    where id=auth.uid() and tenant_id=p.tenant_id and is_active;
  if v_actor_name is null then
    raise exception using errcode='42501',message='Usuario responsavel nao esta ativo.';
  end if;
  select count(*) into v_steps from apticket.supplier_approval_policy_steps step
    join apticket.profiles profile on profile.id=step.approver_id
      and profile.tenant_id=step.tenant_id and profile.is_active
    where step.policy_id=policy.id and step.deleted_at is null;
  if v_steps=0 or v_steps<>(select count(*) from apticket.supplier_approval_policy_steps
    where policy_id=policy.id and deleted_at is null) then
    raise exception using errcode='23514',message='A alcada possui aprovador inativo ou nenhuma etapa configurada.';
  end if;
  insert into apticket.supplier_payable_approval_requests(id,tenant_id,operating_company_id,
    supplier_payable_id,policy_id,policy_name,payable_amount,submitted_by,submitted_by_name)
  values(v_request_id,p.tenant_id,p.operating_company_id,p.id,policy.id,policy.name,
    p.total_amount,auth.uid(),v_actor_name);
  insert into apticket.supplier_payable_approval_steps(tenant_id,operating_company_id,
    request_id,step_order,approver_id,approver_name)
  select step.tenant_id,step.operating_company_id,v_request_id,step.step_order,
    step.approver_id,profile.name
  from apticket.supplier_approval_policy_steps step
  join apticket.profiles profile on profile.id=step.approver_id and profile.tenant_id=step.tenant_id
  where step.policy_id=policy.id and step.deleted_at is null order by step.step_order;
  update apticket.supplier_payables set status='awaiting_approval' where id=p.id;
  return v_request_id;
end $$;


ALTER FUNCTION apticket.submit_supplier_payable_for_approval(p_supplier_payable_id uuid) OWNER TO supabase_admin;

--
-- Name: update_employee_position(uuid, text, text, numeric, text, text, date, date); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.update_employee_position(p_position_id uuid, p_cargo text, p_nivel text, p_salario numeric, p_tipo_alteracao text, p_motivo text, p_vigente_de date, p_vigente_ate date DEFAULT NULL::date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare position apticket.funcionario_cargos_salarios; begin
  select * into position from apticket.funcionario_cargos_salarios where id=p_position_id and deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Cargo e salário não encontrados.'; end if;
  if auth.uid() is null or position.tenant_id<>apticket.current_tenant_id()
    or not apticket.has_permission(auth.uid(),'funcionarios','edit') then
    raise exception using errcode='42501',message='Sem permissão para editar cargos e salários.';
  end if;
  if length(btrim(coalesce(p_cargo,'')))<2 or p_salario<0 or p_vigente_de is null
    or length(btrim(coalesce(p_tipo_alteracao,''))) not between 2 and 150
    or (p_vigente_ate is not null and p_vigente_ate<p_vigente_de) then
    raise exception using errcode='23514',message='Revise cargo, salário, tipo de alteração e período de vigência.';
  end if;
  if p_vigente_ate is null and position.vigente_ate is not null and exists(
    select 1 from apticket.funcionario_cargos_salarios other where other.funcionario_id=position.funcionario_id
      and other.id<>position.id and other.vigente_ate is null and other.deleted_at is null) then
    raise exception using errcode='23505',message='Já existe outro cargo e salário vigente. Informe a data final deste registro.';
  end if;
  update apticket.funcionario_cargos_salarios set cargo=btrim(p_cargo),nivel=nullif(btrim(p_nivel),''),
    salario_base=p_salario,tipo_alteracao=btrim(p_tipo_alteracao),motivo=nullif(btrim(p_motivo),''),
    vigente_de=p_vigente_de,vigente_ate=p_vigente_ate,updated_at=clock_timestamp() where id=p_position_id;
  if p_vigente_ate is null then
    update apticket.funcionarios set cargo_atual_id=p_position_id,updated_at=clock_timestamp(),updated_by=auth.uid()
      where id=position.funcionario_id;
  elsif exists(select 1 from apticket.funcionarios where id=position.funcionario_id and cargo_atual_id=p_position_id) then
    update apticket.funcionarios employee set cargo_atual_id=(select id from apticket.funcionario_cargos_salarios other
      where other.funcionario_id=position.funcionario_id and other.id<>position.id and other.vigente_ate is null
        and other.deleted_at is null order by other.vigente_de desc limit 1),updated_at=clock_timestamp(),updated_by=auth.uid()
      where employee.id=position.funcionario_id;
  end if;
end $$;


ALTER FUNCTION apticket.update_employee_position(p_position_id uuid, p_cargo text, p_nivel text, p_salario numeric, p_tipo_alteracao text, p_motivo text, p_vigente_de date, p_vigente_ate date) OWNER TO supabase_admin;

--
-- Name: update_supplier_payable(uuid, integer, text, text, date, date, numeric, text); Type: FUNCTION; Schema: apticket; Owner: supabase_admin
--

CREATE FUNCTION apticket.update_supplier_payable(p_id uuid, p_expected_revision integer, p_document_number text, p_description text, p_competence date, p_due_date date, p_total_amount numeric, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; v_competence date:=date_trunc('month',p_competence)::date;
  v_context text:=coalesce(current_setting('apticket.payable_mutation',true),'');
begin
  p:=apticket_finance_private.prepare_payable_mutation(p_id,p_expected_revision);
  if length(btrim(coalesce(p_document_number,''))) not between 2 and 80
    or length(btrim(coalesce(p_description,''))) not between 2 and 500
    or length(btrim(coalesce(p_reason,''))) not between 3 and 1000
    or v_competence is null or p_due_date is null or p_due_date<v_competence
    or p_total_amount is null or p_total_amount::text in ('NaN','Infinity','-Infinity')
    or p_total_amount<0 or p_total_amount>999999999999.99 or p_total_amount<>round(p_total_amount,2)
    or (p.origin_type='manual' and p_total_amount=0) then
    raise exception using errcode='22023',message='Revise documento, descrição, competência, vencimento, valor e motivo da alteração.';
  end if;
  if p.origin_type<>'manual' and (v_competence<>date_trunc('month',p.cycle_start)::date or p_total_amount<>p.total_amount) then
    raise exception using errcode='P0001',message='O valor e a competência dos lançamentos contratuais são definidos pelo contrato e seus rateios.';
  end if;
  if row(btrim(p_document_number),btrim(p_description),v_competence,p_due_date,p_total_amount)
    is not distinct from row(p.document_number,p.description,date_trunc('month',p.cycle_start)::date,p.due_date,p.total_amount) then
    raise exception using errcode='22023',message='Altere pelo menos um campo do lançamento antes de salvar.';
  end if;
  perform apticket_finance_private.cancel_payable_approvals(p.id,'Lançamento alterado: '||btrim(p_reason));
  perform set_config('apticket.payable_mutation',p.id::text,true);
  update apticket.supplier_payables set document_number=btrim(p_document_number),description=btrim(p_description),
    cycle_start=case when p.origin_type='manual' then v_competence else p.cycle_start end,
    cycle_end=case when p.origin_type='manual' then (v_competence+interval '1 month')::date else p.cycle_end end,
    due_date=p_due_date,total_amount=p_total_amount,
    unit_price=case when p.origin_type='manual' then p_total_amount else p.unit_price end,
    status='scheduled',last_change_reason=btrim(p_reason) where id=p.id;
  perform set_config('apticket.payable_mutation',v_context,true);
  return true;
end $$;


ALTER FUNCTION apticket.update_supplier_payable(p_id uuid, p_expected_revision integer, p_document_number text, p_description text, p_competence date, p_due_date date, p_total_amount numeric, p_reason text) OWNER TO supabase_admin;

--
-- Name: FUNCTION update_supplier_payable(p_id uuid, p_expected_revision integer, p_document_number text, p_description text, p_competence date, p_due_date date, p_total_amount numeric, p_reason text); Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON FUNCTION apticket.update_supplier_payable(p_id uuid, p_expected_revision integer, p_document_number text, p_description text, p_competence date, p_due_date date, p_total_amount numeric, p_reason text) IS 'Edita um lançamento/parcela ainda não pago e sem pagamento ativo; invalida aprovações anteriores. Valor/período contratuais preservados.';


--
-- Name: validar_equipamento_ticket_avulso(); Type: FUNCTION; Schema: apticket; Owner: postgres
--

CREATE FUNCTION apticket.validar_equipamento_ticket_avulso() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_ticket apticket.tickets%rowtype;
  v_equipment apticket.equipments%rowtype;
  v_result record;
begin
  select * into v_ticket from apticket.tickets where id = new.ticket_id;
  select * into v_equipment from apticket.equipments where id = new.equipment_id;
  if v_ticket.id is null or v_equipment.id is null
     or v_ticket.tenant_id <> new.tenant_id
     or v_equipment.tenant_id <> new.tenant_id
     or v_equipment.company_id is distinct from v_ticket.company_id then
    raise exception 'Equipamento não pertence ao cliente e tenant do ticket';
  end if;

  if v_ticket.tipo_atendimento = 'contratual' then
    select * into v_result
    from apticket.resolver_atendimento_ticket(
      v_ticket.tenant_id, v_ticket.company_id, new.equipment_id, v_ticket.created_at
    );
    if v_result.tipo = 'avulso' then
      update apticket.tickets
      set tipo_atendimento = 'avulso',
          motivo_avulso = v_result.motivo,
          contract_id = null,
          sla_policy_id = null,
          sla_first_response_due_at = null,
          sla_resolution_due_at = null,
          sla_breached = false
      where id = v_ticket.id;
      perform apticket.criar_cobranca_ticket_avulso(v_ticket.id);
    elsif v_result.contrato_id is distinct from v_ticket.contract_id then
      update apticket.tickets
      set contract_id = v_result.contrato_id,
          sla_policy_id = v_result.sla_id
      where id = v_ticket.id;
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket.validar_equipamento_ticket_avulso() OWNER TO postgres;

--
-- Name: check_session(); Type: FUNCTION; Schema: apticket_auth_private; Owner: postgres
--

CREATE FUNCTION apticket_auth_private.check_session() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if coalesce(auth.jwt() ->> 'app', '') = 'apticket'
     and not apticket_auth_private.session_is_current() then
    raise sqlstate 'PT401' using message = 'session_revoked';
  end if;
end $$;


ALTER FUNCTION apticket_auth_private.check_session() OWNER TO postgres;

--
-- Name: complete_credential(text, text, text); Type: FUNCTION; Schema: apticket_auth_private; Owner: postgres
--

CREATE FUNCTION apticket_auth_private.complete_credential(_kind text, _token_hash text, _password_hash text) RETURNS TABLE(id uuid, tenant_id uuid, name text, email text, session_version bigint)
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
declare target_id uuid; token_id uuid; claimed_id uuid; active boolean;
begin
  if _token_hash is null or _token_hash !~ '^[0-9a-f]{64}$'
     or _password_hash is null or _password_hash !~ '^[$]2[aby][$]1[2-5][$][./A-Za-z0-9]{53}$' then
    raise invalid_parameter_value using message = 'credential_token_invalid';
  end if;
  if _kind = 'reset' then
    select r.id, r.profile_id into token_id, target_id from apticket.password_resets r
    where r.token_hash = _token_hash and r.accepted_at is null and r.expires_at > clock_timestamp();
  elsif _kind = 'invite' then
    select i.id, i.profile_id into token_id, target_id from apticket.invites i
    where i.token_hash = _token_hash and i.accepted_at is null and i.expires_at > clock_timestamp();
  else raise invalid_parameter_value using message = 'credential_token_invalid';
  end if;
  if target_id is null then raise invalid_parameter_value using message = 'credential_token_invalid'; end if;

  -- Serialize all credential changes for a profile, including different tokens.
  select p.is_active into active from apticket.profiles p where p.id = target_id for update;
  if not found or (_kind = 'reset' and not active) then
    raise invalid_parameter_value using message = 'credential_token_invalid';
  end if;
  if _kind = 'reset' then
    update apticket.password_resets r set accepted_at = clock_timestamp()
    where r.id = token_id and r.accepted_at is null and r.expires_at > clock_timestamp()
    returning r.id into claimed_id;
  else
    update apticket.invites i set accepted_at = clock_timestamp()
    where i.id = token_id and i.accepted_at is null and i.expires_at > clock_timestamp()
    returning i.id into claimed_id;
  end if;
  if claimed_id is null then raise invalid_parameter_value using message = 'credential_token_invalid'; end if;

  update apticket.profiles p set password_hash = _password_hash,
    is_active = case when _kind = 'invite' then true else p.is_active end
  where p.id = target_id;
  update apticket.password_resets r set accepted_at = clock_timestamp()
    where r.profile_id = target_id and r.accepted_at is null;
  update apticket.invites i set accepted_at = clock_timestamp()
    where i.profile_id = target_id and i.accepted_at is null;

  return query select p.id,p.tenant_id,p.name,p.email,p.session_version
    from apticket.profiles p where p.id = target_id;
end $_$;


ALTER FUNCTION apticket_auth_private.complete_credential(_kind text, _token_hash text, _password_hash text) OWNER TO postgres;

--
-- Name: protect_session_version(); Type: FUNCTION; Schema: apticket_auth_private; Owner: postgres
--

CREATE FUNCTION apticket_auth_private.protect_session_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.session_version is distinct from old.session_version
     and current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise insufficient_privilege using message = 'Session version is server-managed';
  end if;
  if new.password_hash is distinct from old.password_hash then
    new.session_version := old.session_version + 1;
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_auth_private.protect_session_version() OWNER TO postgres;

--
-- Name: session_is_current(); Type: FUNCTION; Schema: apticket_auth_private; Owner: postgres
--

CREATE FUNCTION apticket_auth_private.session_is_current() RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare claims jsonb := auth.jwt(); token_version text;
begin
  if coalesce(claims ->> 'app', '') <> 'apticket'
     or coalesce(claims ->> 'role', '') <> 'authenticated' then return false; end if;
  token_version := coalesce(claims ->> 'session_version', '0');
  if token_version !~ '^(0|[1-9][0-9]*)$' then return false; end if;
  return exists (
    select 1 from apticket.profiles p
    where p.id = auth.uid() and p.is_active
      and p.tenant_id::text = claims ->> 'tenant_id'
      and p.session_version = token_version::bigint
  );
exception when invalid_text_representation or numeric_value_out_of_range then
  return false;
end $_$;


ALTER FUNCTION apticket_auth_private.session_is_current() OWNER TO postgres;

--
-- Name: normalize_phone(text); Type: FUNCTION; Schema: apticket_contact_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_contact_private.normalize_phone(value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select case when length(digits) in (10,11) and left(digits,2) <> '55'
    then '55' || digits else digits end
  from (select regexp_replace(value, '[^0-9]', '', 'g') as digits) normalized;
$$;


ALTER FUNCTION apticket_contact_private.normalize_phone(value text) OWNER TO supabase_admin;

--
-- Name: sync_identifiers(); Type: FUNCTION; Schema: apticket_contact_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_contact_private.sync_identifiers() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  delete from apticket_contact_private.identifiers where contact_id=new.id;
  begin
    insert into apticket_contact_private.identifiers(tenant_id,kind,value,contact_id)
      select new.tenant_id,'email',value,new.id
      from unnest(array_remove(array[new.email] || new.secondary_emails, null)) value;
  exception when unique_violation then
    raise exception using errcode='23505',message='Já existe um contato cadastrado com este e-mail.';
  end;
  begin
    insert into apticket_contact_private.identifiers(tenant_id,kind,value,contact_id)
      select new.tenant_id,'phone',value,new.id
      from unnest(array_remove(array[new.phone] || new.secondary_phones, null)) value;
  exception when unique_violation then
    raise exception using errcode='23505',message='Já existe um contato cadastrado com este telefone.';
  end;
  return new;
end $$;


ALTER FUNCTION apticket_contact_private.sync_identifiers() OWNER TO supabase_admin;

--
-- Name: validate_channels(); Type: FUNCTION; Schema: apticket_contact_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_contact_private.validate_channels() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  emails text[];
  phones text[];
begin
  new.email := nullif(lower(btrim(new.email)), '');
  new.phone := nullif(apticket_contact_private.normalize_phone(new.phone), '');
  select coalesce(array_agg(lower(btrim(value)) order by ordinal), '{}') into new.secondary_emails
    from unnest(new.secondary_emails) with ordinality as items(value, ordinal);
  select coalesce(array_agg(apticket_contact_private.normalize_phone(value) order by ordinal), '{}') into new.secondary_phones
    from unnest(new.secondary_phones) with ordinality as items(value, ordinal);
  emails := array_remove(array[new.email] || new.secondary_emails, null);
  phones := array_remove(array[new.phone] || new.secondary_phones, null);
  if exists (select 1 from unnest(new.secondary_emails) value where value is null or value !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(value)>255) then
    raise exception using errcode='23514',message='E-mail secundário inválido.';
  end if;
  if exists (select 1 from unnest(new.secondary_phones) value where value is null or value !~ '^[0-9]{10,15}$') then
    raise exception using errcode='23514',message='Telefone secundário inválido.';
  end if;
  if cardinality(emails) <> (select count(distinct value) from unnest(emails) value) then
    raise exception using errcode='23514',message='Este e-mail já foi informado no contato.';
  end if;
  if cardinality(phones) <> (select count(distinct value) from unnest(phones) value) then
    raise exception using errcode='23514',message='Este telefone já foi informado no contato.';
  end if;
  return new;
end $_$;


ALTER FUNCTION apticket_contact_private.validate_channels() OWNER TO supabase_admin;

--
-- Name: accept_inter_charge_webhook(text, text, jsonb); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.accept_inter_charge_webhook(p_environment text, p_secret_hash text, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  cfg apticket.tenant_inter_configurations;
  item jsonb;
  req apticket.inter_charge_requests;
  event apticket.inter_charge_webhook_events;
  fingerprint text;
  accepted jsonb:='[]'::jsonb;
  ignored integer:=0;
  code text;
  notified text;
  notified_time timestamptz;
begin
  if p_environment is null or p_environment not in ('sandbox','production')
    or p_secret_hash is null or p_secret_hash !~ '^[0-9a-f]{64}$'
    or p_events is null or jsonb_typeof(p_events)<>'array'
    or jsonb_array_length(p_events) not between 1 and 50 then
    raise exception using errcode='22023',message='Callback invalido.';
  end if;
  select * into cfg from apticket.tenant_inter_configurations
    where environment=p_environment and webhook_status='active'
      and webhook_secret_hash=p_secret_hash;
  if not found then raise exception using errcode='42501',message='Webhook nao autorizado.'; end if;
  for item in select value from jsonb_array_elements(p_events) loop
    code:=item->>'codigo_solicitacao';
    notified:=nullif(item->>'situacao','');
    if code is null or code !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      or notified is not null and notified not in (
        'RECEBIDO','A_RECEBER','MARCADO_RECEBIDO','ATRASADO','CANCELADO',
        'EXPIRADO','FALHA_EMISSAO','EM_PROCESSAMENTO','PROTESTO'
      ) then
      raise exception using errcode='22023',message='Evento de callback invalido.';
    end if;
    notified_time:=nullif(item->>'data_hora_situacao','')::timestamptz;
    select * into req from apticket.inter_charge_requests
      where tenant_id=cfg.tenant_id and operating_company_id=cfg.operating_company_id and environment=p_environment
        and bank_request_id=code::uuid and status='submitted' and deleted_at is null;
    if not found then ignored:=ignored+1; continue; end if;
    fingerprint:=encode(extensions.digest(
      concat_ws('|',code,coalesce(notified,''),coalesce(notified_time::text,'')),'sha256'
    ),'hex');
    insert into apticket.inter_charge_webhook_events(
      tenant_id,operating_company_id,request_id,environment,bank_request_id,
      event_fingerprint,notified_status,notified_at
    ) values(
      req.tenant_id,req.operating_company_id,req.id,p_environment,req.bank_request_id,
      fingerprint,notified,notified_time
    ) on conflict(tenant_id,environment,event_fingerprint) do update
      set event_fingerprint=excluded.event_fingerprint
    returning * into event;
    accepted:=accepted||jsonb_build_array(jsonb_build_object(
      'event_id',event.id,'request_id',event.request_id,'status',event.status,
      'attempt_count',event.attempt_count
    ));
  end loop;
  return jsonb_build_object('events',accepted,'ignored',ignored);
end $_$;


ALTER FUNCTION apticket_finance_private.accept_inter_charge_webhook(p_environment text, p_secret_hash text, p_events jsonb) OWNER TO postgres;

--
-- Name: actor_has_permission(uuid, uuid, text, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.actor_has_permission(p_actor uuid, p_tenant uuid, p_module text, p_action text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select exists (
    select 1
    from apticket.profiles profile
    join apticket.permissions permission
      on permission.module = p_module
     and permission.action = p_action
    where profile.id = p_actor
      and profile.tenant_id = p_tenant
      and profile.is_active
      and coalesce(
        (
          select user_permission.granted
          from apticket.user_permissions user_permission
          where user_permission.user_id = p_actor
            and user_permission.tenant_id = p_tenant
            and user_permission.permission_id = permission.id
        ),
        exists (
          select 1
          from apticket.user_roles user_role
          join apticket.roles role
            on role.id = user_role.role_id
           and role.tenant_id = user_role.tenant_id
          join apticket.role_permissions role_permission
            on role_permission.role_id = role.id
           and role_permission.permission_id = permission.id
          where user_role.user_id = p_actor
            and user_role.tenant_id = p_tenant
        )
      )
  );
$$;


ALTER FUNCTION apticket_finance_private.actor_has_permission(p_actor uuid, p_tenant uuid, p_module text, p_action text) OWNER TO supabase_admin;

--
-- Name: apply_contract_default_classification(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.apply_contract_default_classification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare row_data jsonb:=to_jsonb(new); categories jsonb; centers jsonb; category jsonb; center jsonb; v_contract_id uuid;
  v_source_type text; v_direction text; v_actor uuid:=auth.uid(); v_actor_name text;
begin
  if tg_table_name='contas_receber' then
    v_contract_id:=nullif(row_data->>'contrato_id','')::uuid;
    select category_allocations,cost_center_allocations into categories,centers from apticket.contracts
      where id=v_contract_id and tenant_id=new.tenant_id;
    v_source_type:=case row_data->>'origin_type' when 'measurement' then 'measurement_receivable'
      when 'manual' then 'manual_receivable' else 'recurring_receivable' end;
    v_direction:='inflow';
  elsif tg_table_name='supplier_payables' then
    v_contract_id:=nullif(row_data->>'supplier_contract_id','')::uuid;
    select category_allocations,cost_center_allocations into categories,centers from apticket.supplier_contracts
      where id=v_contract_id and tenant_id=new.tenant_id;
    v_source_type:='supplier_payable'; v_direction:='outflow';
  else return new; end if;
  -- Grandfather unclassified historical contracts. New/edited contracts cannot be empty.
  if categories is null and centers is null then return new; end if;
  categories:=apticket_finance_private.normalize_contract_allocation(categories,'category',new.tenant_id,new.operating_company_id,v_direction);
  centers:=apticket_finance_private.normalize_contract_allocation(centers,'cost_center',new.tenant_id,new.operating_company_id,v_direction);
  select value into category from jsonb_array_elements(categories) order by (value->>'percentage')::numeric desc,value->>'item_id' limit 1;
  select value into center from jsonb_array_elements(centers) order by (value->>'percentage')::numeric desc,value->>'item_id' limit 1;
  select name into v_actor_name from apticket.profiles where id=v_actor and tenant_id=new.tenant_id and is_active;
  insert into apticket.financial_entry_classifications(tenant_id,operating_company_id,source_type,source_id,direction,
    financial_category_id,financial_category_code,financial_category_name,cost_center_id,cost_center_code,cost_center_name,
    classified_by,classified_by_name,category_allocations,cost_center_allocations)
  values(new.tenant_id,new.operating_company_id,v_source_type,new.id,v_direction,
    (category->>'item_id')::uuid,category->>'code',category->>'name',
    (center->>'item_id')::uuid,center->>'code',center->>'name',
    case when v_actor_name is null then null else v_actor end,coalesce(v_actor_name,'Sistema'),categories,centers);
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.apply_contract_default_classification() OWNER TO supabase_admin;

--
-- Name: apply_fixed_supplier_allocation(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.apply_fixed_supplier_allocation(p_payable_id uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; v_set apticket.supplier_allocation_rule_sets;
  v_count integer; v_total numeric;
begin
  select * into p from apticket.supplier_payables where id=p_payable_id and deleted_at is null for update;
  if not found then return false; end if;
  if p.allocation_status='complete' and exists(
    select 1 from apticket.supplier_payable_allocations
    where supplier_payable_id=p.id and deleted_at is null
  ) then return true; end if;
  select * into v_set from apticket.supplier_allocation_rule_sets s
    where s.supplier_contract_id=p.supplier_contract_id and s.effective_from<=p.cycle_start
      and s.deleted_at is null order by s.effective_from desc limit 1;
  if not found then return false; end if;
  select count(*),coalesce(sum(percentage),0) into v_count,v_total
    from apticket.supplier_allocation_rules where rule_set_id=v_set.id and deleted_at is null;
  if v_count=0 or v_total<>100 then return false; end if;
  insert into apticket.supplier_payable_allocations(tenant_id,operating_company_id,
    supplier_payable_id,customer_contract_id,allocation_rule_id,customer_name,contract_number,
    metric,quantity,unit_price,percentage,source_snapshot)
  with base as (
    select r.id rule_id,r.customer_contract_id,r.percentage,
      client_contract.numero_contrato,company.name customer_name,
      round(p.total_amount*r.percentage/100,2) base_amount,
      row_number() over(order by r.percentage desc,r.id) row_number
    from apticket.supplier_allocation_rules r
    join apticket.contracts client_contract
      on client_contract.id=r.customer_contract_id and client_contract.tenant_id=r.tenant_id
    join apticket.companies company
      on company.id=client_contract.company_id and company.tenant_id=r.tenant_id
    where r.rule_set_id=v_set.id and r.deleted_at is null
  ), calculated as (select base.*,sum(base_amount) over() allocated_total from base)
  select p.tenant_id,p.operating_company_id,p.id,customer_contract_id,rule_id,
    customer_name,numero_contrato,null,1,
    base_amount+case when row_number=1 then p.total_amount-allocated_total else 0 end,
    percentage,jsonb_build_object('rule_set_id',v_set.id,'rule_id',rule_id,
      'effective_from',v_set.effective_from,'percentage',percentage,'allocation_mode','measurement')
  from calculated;
  if (select coalesce(sum(amount),0) from apticket.supplier_payable_allocations
      where supplier_payable_id=p.id and deleted_at is null)<>p.total_amount then
    raise exception using errcode='23514',message='O rateio nao confere com o valor do lancamento.';
  end if;
  update apticket.supplier_payables set allocation_status='complete' where id=p.id;
  return true;
end $$;


ALTER FUNCTION apticket_finance_private.apply_fixed_supplier_allocation(p_payable_id uuid) OWNER TO supabase_admin;

--
-- Name: assign_measurement_operating_company(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.assign_measurement_operating_company() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_explicit uuid;
  v_fallback uuid;
begin
  if new.medicao_id is null or new.operating_company_id is not null then
    return new;
  end if;

  select terms.operating_company_id into v_explicit
  from apticket.contract_financial_terms as terms
  where terms.contract_id = new.contrato_id
    and terms.tenant_id = new.tenant_id
    and terms.deleted_at is null;

  if v_explicit is not null then
    if exists (
      select 1 from apticket.operating_companies as operator
      where operator.id = v_explicit
        and operator.tenant_id = new.tenant_id
        and operator.deleted_at is null
    ) then
      new.operating_company_id := v_explicit;
    end if;
    return new;
  end if;

  select candidate.id into v_fallback
  from (
    select operator.id, count(*) over () as active_count
    from apticket.operating_companies as operator
    where operator.tenant_id = new.tenant_id
      and operator.deleted_at is null
  ) as candidate
  where candidate.active_count = 1;

  new.operating_company_id := v_fallback;
  return new;
end
$$;


ALTER FUNCTION apticket_finance_private.assign_measurement_operating_company() OWNER TO postgres;

--
-- Name: assign_measurement_operator(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.assign_measurement_operator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare v_operator uuid;
begin
  select operating_company_id into v_operator from apticket.contracts
  where id=new.contrato_id and tenant_id=new.tenant_id;
  if v_operator is null then
    raise exception using errcode='23514',message='O contrato precisa possuir uma empresa operadora ativa.';
  end if;
  if new.operating_company_id is not null and new.operating_company_id<>v_operator then
    raise exception using errcode='23514',message='A empresa da medicao deve ser a mesma do contrato.';
  end if;
  new.operating_company_id:=v_operator;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.assign_measurement_operator() OWNER TO supabase_admin;

--
-- Name: assign_receivable_operator(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.assign_receivable_operator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.operating_company_id is null and new.medicao_id is not null then
    select operating_company_id into new.operating_company_id
    from apticket.medicoes_contrato where id=new.medicao_id and tenant_id=new.tenant_id;
  end if;
  if new.operating_company_id is null then
    raise exception using errcode='23514',message='A conta a receber precisa de uma empresa operadora.';
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.assign_receivable_operator() OWNER TO supabase_admin;

--
-- Name: audit_record(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.audit_record() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare data jsonb := to_jsonb(new);
begin
  insert into apticket.financial_audit_log (
    tenant_id, operating_company_id, entity_table, entity_id, operation,
    actor_id, source, database_role, before_data, after_data
  ) values (
    new.tenant_id,
    case when tg_table_name = 'operating_companies' then (data->>'id')::uuid else (data->>'operating_company_id')::uuid end,
    tg_table_name, coalesce((data->>'id')::uuid, (data->>'contract_id')::uuid), tg_op,
    auth.uid(), case when auth.uid() is null then 'database_or_job' else 'authenticated_request' end,
    current_setting('role'), case when tg_op = 'UPDATE' then to_jsonb(old) else null end, data
  );
  return new;
end;
$$;


ALTER FUNCTION apticket_finance_private.audit_record() OWNER TO postgres;

--
-- Name: auto_apply_fixed_supplier_allocation(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.auto_apply_fixed_supplier_allocation() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.billing_unit='fixed' then
    perform apticket_finance_private.apply_fixed_supplier_allocation(new.id);
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.auto_apply_fixed_supplier_allocation() OWNER TO supabase_admin;

--
-- Name: can_manage_payable_upload(text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.can_manage_payable_upload(p_path text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select auth.uid() is not null and apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit')
    and exists(select 1 from apticket.operating_companies c
      where c.id::text=split_part(p_path,'/',2) and c.tenant_id::text=split_part(p_path,'/',1)
      and split_part(p_path,'/',3)=auth.uid()::text and c.deleted_at is null and c.is_active
      and apticket.has_financial_scope(c.tenant_id,c.id,true))
    and not exists(select 1 from apticket.supplier_payable_attachments a where a.storage_path=p_path);
$$;


ALTER FUNCTION apticket_finance_private.can_manage_payable_upload(p_path text) OWNER TO supabase_admin;

--
-- Name: cancel_payable_approvals(uuid, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.cancel_payable_approvals(p_id uuid, p_reason text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  update apticket.supplier_payable_approval_steps set status='cancelled',decided_at=clock_timestamp(),
    decision_comment=left(p_reason,1000)
    where status='pending' and request_id in
      (select id from apticket.supplier_payable_approval_requests where supplier_payable_id=p_id and status='pending');
  update apticket.supplier_payable_approval_requests set status='cancelled',cancelled_at=clock_timestamp(),
    cancelled_by=auth.uid(),cancellation_reason=left(p_reason,1000),completed_at=coalesce(completed_at,clock_timestamp())
    where supplier_payable_id=p_id and status in ('pending','approved');
end $$;


ALTER FUNCTION apticket_finance_private.cancel_payable_approvals(p_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: category_dependencies(uuid, uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.category_dependencies(p_tenant uuid, p_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 with target as (select * from apticket.financial_categories where id=p_id and tenant_id=p_tenant),
 active_refs as (
   select id from apticket.contracts c where tenant_id=p_tenant and deleted_at is null
     and (financial_category_id=p_id or category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id))
       or exists(select 1 from apticket.contracts_category_allocations a where a.tenant_id=p_tenant and a.contract_id=c.id and a.item_id=p_id))
   union all select id from apticket.supplier_contracts c where tenant_id=p_tenant and deleted_at is null
     and (financial_category_id=p_id or category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id))
       or exists(select 1 from apticket.supplier_contracts_category_allocations a where a.tenant_id=p_tenant and a.contract_id=c.id and a.item_id=p_id))
   union all select id from apticket.fixed_payables where tenant_id=p_tenant and deleted_at is null
     and category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id))
   union all select id from apticket.fixed_payable_occurrences where tenant_id=p_tenant and deleted_at is null and status='forecast'
     and category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id))
   union all select id from apticket.financial_budget_entries where tenant_id=p_tenant and replaced_at is null and financial_category_id=p_id
   union all select id from apticket.funcionario_eventos_financeiros where tenant_id=p_tenant and financial_category_id=p_id
   union all select c.id from apticket.financial_entry_classifications c join apticket.contas_receber r
     on r.id=c.source_id and r.tenant_id=c.tenant_id
     where c.tenant_id=p_tenant and c.replaced_at is null and r.deleted_at is null and r.status_cobranca not in ('recebido','cancelado')
     and c.source_type in ('manual_receivable','measurement_receivable','recurring_receivable')
     and (c.financial_category_id=p_id or c.category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id)))
   union all select c.id from apticket.financial_entry_classifications c join apticket.supplier_payables p
     on p.id=c.source_id and p.tenant_id=c.tenant_id
     where c.tenant_id=p_tenant and c.replaced_at is null and p.deleted_at is null and p.status not in ('paid','cancelled')
     and c.source_type='supplier_payable'
     and (c.financial_category_id=p_id or c.category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id)))
 ), history_refs as (
   select id from apticket.financial_entry_classifications where tenant_id=p_tenant
     and (financial_category_id=p_id or category_allocations @> jsonb_build_array(jsonb_build_object('item_id',p_id)))
   union all select id from apticket.financial_budget_entries where tenant_id=p_tenant and financial_category_id=p_id
   union all select id from apticket.financial_period_snapshot_lines where tenant_id=p_tenant and financial_category_id=p_id
 )
 select jsonb_build_object(
   'children',(select count(*) from apticket.financial_categories c cross join target t
     where c.tenant_id=p_tenant and c.deleted_at is null and c.code like t.code||'.%'
     and (t.is_global or c.operating_company_id=t.operating_company_id)),
   'active_children',(select count(*) from apticket.financial_categories c cross join target t
     where c.tenant_id=p_tenant and c.deleted_at is null and c.is_active and c.code like t.code||'.%'
     and (t.is_global or c.operating_company_id=t.operating_company_id)),
   'active_links',(select count(*) from active_refs),
   'history_links',(select count(*) from history_refs));
$$;


ALTER FUNCTION apticket_finance_private.category_dependencies(p_tenant uuid, p_id uuid) OWNER TO supabase_admin;

--
-- Name: claim_collection_actions(integer); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.claim_collection_actions(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_result jsonb;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then
    raise exception using errcode='42501',message='A fila de cobrança exige credencial de serviço.';
  end if;
  if p_limit not between 1 and 500 then
    raise exception using errcode='22023',message='Limite inválido para a fila de cobrança.';
  end if;
  update apticket.collection_actions set status='failed',last_error='Processamento interrompido antes da confirmação.',
    next_attempt_at=clock_timestamp(),processed_at=clock_timestamp()
  where status='processing' and processed_at<clock_timestamp()-interval '30 minutes';
  with candidates as (
    select id from apticket.collection_actions
    where status in ('pending','failed') and attempt_count<5 and next_attempt_at is not null
      and apticket_finance_private.financial_feature_enabled(tenant_id,'collection_rules')
      and next_attempt_at<=clock_timestamp() and scheduled_for<=current_date
    order by scheduled_for,created_at for update skip locked limit p_limit
  ), claimed as (
    update apticket.collection_actions a set status='processing',attempt_count=a.attempt_count+1,
      processed_at=clock_timestamp(),last_error=null
    from candidates c where a.id=c.id
    returning a.id,a.tenant_id,a.operating_company_id,a.channel,a.attempt_count,
      a.recipient_snapshot,a.content_snapshot
  ) select coalesce(jsonb_agg(to_jsonb(claimed) order by id),'[]'::jsonb) into v_result from claimed;
  return v_result;
end $$;


ALTER FUNCTION apticket_finance_private.claim_collection_actions(p_limit integer) OWNER TO supabase_admin;

--
-- Name: close_financial_period_internal(uuid, date, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.close_financial_period_internal(p_operating_company_id uuid, p_period_month date, p_notes text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_tenant uuid; v_actor_name text; v_id uuid:=gen_random_uuid(); v_revision integer;
  v_line_count integer; v_unclassified integer;
  v_revenue_budgeted numeric(14,2); v_expense_budgeted numeric(14,2);
  v_revenue_planned numeric(14,2); v_expense_planned numeric(14,2);
  v_revenue_realized numeric(14,2); v_expense_realized numeric(14,2);
begin
  if not apticket.has_permission(auth.uid(),'financeiro_fechamento','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select company.tenant_id into v_tenant from apticket.operating_companies company
    where company.id=p_operating_company_id and company.deleted_at is null for update;
  if not found then raise exception using errcode='P0002',message='Empresa operadora não encontrada.'; end if;
  if auth.uid() is null or not apticket.has_financial_scope(v_tenant,p_operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissão financeira para encerrar esta competência.';
  end if;
  if p_period_month is null or p_period_month<>date_trunc('month',p_period_month)::date
    or p_period_month>date_trunc('month',current_date)::date then
    raise exception using errcode='23514',message='Selecione uma competência mensal atual ou anterior.';
  end if;
  if p_notes is not null and length(btrim(p_notes))>1000 then
    raise exception using errcode='22001',message='As observações devem ter no máximo 1000 caracteres.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_operating_company_id::text||p_period_month::text,0));
  if apticket_finance_private.period_is_closed(v_tenant,p_operating_company_id,p_period_month) then
    raise exception using errcode='23505',message='Esta competência já está encerrada.';
  end if;
  select profile.name into v_actor_name from apticket.profiles profile
    where profile.id=auth.uid() and profile.tenant_id=v_tenant and profile.is_active;
  if v_actor_name is null then
    raise exception using errcode='42501',message='Usuário responsável não está ativo.';
  end if;
  select count(*) into v_unclassified from apticket.cash_flow_entries entry
    where entry.tenant_id=v_tenant and entry.operating_company_id=p_operating_company_id
      and entry.cash_status<>'cancelled'
      and (date_trunc('month',entry.planned_date)::date=p_period_month
        or date_trunc('month',entry.realized_date)::date=p_period_month)
      and (entry.financial_category_id is null or entry.cost_center_id is null)
      and (entry.planned_amount<>0 or entry.realized_amount<>0);
  if v_unclassified>0 then
    raise exception using errcode='23514',message=format(
      'Existem %s movimento(s) sem classificação completa nesta competência.',v_unclassified);
  end if;
  select count(*),
    coalesce(sum(variance.budgeted_amount) filter(where variance.direction='inflow'),0),
    coalesce(sum(variance.budgeted_amount) filter(where variance.direction='outflow'),0),
    coalesce(sum(variance.planned_amount) filter(where variance.direction='inflow'),0),
    coalesce(sum(variance.planned_amount) filter(where variance.direction='outflow'),0),
    coalesce(sum(variance.realized_amount) filter(where variance.direction='inflow'),0),
    coalesce(sum(variance.realized_amount) filter(where variance.direction='outflow'),0)
  into v_line_count,v_revenue_budgeted,v_expense_budgeted,v_revenue_planned,
    v_expense_planned,v_revenue_realized,v_expense_realized
  from apticket.financial_budget_variance variance
  where variance.tenant_id=v_tenant and variance.operating_company_id=p_operating_company_id
    and variance.period_month=p_period_month;
  if v_line_count=0 then
    raise exception using errcode='23514',message='Não existem valores financeiros para encerrar nesta competência.';
  end if;
  select coalesce(max(closure.revision),0)+1 into v_revision
  from apticket.financial_period_closures closure
  where closure.tenant_id=v_tenant and closure.operating_company_id=p_operating_company_id
    and closure.period_month=p_period_month;
  insert into apticket.financial_period_closures(
    id,tenant_id,operating_company_id,period_month,revision,
    revenue_budgeted,expense_budgeted,result_budgeted,
    revenue_planned,expense_planned,result_planned,
    revenue_realized,expense_realized,result_realized,snapshot_line_count,
    close_notes,closed_by,closed_by_name
  ) values(
    v_id,v_tenant,p_operating_company_id,p_period_month,v_revision,
    v_revenue_budgeted,v_expense_budgeted,v_revenue_budgeted-v_expense_budgeted,
    v_revenue_planned,v_expense_planned,v_revenue_planned-v_expense_planned,
    v_revenue_realized,v_expense_realized,v_revenue_realized-v_expense_realized,v_line_count,
    nullif(btrim(p_notes),''),auth.uid(),v_actor_name
  );
  insert into apticket.financial_period_snapshot_lines(
    closure_id,tenant_id,operating_company_id,period_month,direction,
    financial_category_id,financial_category_code,financial_category_name,
    cost_center_id,cost_center_code,cost_center_name,budget_entry_id,
    budgeted_amount,planned_amount,realized_amount,favorable_variance_amount,
    favorable_variance_percent,budget_revision,budget_created_by_name,budget_created_at
  )
  select v_id,v_tenant,p_operating_company_id,p_period_month,variance.direction,
    variance.financial_category_id,variance.financial_category_code,variance.financial_category_name,
    variance.cost_center_id,variance.cost_center_code,variance.cost_center_name,
    variance.budget_entry_id,variance.budgeted_amount,variance.planned_amount,
    variance.realized_amount,
    case when variance.direction='inflow' then variance.realized_amount-variance.budgeted_amount
      else variance.budgeted_amount-variance.realized_amount end,
    case when variance.budgeted_amount=0 then null
      when variance.direction='inflow' then round(
        (variance.realized_amount-variance.budgeted_amount)/variance.budgeted_amount*100,2)
      else round((variance.budgeted_amount-variance.realized_amount)/variance.budgeted_amount*100,2)
    end,variance.revision,variance.created_by_name,variance.created_at
  from apticket.financial_budget_variance variance
  where variance.tenant_id=v_tenant and variance.operating_company_id=p_operating_company_id
    and variance.period_month=p_period_month;
  return v_id;
end $$;


ALTER FUNCTION apticket_finance_private.close_financial_period_internal(p_operating_company_id uuid, p_period_month date, p_notes text) OWNER TO supabase_admin;

--
-- Name: close_next_cycle(uuid, date); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.close_next_cycle(p_contract_id uuid, p_as_of date) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare
  f apticket.contract_financial_terms; c apticket.contracts;
  v_start date; v_end date; v_service_start date; v_service_end date; v_month date;
  v_last_end date; v_due date; v_id uuid; v_client text; v_metric text;
  v_items jsonb; v_item jsonb; v_total numeric; v_days integer; v_count integer;
begin
  select * into f from apticket.contract_financial_terms where contract_id=p_contract_id and deleted_at is null for update;
  if not found or not f.billing_enabled then return null; end if;
  select * into c from apticket.contracts where id=p_contract_id and tenant_id=f.tenant_id for update;
  if not found or c.status not in ('active','expired') then return null; end if;
  if not exists(select 1 from apticket.operating_companies where id=f.operating_company_id and deleted_at is null) then return null; end if;
  select max(cycle_end) into v_last_end from apticket.billing_cycles where contract_id=c.id;
  v_month := coalesce(date_trunc('month',v_last_end)::date,f.billing_anchor_month);
  v_start := apticket_finance_private.cutoff_date(v_month,f.cutoff_day);
  v_end := apticket_finance_private.cutoff_date((v_month+make_interval(months=>f.billing_interval_months))::date,f.cutoff_day);
  if v_end > p_as_of then return null; end if;
  if v_end <= c.starts_at then
    raise exception using errcode='23514', message='O primeiro ciclo antecede o início do contrato. Revise o mês âncora.';
  end if;
  v_service_start := greatest(v_start,c.starts_at);
  v_service_end := least(v_end,c.ends_at+1);
  if v_service_start >= v_service_end then return null; end if;
  if exists(select 1 from apticket.contas_receber r where r.contrato_id=c.id and r.medicao_id is not null
    and r.competencia < v_end and (r.competencia+interval '1 month')::date > v_start) then
    raise exception using errcode='23514', message='Já existe cobrança de medição neste ciclo. Revise a transição para recorrência.';
  end if;

  -- Uma linha fixa por versão, com dias reais sobre dias do ciclo completo.
  with periods as (
    select v.*, lead(effective_from,1,v_service_end) over(order by effective_from) until_date
    from apticket.contract_value_versions v where v.contract_id=c.id and v.deleted_at is null
  ), lines as (
    select id,base_amount,greatest(effective_from,v_service_start) a,least(until_date,v_service_end) b from periods
  ) select coalesce(jsonb_agg(jsonb_build_object('kind','fixed','version_id',id,'description','Parcela fixa proporcional',
    'start',a,'end',b,'quantity',b-a,'unit_price',base_amount*f.billing_interval_months,'divisor',v_end-v_start) order by a),'[]'),
    coalesce(sum(b-a),0) into v_items,v_days from lines where b>a;
  if v_days <> v_service_end-v_service_start then
    raise exception using errcode='23514', message='Falta valor contratual vigente para parte do ciclo.';
  end if;

  -- Uma métrica exigida deve cobrir o período inteiro, mesmo quando o consumo for zero.
  foreach v_metric in array f.required_metrics loop
    select coalesce(sum(cycle_end-cycle_start),0),count(*) into v_days,v_count
    from apticket.consumption_snapshots s where s.contract_id=c.id and s.metric=v_metric and s.deleted_at is null
      and s.cycle_start>=v_service_start and s.cycle_end<=v_service_end;
    if v_days <> v_service_end-v_service_start or v_count=0 then
      raise exception using errcode='23514', message='Apuração incompleta para a métrica: '||v_metric;
    end if;
  end loop;
  if exists(select 1 from apticket.consumption_snapshots s where s.contract_id=c.id and s.deleted_at is null
    and s.cycle_start<v_service_end and s.cycle_end>v_service_start
    and (s.cycle_start<v_service_start or s.cycle_end>v_service_end or not s.metric=any(f.required_metrics))) then
    raise exception using errcode='23514', message='Há snapshot fora dos limites ou das métricas configuradas para o ciclo.';
  end if;
  select v_items || coalesce(jsonb_agg(jsonb_build_object('kind','variable','version_id',s.value_version_id,'snapshot_id',s.id,
    'description','Consumo: '||s.metric,'start',s.cycle_start,'end',s.cycle_end,'quantity',s.billable_quantity,
    'unit_price',s.unit_price,'divisor',1) order by s.metric,s.cycle_start),'[]') into v_items
  from apticket.consumption_snapshots s where s.contract_id=c.id and s.deleted_at is null
    and s.cycle_start>=v_service_start and s.cycle_end<=v_service_end and s.metric=any(f.required_metrics);
  select sum(round((j->>'quantity')::numeric*(j->>'unit_price')::numeric/(j->>'divisor')::integer,2)) into v_total
    from jsonb_array_elements(v_items) j;
  v_due := apticket.calcular_vencimento_medicao(date_trunc('month',v_end)::date,c.tipo_vencimento,c.dia_vencimento,c.tenant_id);
  if v_due < v_end then
    v_due := apticket.calcular_vencimento_medicao((date_trunc('month',v_end)+interval '1 month')::date,c.tipo_vencimento,c.dia_vencimento,c.tenant_id);
  end if;
  select name into v_client from apticket.companies where id=c.company_id and tenant_id=c.tenant_id;
  if v_client is null then raise exception using errcode='23514',message='Cliente do contrato inválido.'; end if;
  insert into apticket.billing_cycles(tenant_id,operating_company_id,contract_id,cycle_start,cycle_end,service_start,service_end,total_amount,due_date,terms_snapshot)
    values(c.tenant_id,f.operating_company_id,c.id,v_start,v_end,v_service_start,v_service_end,v_total,v_due,to_jsonb(f)) returning id into v_id;
  for v_item in select * from jsonb_array_elements(v_items) loop
    insert into apticket.billing_cycle_items(tenant_id,operating_company_id,contract_id,billing_cycle_id,value_version_id,
      consumption_snapshot_id,kind,description,period_start,period_end,quantity,unit_price,divisor)
    values(c.tenant_id,f.operating_company_id,c.id,v_id,(v_item->>'version_id')::uuid,(v_item->>'snapshot_id')::uuid,
      v_item->>'kind',v_item->>'description',(v_item->>'start')::date,(v_item->>'end')::date,
      (v_item->>'quantity')::numeric,(v_item->>'unit_price')::numeric,(v_item->>'divisor')::integer);
  end loop;
  insert into apticket.contas_receber(tenant_id,billing_cycle_id,operating_company_id,contrato_id,company_id,cliente_nome,
    documento_referencia,descricao,competencia,valor_original,valor_aberto,vencimento_em,aprovado_em)
  values(c.tenant_id,v_id,f.operating_company_id,c.id,c.company_id,v_client,'REC-'||v_id::text,
    'Ciclo do contrato '||c.numero_contrato||' de '||to_char(v_start,'DD/MM/YYYY')||' a '||to_char(v_end-1,'DD/MM/YYYY'),
    date_trunc('month',v_start)::date,v_total,v_total,v_due,now());
  return v_id;
end $$;


ALTER FUNCTION apticket_finance_private.close_next_cycle(p_contract_id uuid, p_as_of date) OWNER TO postgres;

--
-- Name: confirm_inter_binding(uuid, text, integer, uuid, boolean); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.confirm_inter_binding(p_company uuid, p_environment text, p_configuration_version integer, p_previous_binding uuid, p_confirmed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  c apticket.operating_companies; cfg apticket.tenant_inter_configurations;
  b apticket.operating_company_inter_bindings; tenant_tax text;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_bancos','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null then raise exception using errcode='42501',message='Sessão obrigatória.'; end if;
  if not apticket.has_financial_scope(apticket.current_tenant_id(),p_company,true)
    or not exists(select 1 from apticket.user_roles ur join apticket.roles r on r.id=ur.role_id
      where ur.user_id=auth.uid() and r.tenant_id=apticket.current_tenant_id() and r.name in ('Admin','Financeiro')) then
    raise exception using errcode='42501',message='Exige perfil Admin ou Financeiro com acesso de escrita à empresa.';
  end if;
  if p_environment is null or p_environment not in ('sandbox','production')
    or p_configuration_version is null or p_configuration_version<1 or p_confirmed is distinct from true then
    raise exception using errcode='22023',message='Confirme a empresa, a conta e o ambiente revisados.';
  end if;
  -- Mesma ordem de lock do salvamento de credenciais: tenant antes da configuração.
  select regexp_replace(cnpj,'[^0-9]','','g') into tenant_tax from apticket.tenants
    where id=apticket.current_tenant_id() for update;
  select * into c from apticket.operating_companies where id=p_company
    and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found or c.tax_id is null then
    raise exception using errcode='23514',message='O CNPJ da empresa operadora deve corresponder ao cadastro da tenant.';
  end if;
  select * into cfg from apticket.tenant_inter_configurations where tenant_id=c.tenant_id and operating_company_id=c.id and environment=p_environment;
  if not found then raise exception using errcode='23514',message='Configure este ambiente do Inter antes de vincular.'; end if;
  if cfg.version<>p_configuration_version then
    raise exception using errcode='40001',message='Configuração bancária alterada. Consulte e confirme novamente.';
  end if;
  if cfg.certificate_expires_at<=now() then raise exception using errcode='23514',message='Renove o certificado vencido antes de vincular.'; end if;
  select * into b from apticket.operating_company_inter_bindings
    where tenant_id=c.tenant_id and operating_company_id=c.id and environment=p_environment and deleted_at is null;
  if b.id is not null then
    if b.operating_company_id<>c.id then
      raise exception using errcode='23514',message='Ambiente vinculado a outra empresa. Solicite revisão do vínculo.';
    end if;
    if b.configuration_version=cfg.version and b.company_tax_id=c.tax_id then
      return jsonb_build_object('id',b.id,'reused',true,'dispatch_enabled',false);
    end if;
  end if;
  if b.id is distinct from p_previous_binding then
    raise exception using errcode='40001',message='Vínculo alterado. Consulte e confirme novamente.';
  end if;
  update apticket.operating_company_inter_bindings set deleted_at=now() where id=b.id;
  insert into apticket.operating_company_inter_bindings
    (tenant_id,operating_company_id,environment,configuration_version,company_tax_id,account_last_four,created_by)
    values(c.tenant_id,c.id,p_environment,cfg.version,c.tax_id,right(cfg.account,4),auth.uid()) returning * into b;
  return jsonb_build_object('id',b.id,'reused',false,'dispatch_enabled',false);
end $$;


ALTER FUNCTION apticket_finance_private.confirm_inter_binding(p_company uuid, p_environment text, p_configuration_version integer, p_previous_binding uuid, p_confirmed boolean) OWNER TO postgres;

--
-- Name: confirm_inter_payer(uuid, text, uuid, uuid, boolean); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.confirm_inter_payer(p_request uuid, p_source_fingerprint text, p_binding uuid, p_previous_snapshot uuid, p_confirmed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  req apticket.inter_charge_requests;
  rec apticket.contas_receber;
  customer apticket.companies;
  review jsonb;
  snap apticket.inter_payer_snapshots;
  tax text;
  phone_parts text[];
  ddd text;
  local_phone text;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'Sessão obrigatória.';
  end if;

  select * into req
  from apticket.inter_charge_requests
  where id = p_request
    and tenant_id = apticket.current_tenant_id()
    and deleted_at is null
  for update;

  if not found
    or not apticket.has_financial_scope(req.tenant_id, req.operating_company_id, true)
    or not exists (
      select 1
      from apticket.user_roles as user_role
      join apticket.roles as role on role.id = user_role.role_id
      where user_role.user_id = auth.uid()
        and role.tenant_id = req.tenant_id
        and role.name in ('Admin', 'Financeiro')
    ) then
    raise exception using errcode = '42501',
      message = 'Exige perfil Admin ou Financeiro com acesso de escrita à empresa.';
  end if;

  if p_confirmed is distinct from true
    or p_source_fingerprint is null
    or p_source_fingerprint !~ '^[0-9a-f]{32}$'
    or p_binding is null then
    raise exception using errcode = '22023',
      message = 'Confirme os dados do pagador e o vínculo revisados.';
  end if;

  select * into rec
  from apticket.contas_receber
  where id = req.receivable_id
    and tenant_id = req.tenant_id
    and operating_company_id = req.operating_company_id
    and deleted_at is null
  for update;
  if not found then
    raise exception using errcode = '23514', message = 'Recebível da solicitação indisponível.';
  end if;

  select * into customer
  from apticket.companies
  where id = rec.company_id and tenant_id = req.tenant_id
  for update;
  if not found then
    raise exception using errcode = '23514', message = 'Cliente da solicitação indisponível.';
  end if;

  review := apticket_finance_private.review_inter_payer(req.id);
  if review ->> 'state' = 'missing_data' then
    raise exception using errcode = '23514',
      message = 'Complete os dados obrigatórios do pagador antes de confirmar.';
  end if;
  if review ->> 'state' = 'binding_required' then
    raise exception using errcode = '23514',
      message = 'Confirme o vínculo bancário deste ambiente antes do pagador.';
  end if;
  if review ->> 'source_fingerprint' <> p_source_fingerprint
    or (review ->> 'binding_id')::uuid <> p_binding then
    raise exception using errcode = '40001', message = 'Dados alterados. Consulte e confirme novamente.';
  end if;

  select * into snap
  from apticket.inter_payer_snapshots
  where request_id = req.id and deleted_at is null;
  if snap.id is not null and review ->> 'state' = 'confirmed' then
    return jsonb_build_object('id', snap.id, 'reused', true, 'dispatch_enabled', false);
  end if;
  if snap.id is distinct from p_previous_snapshot then
    raise exception using errcode = '40001',
      message = 'Snapshot alterado. Consulte e confirme novamente.';
  end if;

  update apticket.inter_payer_snapshots set deleted_at = now() where id = snap.id;
  tax := regexp_replace(customer.cnpj, '[^0-9]', '', 'g');
  phone_parts := apticket_finance_private.normalize_inter_phone(customer.phone);
  ddd := phone_parts[1];
  local_phone := phone_parts[2];

  insert into apticket.inter_payer_snapshots (
    tenant_id, operating_company_id, request_id, receivable_id, environment,
    customer_company_id, binding_id, seu_numero, amount, due_date, payer_name,
    payer_tax_id, payer_type, payer_ddd, payer_phone, payer_street, payer_number,
    payer_complement, payer_district, payer_city, payer_state, payer_zip,
    source_fingerprint, source_updated_at, created_by
  ) values (
    req.tenant_id, req.operating_company_id, req.id, req.receivable_id,
    req.environment, customer.id, p_binding, review ->> 'seu_numero', req.amount,
    req.due_date, btrim(customer.name), tax, 'JURIDICA', ddd, local_phone,
    btrim(customer.address_street), btrim(customer.address_number),
    nullif(btrim(customer.address_complement), ''),
    btrim(customer.address_neighborhood), btrim(customer.address_city),
    upper(btrim(customer.address_state)),
    regexp_replace(customer.address_zip, '[^0-9]', '', 'g'),
    p_source_fingerprint, customer.updated_at, auth.uid()
  )
  returning * into snap;

  return jsonb_build_object('id', snap.id, 'reused', false, 'dispatch_enabled', false);
end
$_$;


ALTER FUNCTION apticket_finance_private.confirm_inter_payer(p_request uuid, p_source_fingerprint text, p_binding uuid, p_previous_snapshot uuid, p_confirmed boolean) OWNER TO postgres;

--
-- Name: cutoff_date(date, integer); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.cutoff_date(p_month date, p_day integer) RETURNS date
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
  select date_trunc('month',p_month)::date + (least(p_day,
    extract(day from date_trunc('month',p_month) + interval '1 month - 1 day')::integer)-1);
$$;


ALTER FUNCTION apticket_finance_private.cutoff_date(p_month date, p_day integer) OWNER TO postgres;

--
-- Name: ensure_contract_allocation_target(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.ensure_contract_allocation_target() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.operating_company_id is not null then
    insert into apticket.contract_financial_terms(
      contract_id,tenant_id,operating_company_id,billing_interval_months,cutoff_day,
      adjustment_index,adjustment_interval_months,adjustment_base_date,
      adjustment_notice_days,billing_enabled,required_metrics
    ) values(
      new.id,new.tenant_id,new.operating_company_id,1,
      greatest(1,least(31,coalesce(new.dia_vencimento,1))),
      'fixed',12,new.starts_at,30,false,'{}'::text[]
    ) on conflict (contract_id) do nothing;
  end if;
  return new;
end
$$;


ALTER FUNCTION apticket_finance_private.ensure_contract_allocation_target() OWNER TO supabase_admin;

