--
-- Name: evaluate_collection_policy(uuid, uuid, date); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.evaluate_collection_policy(p_tenant uuid, p_company uuid, p_as_of date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_policy apticket.collection_policies; v_actions int:=0; v_events int:=0;
begin
  if not apticket_finance_private.financial_feature_enabled(p_tenant,'collection_rules') then
    return jsonb_build_object('actions',0,'events',0,'enabled',false);
  end if;
  select * into v_policy from apticket.collection_policies where tenant_id=p_tenant
    and operating_company_id=p_company and enabled and deleted_at is null for update;
  if not found then return jsonb_build_object('actions',0,'events',0,'enabled',false); end if;
  insert into apticket.collection_actions(tenant_id,operating_company_id,policy_id,policy_step_id,
    receivable_id,contract_id,due_date,scheduled_for,channel,recipient_snapshot,content_snapshot)
  select r.tenant_id,r.operating_company_id,v_policy.id,s.id,r.id,r.contrato_id,r.vencimento_em,
    r.vencimento_em+s.days_after_due,s.channel,
    jsonb_build_object('contact_id',recipient.id,'name',coalesce(recipient.name,r.cliente_nome),
      'email',recipient.email,'phone',recipient.phone,'company_id',r.company_id,'customer_name',r.cliente_nome),
    jsonb_build_object('subject',s.subject,'message_template',s.message_template,
      'document',r.documento_referencia,'amount',r.valor_aberto,'due_date',r.vencimento_em)
  from apticket.contas_receber r join apticket.collection_policy_steps s on s.policy_id=v_policy.id
  left join lateral (
    select c.id,c.name,c.email,c.phone from apticket.contacts c
    where c.tenant_id=r.tenant_id and c.company_id=r.company_id and c.is_active
      and ((s.channel='email' and nullif(btrim(c.email),'') is not null)
        or (s.channel in ('whatsapp','sms') and nullif(regexp_replace(coalesce(c.phone,''),'[^0-9]','','g'),'') is not null))
    order by c.can_open_tickets desc,c.created_at,c.id limit 1
  ) recipient on true
  where r.tenant_id=p_tenant and r.operating_company_id=p_company and r.deleted_at is null
    and r.status_cobranca='vencido' and r.valor_aberto>0 and s.enabled and s.deleted_at is null
    and r.vencimento_em+s.days_after_due<=p_as_of
  on conflict(receivable_id,policy_step_id) do nothing;
  get diagnostics v_actions=row_count;
  if v_policy.suspend_after_days is not null then
    insert into apticket.financial_domain_events(tenant_id,operating_company_id,aggregate_type,aggregate_id,
      event_type,source_id,payload)
    select r.tenant_id,r.operating_company_id,'contract',r.contrato_id,'contract.suspended_for_delinquency',r.id,
      jsonb_build_object('receivable_id',r.id,'document',r.documento_referencia,'due_date',r.vencimento_em,
        'open_amount',r.valor_aberto,'days_overdue',p_as_of-r.vencimento_em)
    from apticket.contas_receber r where r.tenant_id=p_tenant and r.operating_company_id=p_company
      and r.deleted_at is null and r.status_cobranca='vencido' and r.valor_aberto>0
      and r.vencimento_em+v_policy.suspend_after_days<=p_as_of
    on conflict(event_type,source_id) do nothing;
    get diagnostics v_events=row_count;
  end if;
  return jsonb_build_object('actions',v_actions,'events',v_events,'enabled',true);
end $$;


ALTER FUNCTION apticket_finance_private.evaluate_collection_policy(p_tenant uuid, p_company uuid, p_as_of date) OWNER TO supabase_admin;

--
-- Name: fill_measurement_billing_terms(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.fill_measurement_billing_terms() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  select contract.billing_type, contract.collection_type
  into new.billing_type, new.collection_type
  from apticket.contracts as contract
  where contract.id = new.contrato_id
    and contract.tenant_id = new.tenant_id;

  if new.billing_type is null or new.collection_type is null then
    raise exception using
      errcode = '23514',
      message = 'Os termos de faturamento e cobranca do contrato nao foram encontrados.';
  end if;

  new.emite_nf := new.billing_type = 'service_invoice';
  new.emite_boleto := new.collection_type in ('boleto_pf', 'boleto_inter_pj');
  return new;
end
$$;


ALTER FUNCTION apticket_finance_private.fill_measurement_billing_terms() OWNER TO supabase_admin;

--
-- Name: fill_supplier_contract_number(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.fill_supplier_contract_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.numero_contrato is null or btrim(new.numero_contrato)='' then
    new.numero_contrato:=apticket_finance_private.next_supplier_contract_number(new.tenant_id);
  end if;
  return new;
end
$$;


ALTER FUNCTION apticket_finance_private.fill_supplier_contract_number() OWNER TO supabase_admin;

--
-- Name: financial_feature_enabled(uuid, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.financial_feature_enabled(p_tenant uuid, p_feature text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
  select case p_feature
    when 'payable_approvals' then coalesce((select use_payable_approvals from apticket.financial_settings where tenant_id=p_tenant),true)
    when 'collection_rules' then coalesce((select use_collection_rules from apticket.financial_settings where tenant_id=p_tenant),true)
    else false end
$$;


ALTER FUNCTION apticket_finance_private.financial_feature_enabled(p_tenant uuid, p_feature text) OWNER TO supabase_admin;

--
-- Name: finish_collection_action(uuid, boolean, text, text, boolean); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.finish_collection_action(p_action uuid, p_success boolean, p_external_id text DEFAULT NULL::text, p_error text DEFAULT NULL::text, p_retryable boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_action apticket.collection_actions;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then
    raise exception using errcode='42501',message='A fila de cobrança exige credencial de serviço.';
  end if;
  select * into v_action from apticket.collection_actions where id=p_action for update;
  if not found or v_action.status<>'processing' then
    raise exception using errcode='40001',message='A ação não está disponível para conclusão.';
  end if;
  if p_success then
    update apticket.collection_actions set status='sent',external_id=nullif(left(p_external_id,500),''),
      last_error=null,next_attempt_at=null,processed_at=clock_timestamp() where id=p_action;
  else
    update apticket.collection_actions set status='failed',last_error=left(coalesce(nullif(p_error,''),'Falha não informada.'),2000),
      next_attempt_at=case when p_retryable and attempt_count<5 then
        clock_timestamp()+make_interval(mins=>least(1440,15*(2^greatest(attempt_count-1,0))::integer)) end,
      processed_at=clock_timestamp() where id=p_action;
  end if;
  return jsonb_build_object('id',p_action,'status',case when p_success then 'sent' else 'failed' end,
    'retryable',not p_success and p_retryable and v_action.attempt_count<5);
end $$;


ALTER FUNCTION apticket_finance_private.finish_collection_action(p_action uuid, p_success boolean, p_external_id text, p_error text, p_retryable boolean) OWNER TO supabase_admin;

--
-- Name: finish_inter_charge_sync(uuid, text, integer, text, text, jsonb); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.finish_inter_charge_sync(p_attempt uuid, p_outcome text, p_http_status integer, p_error_code text, p_error_message text, p_bank_result jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  attempt apticket.inter_charge_sync_attempts;
  req apticket.inter_charge_requests;
  situation text;
  received numeric(14,2);
begin
  if p_outcome not in ('synced','failed')
    or p_http_status is not null and p_http_status not between 100 and 599
    or (p_outcome='synced') is distinct from (p_bank_result is not null) then
    raise exception using errcode='22023',message='Resultado da consulta invalido.';
  end if;
  select * into attempt from apticket.inter_charge_sync_attempts where id=p_attempt for update;
  if not found then raise exception using errcode='P0002',message='Tentativa nao encontrada.'; end if;
  if attempt.status<>'claimed' then
    return jsonb_build_object('state',attempt.status,'request_id',attempt.request_id,'bank_status',attempt.bank_status,'reused',true);
  end if;
  select * into req from apticket.inter_charge_requests where id=attempt.request_id for update;
  if p_outcome='synced' then
    situation:=p_bank_result->>'situacao';
    if situation is null or situation not in ('RECEBIDO','A_RECEBER','MARCADO_RECEBIDO','ATRASADO','CANCELADO',
      'EXPIRADO','FALHA_EMISSAO','EM_PROCESSAMENTO','PROTESTO')
      or coalesce(p_bank_result->>'codigo_solicitacao','')<>req.bank_request_id::text then
      raise exception using errcode='22023',message='Resposta bancaria incompativel com a cobranca.';
    end if;
    if nullif(p_bank_result->>'valor_total_recebido','') is not null then
      received:=(p_bank_result->>'valor_total_recebido')::numeric(14,2);
      if received<0 then raise exception using errcode='22023',message='Valor recebido invalido.'; end if;
    end if;
    update apticket.inter_charge_requests set
      bank_status=situation,bank_status_at=nullif(p_bank_result->>'data_situacao','')::date,
      bank_our_number=left(nullif(p_bank_result->>'nosso_numero',''),30),
      bank_barcode=left(nullif(p_bank_result->>'codigo_barras',''),60),
      bank_digitable_line=left(nullif(p_bank_result->>'linha_digitavel',''),60),
      bank_txid=left(nullif(p_bank_result->>'txid',''),100),
      bank_pix_copy_paste=left(nullif(p_bank_result->>'pix_copia_cola',''),1000),
      bank_received_amount=received,bank_receipt_origin=nullif(p_bank_result->>'origem_recebimento',''),
      bank_synced_at=clock_timestamp(),last_sync_error_code=null,last_sync_error_message=null,updated_at=now()
      where id=req.id;
    update apticket.contas_receber set
      status_cobranca=case
        when situation in ('RECEBIDO','MARCADO_RECEBIDO') then 'recebido'::apticket.status_cobranca_avulsa
        when situation in ('ATRASADO','PROTESTO') then 'vencido'::apticket.status_cobranca_avulsa
        when situation in ('A_RECEBER','EM_PROCESSAMENTO') then 'faturado'::apticket.status_cobranca_avulsa
        else status_cobranca end,
      valor_aberto=case when situation in ('RECEBIDO','MARCADO_RECEBIDO') then 0 else valor_aberto end,
      updated_at=now()
      where id=req.receivable_id and tenant_id=req.tenant_id and deleted_at is null;
  else
    update apticket.inter_charge_requests set last_sync_error_code=left(nullif(p_error_code,''),60),
      last_sync_error_message=left(nullif(p_error_message,''),300),updated_at=now() where id=req.id;
  end if;
  update apticket.inter_charge_sync_attempts set status=p_outcome,http_status=p_http_status,
    bank_status=case when p_outcome='synced' then situation end,
    error_code=case when p_outcome='failed' then left(nullif(p_error_code,''),60) end,
    error_message=case when p_outcome='failed' then left(nullif(p_error_message,''),300) end,
    finished_at=clock_timestamp() where id=attempt.id;
  if attempt.source_event_id is not null then
    update apticket.inter_charge_webhook_events set status=case when p_outcome='synced' then 'verified' else 'failed' end,
      error_code=case when p_outcome='failed' then left(nullif(p_error_code,''),60) end,
      error_message=case when p_outcome='failed' then left(nullif(p_error_message,''),300) end,
      processed_at=clock_timestamp() where id=attempt.source_event_id;
  end if;
  return jsonb_build_object('state',p_outcome,'request_id',req.id,'bank_status',situation,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.finish_inter_charge_sync(p_attempt uuid, p_outcome text, p_http_status integer, p_error_code text, p_error_message text, p_bank_result jsonb) OWNER TO postgres;

--
-- Name: finish_inter_sandbox_dispatch(uuid, text, uuid, integer, text, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.finish_inter_sandbox_dispatch(p_attempt uuid, p_outcome text, p_bank_request uuid, p_http_status integer, p_error_code text, p_error_message text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  attempt apticket.inter_charge_dispatch_attempts;
  req apticket.inter_charge_requests;
begin
  if p_outcome is null or p_outcome not in ('submitted','uncertain','failed')
    or (p_outcome='submitted' and p_bank_request is null)
    or (p_outcome<>'submitted' and p_bank_request is not null)
    or p_http_status is not null and p_http_status not between 100 and 599 then
    raise exception using errcode='22023',message='Resultado inválido.';
  end if;
  select * into attempt from apticket.inter_charge_dispatch_attempts where id=p_attempt for update;
  if not found then raise exception using errcode='P0002',message='Tentativa não encontrada.'; end if;
  if attempt.status<>'claimed' then
    return jsonb_build_object('state',attempt.status,'request_id',attempt.request_id,
      'bank_request_id',attempt.bank_request_id,'reused',true);
  end if;
  select * into req from apticket.inter_charge_requests where id=attempt.request_id for update;
  if req.status<>'dispatching' then raise exception using errcode='40001',message='Estado da solicitação alterado.'; end if;
  update apticket.inter_charge_dispatch_attempts set status=p_outcome,bank_request_id=p_bank_request,
    http_status=p_http_status,error_code=left(nullif(p_error_code,''),60),
    error_message=left(nullif(p_error_message,''),300),finished_at=clock_timestamp() where id=attempt.id;
  update apticket.inter_charge_requests set status=p_outcome,bank_request_id=p_bank_request,
    bank_status=case when p_outcome='submitted' then 'EM_PROCESSAMENTO' else null end,
    bank_accepted_at=case when p_outcome='submitted' then clock_timestamp() else null end,
    last_error_code=left(nullif(p_error_code,''),60),last_error_message=left(nullif(p_error_message,''),300),
    updated_at=now() where id=req.id;
  return jsonb_build_object('state',p_outcome,'request_id',req.id,'bank_request_id',p_bank_request,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.finish_inter_sandbox_dispatch(p_attempt uuid, p_outcome text, p_bank_request uuid, p_http_status integer, p_error_code text, p_error_message text) OWNER TO postgres;

--
-- Name: finish_inter_webhook_registration(uuid, text, integer, text, text, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.finish_inter_webhook_registration(p_attempt uuid, p_outcome text, p_http_status integer, p_error_code text, p_error_message text, p_candidate_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  attempt apticket.inter_webhook_registration_attempts;
  cfg apticket.tenant_inter_configurations;
  secret uuid;
begin
  if p_outcome not in ('registered','failed')
    or p_http_status is not null and p_http_status not between 100 and 599
    or (p_outcome='registered' and (
      p_candidate_token is null or length(p_candidate_token)<>64
      or encode(extensions.digest(p_candidate_token,'sha256'),'hex') is distinct from
        (select candidate_secret_hash from apticket.inter_webhook_registration_attempts where id=p_attempt)
    )) then
    raise exception using errcode='22023',message='Resultado de configuracao do webhook invalido.';
  end if;
  select * into attempt from apticket.inter_webhook_registration_attempts where id=p_attempt for update;
  if not found then raise exception using errcode='P0002',message='Tentativa nao encontrada.'; end if;
  if attempt.status<>'claimed' then
    return jsonb_build_object('state',attempt.status,'reused',true);
  end if;
  select * into cfg from apticket.tenant_inter_configurations
    where tenant_id=attempt.tenant_id and operating_company_id=attempt.operating_company_id and environment=attempt.environment for update;
  if cfg.version<>attempt.configuration_version then
    raise exception using errcode='40001',message='Configuracao bancaria mudou durante o registro.';
  end if;
  if p_outcome='registered' then
    if cfg.webhook_secret_id is null then
      select vault.create_secret(
        p_candidate_token,'apticket_inter_webhook_'||attempt.tenant_id||'_'||attempt.environment
      ) into secret;
    else
      secret:=cfg.webhook_secret_id;
      perform vault.update_secret(secret,p_candidate_token);
    end if;
    update apticket.tenant_inter_configurations set
      webhook_status='active',webhook_callback_base_url=attempt.callback_base_url,
      webhook_secret_hash=attempt.candidate_secret_hash,webhook_secret_id=secret,
      webhook_registered_at=clock_timestamp(),
      webhook_updated_at=clock_timestamp(),webhook_last_error_code=null,webhook_last_error_message=null
      where tenant_id=attempt.tenant_id and operating_company_id=attempt.operating_company_id and environment=attempt.environment;
  else
    update apticket.tenant_inter_configurations set
      webhook_status=case when webhook_secret_hash is not null then 'active' else 'failed' end,
      webhook_updated_at=clock_timestamp(),webhook_last_error_code=left(nullif(p_error_code,''),60),
      webhook_last_error_message=left(nullif(p_error_message,''),300)
      where tenant_id=attempt.tenant_id and operating_company_id=attempt.operating_company_id and environment=attempt.environment;
  end if;
  update apticket.inter_webhook_registration_attempts set status=p_outcome,http_status=p_http_status,
    error_code=case when p_outcome='failed' then left(nullif(p_error_code,''),60) end,
    error_message=case when p_outcome='failed' then left(nullif(p_error_message,''),300) end,
    finished_at=clock_timestamp() where id=attempt.id;
  return jsonb_build_object('state',p_outcome,'environment',attempt.environment,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.finish_inter_webhook_registration(p_attempt uuid, p_outcome text, p_http_status integer, p_error_code text, p_error_message text, p_candidate_token text) OWNER TO postgres;

--
-- Name: generate_fixed_forecasts(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.generate_fixed_forecasts(p_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare t apticket.fixed_payables; v_end date; v_count integer;
begin
  select * into t from apticket.fixed_payables where id=p_id for update;
  if not found or not t.is_active or t.deleted_at is not null then return 0; end if;
  v_end:=coalesce(t.end_month,(greatest(t.start_month,date_trunc('month',timezone('America/Sao_Paulo',clock_timestamp()))::date)+interval '11 months')::date);
  insert into apticket.fixed_payable_occurrences(tenant_id,operating_company_id,fixed_payable_id,competence,
    supplier_id,supplier_name,document_type_id,description,total_amount,due_date,category_allocations,cost_center_allocations,notes,created_by)
  select t.tenant_id,t.operating_company_id,t.id,m::date,t.supplier_id,t.supplier_name,t.document_type_id,t.description,t.total_amount,
    least((m+(t.due_day-1)*interval '1 day')::date,(m+interval '1 month - 1 day')::date),t.category_allocations,t.cost_center_allocations,t.notes,auth.uid()
  from generate_series(t.start_month::timestamp,v_end::timestamp,interval '1 month') m
  where not exists(select 1 from apticket.fixed_payable_occurrences o where o.fixed_payable_id=t.id and o.competence=m::date and (o.deleted_at is null or o.deletion_reason='skipped'))
  on conflict(tenant_id,fixed_payable_id,competence) where deleted_at is null do nothing;
  get diagnostics v_count=row_count; return v_count;
end $$;


ALTER FUNCTION apticket_finance_private.generate_fixed_forecasts(p_id uuid) OWNER TO supabase_admin;

