--
-- Name: guard_receivable_cycle(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.guard_receivable_cycle() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare f apticket.contract_financial_terms;
begin
  if tg_op='UPDATE' then
    if row(new.billing_cycle_id,new.operating_company_id) is distinct from row(old.billing_cycle_id,old.operating_company_id) then
      raise exception using errcode='23514', message='A origem e a empresa da cobrança não podem ser alteradas.';
    end if;
  else
    select * into f from apticket.contract_financial_terms where contract_id=new.contrato_id for update;
    if new.medicao_id is not null and found and (
      (f.billing_enabled and new.competencia >= f.billing_anchor_month)
      or exists(select 1 from apticket.billing_cycles b where b.contract_id=new.contrato_id
        and b.cycle_start < (new.competencia + interval '1 month')::date and b.cycle_end > new.competencia)) then
      raise exception using errcode='23514', message='Este período utiliza faturamento recorrente. A medição não pode gerar cobrança duplicada.';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.guard_receivable_cycle() OWNER TO postgres;

--
-- Name: guard_record(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.guard_record() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op in ('DELETE', 'TRUNCATE') then
    raise exception using errcode = '23514', message = 'Dados financeiros não permitem exclusão física. Utilize exclusão lógica.';
  end if;
  if tg_op = 'UPDATE' then
    if tg_table_name = 'financial_audit_log' then
      raise exception using errcode = '23514', message = 'A auditoria financeira é imutável.';
    end if;
    -- Coluna generated ainda não foi calculada no BEFORE UPDATE.
    if (to_jsonb(new) - array['deleted_at', 'billable_quantity']) is distinct from (to_jsonb(old) - array['deleted_at', 'billable_quantity'])
       and tg_table_name in ('contract_value_versions', 'consumption_snapshots') then
      raise exception using errcode = '23514', message = 'Histórico financeiro e snapshots são imutáveis. Gere um novo registro.';
    end if;
    if new.tenant_id is distinct from old.tenant_id
       or (to_jsonb(new)->'id') is distinct from (to_jsonb(old)->'id')
       or (to_jsonb(new)->'contract_id') is distinct from (to_jsonb(old)->'contract_id')
       or (to_jsonb(new)->'operating_company_id') is distinct from (to_jsonb(old)->'operating_company_id')
       or (to_jsonb(new)->'user_id') is distinct from (to_jsonb(old)->'user_id')
       or (to_jsonb(new)->'created_at') is distinct from (to_jsonb(old)->'created_at') then
      raise exception using errcode = '23514', message = 'Identidade, empresa e tenant do registro financeiro não podem ser alterados.';
    end if;
  end if;
  return new;
end;
$$;


ALTER FUNCTION apticket_finance_private.guard_record() OWNER TO postgres;

