    AS $$
begin
  if row(new.tenant_id,new.operating_company_id,new.supplier_id,new.created_by,new.created_at)
    is distinct from row(old.tenant_id,old.operating_company_id,old.supplier_id,old.created_by,old.created_at) then
    raise exception using errcode='23514',message='O escopo do dado bancario nao pode ser alterado.';
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.guard_supplier_bank_account() OWNER TO supabase_admin;

--
-- Name: guard_supplier_payable(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.guard_supplier_payable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare v_context text:=current_setting('apticket.payable_mutation',true); v_generated text[];
begin
  -- Colunas geradas ainda estão nulas no NEW de um BEFORE UPDATE.
  select coalesce(array_agg(attname::text),'{}'::text[]) into v_generated from pg_attribute
    where attrelid=tg_relid and attgenerated<>'' and not attisdropped;
  if tg_table_name='supplier_payable_allocations' then
    if v_context=new.supplier_payable_id::text and old.deleted_at is null and new.deleted_at is not null
      and to_jsonb(new)-v_generated-'deleted_at'=to_jsonb(old)-v_generated-'deleted_at' then return new; end if;
    raise exception using errcode='23514',message='O rateio gerado é imutável.';
  end if;
  new.revision:=old.revision+1;
  new.updated_at:=clock_timestamp();
  new.updated_by:=coalesce(auth.uid(),old.updated_by);
  if v_context=old.id::text then
    if old.deleted_at is not null or old.status='paid'
      or (to_jsonb(new)-v_generated-array['document_number','description','cycle_start','cycle_end','due_date',
        'unit_price','total_amount','status','deleted_at','revision','updated_at','updated_by','last_change_reason'])
        is distinct from
        (to_jsonb(old)-v_generated-array['document_number','description','cycle_start','cycle_end','due_date',
        'unit_price','total_amount','status','deleted_at','revision','updated_at','updated_by','last_change_reason']) then
      raise exception using errcode='23514',message='A alteração financeira solicitada não é permitida.';
    end if;
    return new;
  end if;
  if new.allocation_status is distinct from old.allocation_status then
    if old.allocation_status='pending_rule' and new.allocation_status='complete' then return new; end if;
    raise exception using errcode='23514',message='A situacao do rateio nao pode retroceder.';
  end if;
  if new.status is distinct from old.status then
    if (old.status='scheduled' and new.status='awaiting_approval' and new.allocation_status='complete')
      or (old.status='awaiting_approval' and new.status in ('approved','scheduled'))
      or (old.status='scheduled' and new.status='approved' and new.allocation_status='complete'
        and not apticket_finance_private.financial_feature_enabled(new.tenant_id,'payable_approvals'))
      or (old.status='approved' and new.status='paid') then return new; end if;
    raise exception using errcode='23514',message='A transicao financeira deste lancamento nao e permitida.';
  end if;
  if new.deleted_at is distinct from old.deleted_at then return new; end if;
  raise exception using errcode='23514',message='O lancamento gerado e imutavel.';
end $$;


ALTER FUNCTION apticket_finance_private.guard_supplier_payable() OWNER TO supabase_admin;

--
-- Name: guard_supplier_payment(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.guard_supplier_payment() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if to_jsonb(new)-array['status','paid_at','paid_amount','reconciliation_status','difference_amount',
      'transaction_reference','settlement_notes','receipt_bucket','receipt_path','receipt_file_name',
      'receipt_mime_type','receipt_size','settled_by','settled_by_name','cancelled_at','cancelled_by',
      'cancelled_by_name','cancellation_reason','updated_at']
    is distinct from
    to_jsonb(old)-array['status','paid_at','paid_amount','reconciliation_status','difference_amount',
      'transaction_reference','settlement_notes','receipt_bucket','receipt_path','receipt_file_name',
      'receipt_mime_type','receipt_size','settled_by','settled_by_name','cancelled_at','cancelled_by',
      'cancelled_by_name','cancellation_reason','updated_at'] then
    raise exception using errcode='23514',message='A programacao do pagamento e imutavel.';
  end if;
  if new.status is distinct from old.status and not
    (old.status='scheduled' and new.status in ('paid','cancelled')) then
    raise exception using errcode='23514',message='A transicao deste pagamento nao e permitida.';
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.guard_supplier_payment() OWNER TO supabase_admin;

--
-- Name: invalidate_inter_webhook_on_credentials_change(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.invalidate_inter_webhook_on_credentials_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.version is distinct from old.version then
    new.webhook_status := 'not_configured';
    new.webhook_callback_base_url := null;
    new.webhook_secret_hash := null;
    new.webhook_registered_at := null;
    new.webhook_updated_at := clock_timestamp();
    new.webhook_last_error_code := null;
    new.webhook_last_error_message := null;
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.invalidate_inter_webhook_on_credentials_change() OWNER TO postgres;

--
-- Name: is_valid_cnpj(text); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.is_valid_cnpj(value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog'
    AS $_$
declare digits text:=regexp_replace(value,'[^0-9]','','g'); total integer; remainder integer; d1 integer; d2 integer; i integer;
begin
  if digits !~ '^[0-9]{14}$' or digits=repeat(left(digits,1),14) then return false; end if;
  total:=0;
  for i in 1..12 loop total:=total+substring(digits,i,1)::integer*(array[5,4,3,2,9,8,7,6,5,4,3,2])[i]; end loop;
  remainder:=11-(total%11); d1:=case when remainder>=10 then 0 else remainder end;
  total:=0;
  for i in 1..13 loop total:=total+substring(digits,i,1)::integer*(array[6,5,4,3,2,9,8,7,6,5,4,3,2])[i]; end loop;
  remainder:=11-(total%11); d2:=case when remainder>=10 then 0 else remainder end;
  return right(digits,2)=(d1::text||d2::text);
end $_$;


ALTER FUNCTION apticket_finance_private.is_valid_cnpj(value text) OWNER TO postgres;

--
-- Name: link_payable_attachments(uuid, jsonb); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.link_payable_attachments(p_group uuid, p_attachments jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare item jsonb; payable apticket.supplier_payables; obj storage.objects;
begin
  if auth.uid() is null or not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit') then
    raise exception using errcode='42501',message='Sem permissão para incluir anexos.';
  end if;
  if p_attachments is null or jsonb_typeof(p_attachments)<>'array' then
    raise exception using errcode='22023',message='Informe uma lista válida de anexos.';
  end if;
  if jsonb_array_length(p_attachments)>20 then
    raise exception using errcode='22023',message='Inclua no máximo 20 anexos por lançamento.';
  end if;
  for item in select value from jsonb_array_elements(p_attachments) loop
    if jsonb_typeof(item)<>'object' or coalesce(item->>'installment_number','')!~'^[1-9][0-9]{0,2}$' then
      raise exception using errcode='22023',message='Selecione a parcela de cada anexo.';
    end if;
    select * into payable from apticket.supplier_payables
      where manual_entry_group_id=p_group and installment_number=(item->>'installment_number')::integer
      and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
    if not found or not apticket.has_financial_scope(payable.tenant_id,payable.operating_company_id,true) then
      raise exception using errcode='42501',message='Parcela indisponível para este anexo.';
    end if;
    if not apticket_finance_private.can_manage_payable_upload(item->>'storage_path')
      or split_part(item->>'storage_path','/',1)<>payable.tenant_id::text
      or split_part(item->>'storage_path','/',2)<>payable.operating_company_id::text then
      raise exception using errcode='42501',message='Arquivo indisponível para esta empresa.';
    end if;
    select * into obj from storage.objects where bucket_id='supplier-payable-attachments'
      and name=item->>'storage_path' for update;
    if not found then raise exception using errcode='23514',message='Envie o arquivo antes de salvar o anexo.'; end if;
    if coalesce(item->>'file_size','')!~'^[1-9][0-9]{0,7}$'
      or (item->>'file_size')::bigint is distinct from (obj.metadata->>'size')::bigint then
      raise exception using errcode='23514',message='O tamanho do anexo não corresponde ao arquivo enviado.';
    end if;
    insert into apticket.supplier_payable_attachments(tenant_id,operating_company_id,supplier_payable_id,
      storage_path,file_name,file_size,content_type,attachment_type,type_description,created_by)
    values(payable.tenant_id,payable.operating_company_id,payable.id,item->>'storage_path',
      btrim(item->>'file_name'),(item->>'file_size')::bigint,coalesce(obj.metadata->>'mimetype','application/octet-stream'),
      item->>'attachment_type',case when item->>'attachment_type'='outros' then nullif(btrim(item->>'type_description'),'') end,auth.uid());
  end loop;
end $_$;


ALTER FUNCTION apticket_finance_private.link_payable_attachments(p_group uuid, p_attachments jsonb) OWNER TO supabase_admin;

--
-- Name: load_inter_charge_dispatch(uuid, uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.load_inter_charge_dispatch(p_attempt uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  attempt apticket.inter_charge_dispatch_attempts;
  req apticket.inter_charge_requests;
  snap apticket.inter_payer_snapshots;
  binding apticket.operating_company_inter_bindings;
  cfg apticket.tenant_inter_configurations;
  credentials jsonb;
begin
  select * into attempt from apticket.inter_charge_dispatch_attempts where id=p_attempt for update;
  if not found or attempt.created_by<>p_actor
    or attempt.environment not in ('sandbox','production') or attempt.status<>'claimed'
    or attempt.started_at<clock_timestamp()-interval '2 minutes' then
    raise exception using errcode='40001',message='Tentativa indisponível ou expirada.';
  end if;
  select * into req from apticket.inter_charge_requests where id=attempt.request_id for update;
  select * into snap from apticket.inter_payer_snapshots where id=attempt.snapshot_id and deleted_at is null;
  select * into binding from apticket.operating_company_inter_bindings where id=attempt.binding_id and deleted_at is null;
  select * into cfg from apticket.tenant_inter_configurations
    where tenant_id=attempt.tenant_id and operating_company_id=attempt.operating_company_id and environment=attempt.environment;
  if req.status<>'dispatching' or req.environment<>attempt.environment
    or snap.id is null or binding.id is null or cfg.tenant_id is null
    or cfg.version<>binding.configuration_version or cfg.certificate_expires_at<=now()
    or req.amount<>snap.amount or req.due_date<>snap.due_date
    or (attempt.environment='production' and (
      not cfg.is_active or cfg.webhook_status<>'active' or cfg.webhook_secret_id is null
      or attempt.production_confirmed_at is null
    )) then
    raise exception using errcode='23514',message='Origem, snapshot ou configuração bancária deixou de ser válida.';
  end if;
  select decrypted_secret::jsonb into credentials from vault.decrypted_secrets where id=cfg.secret_id;
  if credentials is null or exists(
    select 1 from unnest(array['client_id','client_secret','certificate','private_key']) k
    where jsonb_typeof(credentials->k) is distinct from 'string' or length(btrim(credentials->>k))=0
  ) then
    raise exception using errcode='22023',message='Credenciais bancárias incompletas.';
  end if;
  return jsonb_build_object(
    'attempt_id',attempt.id,'actor_id',attempt.created_by,'environment',attempt.environment,'account',cfg.account,
    'token_cache_key',cfg.tenant_id::text||':'||attempt.operating_company_id::text||':'||attempt.environment||':'||cfg.version::text||':'||cfg.certificate_fingerprint,
    'credentials',credentials,
    'charge',jsonb_build_object(
      'seuNumero',snap.seu_numero,'valorNominal',snap.amount,'dataVencimento',snap.due_date,
      'pagador',jsonb_strip_nulls(jsonb_build_object(
        'email',snap.payer_email,'ddd',snap.payer_ddd,'telefone',snap.payer_phone,
        'numero',snap.payer_number,'complemento',snap.payer_complement,'cpfCnpj',snap.payer_tax_id,
        'tipoPessoa',snap.payer_type,'nome',snap.payer_name,'endereco',snap.payer_street,
        'bairro',snap.payer_district,'cidade',snap.payer_city,'uf',snap.payer_state,'cep',snap.payer_zip
      )),'formasRecebimento',jsonb_build_array('BOLETO','PIX')
    )
  );
end $$;


ALTER FUNCTION apticket_finance_private.load_inter_charge_dispatch(p_attempt uuid, p_actor uuid) OWNER TO supabase_admin;

--
-- Name: load_inter_charge_sync(uuid, uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.load_inter_charge_sync(p_attempt uuid, p_actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  attempt apticket.inter_charge_sync_attempts;
  req apticket.inter_charge_requests;
  binding apticket.operating_company_inter_bindings;
  cfg apticket.tenant_inter_configurations;
  credentials jsonb;
begin
  select * into attempt from apticket.inter_charge_sync_attempts where id=p_attempt for update;
  if not found or attempt.created_by<>p_actor or attempt.status<>'claimed'
    or attempt.started_at<clock_timestamp()-interval '2 minutes' then
    raise exception using errcode='40001',message='Tentativa de consulta indisponível ou expirada.';
  end if;
  select * into req from apticket.inter_charge_requests where id=attempt.request_id for update;
  select * into binding from apticket.operating_company_inter_bindings
    where tenant_id=attempt.tenant_id and operating_company_id=attempt.operating_company_id
      and environment=attempt.environment and deleted_at is null;
  select * into cfg from apticket.tenant_inter_configurations
    where tenant_id=attempt.tenant_id and operating_company_id=attempt.operating_company_id and environment=attempt.environment;
  if req.status<>'submitted' or req.bank_request_id is null or binding.id is null or cfg.tenant_id is null
    or cfg.version<>binding.configuration_version or cfg.certificate_expires_at<=now() then
    raise exception using errcode='23514',message='Cobrança ou configuração bancária deixou de ser válida.';
  end if;
  select decrypted_secret::jsonb into credentials from vault.decrypted_secrets where id=cfg.secret_id;
  if credentials is null or exists(
    select 1 from unnest(array['client_id','client_secret','certificate','private_key']) k
    where jsonb_typeof(credentials->k) is distinct from 'string' or length(btrim(credentials->>k))=0
  ) then
    raise exception using errcode='22023',message='Credenciais bancárias incompletas.';
  end if;
  return jsonb_build_object(
    'attempt_id',attempt.id,'actor_id',attempt.created_by,'environment',attempt.environment,
    'account',cfg.account,'bank_request_id',req.bank_request_id,
    'token_cache_key',cfg.tenant_id::text||':'||attempt.operating_company_id::text||':'||attempt.environment||':'||cfg.version::text||':'||cfg.certificate_fingerprint,
    'credentials',credentials
  );
end $$;


