--
-- Name: fixed_payable_occurrences; Type: TABLE; Schema: apticket; Owner: supabase_admin
--

CREATE TABLE apticket.fixed_payable_occurrences (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    operating_company_id uuid NOT NULL,
    fixed_payable_id uuid NOT NULL,
    competence date NOT NULL,
    supplier_id uuid NOT NULL,
    supplier_name text NOT NULL,
    document_type_id uuid NOT NULL,
    description text NOT NULL,
    total_amount numeric(14,2) NOT NULL,
    due_date date NOT NULL,
    category_allocations jsonb NOT NULL,
    cost_center_allocations jsonb NOT NULL,
    notes text,
    status text DEFAULT 'forecast'::text NOT NULL,
    confirmed_payable_id uuid,
    confirmed_at timestamp with time zone,
    confirmed_by uuid,
    deletion_reason text,
    revision integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_by uuid,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_by uuid,
    deleted_at timestamp with time zone,
    CONSTRAINT fixed_payable_occurrences_check CHECK ((isfinite(due_date) AND (due_date >= competence))),
    CONSTRAINT fixed_payable_occurrences_check1 CHECK ((((status = 'forecast'::text) AND (confirmed_payable_id IS NULL) AND (confirmed_at IS NULL) AND (confirmed_by IS NULL)) OR ((status = 'confirmed'::text) AND (confirmed_payable_id IS NOT NULL) AND (confirmed_at IS NOT NULL) AND (confirmed_by IS NOT NULL) AND (deleted_at IS NULL)))),
    CONSTRAINT fixed_payable_occurrences_competence_check CHECK ((isfinite(competence) AND (competence = (date_trunc('month'::text, (competence)::timestamp with time zone))::date))),
    CONSTRAINT fixed_payable_occurrences_deletion_reason_check CHECK ((deletion_reason = ANY (ARRAY['skipped'::text, 'range_changed'::text, 'template_deleted'::text]))),
    CONSTRAINT fixed_payable_occurrences_description_check CHECK (((length(btrim(description)) >= 2) AND (length(btrim(description)) <= 500))),
    CONSTRAINT fixed_payable_occurrences_notes_check CHECK ((length(notes) <= 4000)),
    CONSTRAINT fixed_payable_occurrences_status_check CHECK ((status = ANY (ARRAY['forecast'::text, 'confirmed'::text]))),
    CONSTRAINT fixed_payable_occurrences_total_amount_check CHECK (((total_amount > (0)::numeric) AND (total_amount <= 999999999.99)))
);


ALTER TABLE apticket.fixed_payable_occurrences OWNER TO supabase_admin;

--
-- Name: TABLE fixed_payable_occurrences; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON TABLE apticket.fixed_payable_occurrences IS 'Previsão é um estado próprio, anterior ao título. Não participa de caixa, DRE, orçamento realizado, conciliação, alçada ou pagamento até confirmar.';


--
-- Name: lock_fixed_occurrence(uuid, integer); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.lock_fixed_occurrence(p_id uuid, p_revision integer) RETURNS apticket.fixed_payable_occurrences
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare o apticket.fixed_payable_occurrences; t apticket.fixed_payables; begin
  select * into o from apticket.fixed_payable_occurrences where id=p_id and tenant_id=apticket.current_tenant_id() and deleted_at is null;
  if not found then raise exception using errcode='P0002',message='Previsão não encontrada.'; end if;
  perform apticket_finance_private.require_fixed_access(o.tenant_id,o.operating_company_id);
  select * into t from apticket.fixed_payables where id=o.fixed_payable_id for update;
  if t.deleted_at is not null then raise exception using errcode='P0001',message='A conta fixa foi excluída.'; end if;
  select * into o from apticket.fixed_payable_occurrences where id=p_id for update;
  if o.status<>'forecast' or o.deleted_at is not null then raise exception using errcode='P0001',message='Esta previsão já foi confirmada ou excluída.'; end if;
  if p_revision is null or o.revision<>p_revision then raise exception using errcode='40001',message='Esta previsão foi alterada. Reabra a confirmação.'; end if;
  return o;
end $$;


ALTER FUNCTION apticket_finance_private.lock_fixed_occurrence(p_id uuid, p_revision integer) OWNER TO supabase_admin;

--
-- Name: maintain_fixed_payable_forecasts(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.maintain_fixed_payable_forecasts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ declare t record; v_count integer:=0; begin
  -- Não fornece um endpoint multi-tenant: EXECUTE é revogado a todos os clientes.
  for t in select id from apticket.fixed_payables where is_active and deleted_at is null order by id loop
    v_count:=v_count+apticket_finance_private.generate_fixed_forecasts(t.id);
  end loop; return v_count;
end $$;


ALTER FUNCTION apticket_finance_private.maintain_fixed_payable_forecasts() OWNER TO supabase_admin;

--
-- Name: mark_inter_webhook_events_queued(uuid[]); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.mark_inter_webhook_events_queued(p_events uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if p_events is null or cardinality(p_events) not between 1 and 50 then
    raise exception using errcode='22023',message='Eventos invalidos.';
  end if;
  update apticket.inter_charge_webhook_events set status='queued',error_code=null,error_message=null
    where id=any(p_events) and status in ('received','failed');
end $$;


ALTER FUNCTION apticket_finance_private.mark_inter_webhook_events_queued(p_events uuid[]) OWNER TO postgres;

--
-- Name: next_supplier_contract_number(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.next_supplier_contract_number(p_tenant_id uuid) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_year integer := extract(year from current_date)::integer;
  v_next integer;
begin
  if p_tenant_id is null then
    raise exception using errcode='22023', message='Tenant obrigatoria para numerar o contrato.';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_tenant_id::text || ':supplier-contract:' || v_year, 0));
  select coalesce(max(split_part(numero_contrato,'/',1)::integer),0)+1
    into v_next
  from apticket.supplier_contracts
  where tenant_id=p_tenant_id and split_part(numero_contrato,'/',2)=v_year::text;
  return lpad(v_next::text,6,'0') || '/' || v_year::text;
end
$$;


ALTER FUNCTION apticket_finance_private.next_supplier_contract_number(p_tenant_id uuid) OWNER TO supabase_admin;

--
-- Name: normalize_contract_allocation(jsonb, text, uuid, uuid, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.normalize_contract_allocation(p_items jsonb, p_dimension text, p_tenant uuid, p_company uuid, p_direction text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare item jsonb; result jsonb:='[]'; total numeric:=0; pct numeric; item_id uuid;
  item_code text; item_name text; seen uuid[]:='{}'; label text;
begin
  label:=case p_dimension when 'category' then 'categorias financeiras' else 'centros de custo' end;
  if p_items is null or jsonb_typeof(p_items)<>'array' then
    raise exception using errcode='23514',message='Informe ao menos um item no rateio de '||label||'.';
  end if;
  if jsonb_array_length(p_items)=0 then
    raise exception using errcode='23514',message='Informe ao menos um item no rateio de '||label||'.';
  end if;
  for item in select value from jsonb_array_elements(p_items) order by value->>'item_id' loop
    if jsonb_typeof(item)<>'object' or coalesce(item->>'percentage','') !~ '^[0-9]+(\.[0-9]{1,2})?$'
      or coalesce(item->>'item_id','') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
      raise exception using errcode='23514',message='Selecione um item e informe um percentual com no máximo 2 casas decimais.';
    end if;
    pct:=(item->>'percentage')::numeric; item_id:=(item->>'item_id')::uuid;
    if pct<=0 or pct>100 then
      raise exception using errcode='23514',message='O percentual deve ser maior que 0 e menor ou igual a 100.';
    end if;
    if item_id=any(seen) then
      raise exception using errcode='23514',message='Não repita o mesmo item no rateio de '||label||'.';
    end if;
    seen:=array_append(seen,item_id);
    if p_dimension='category' then
      select code,name into item_code,item_name from apticket.financial_categories
      where id=item_id and tenant_id=p_tenant and (operating_company_id=p_company or is_global)
        and is_active and deleted_at is null and classification_type='analytic'
        and direction in (p_direction,'both') for share;
    else
      select code,name into item_code,item_name from apticket.financial_cost_centers
      where id=item_id and tenant_id=p_tenant and (operating_company_id=p_company or is_global)
        and is_active and deleted_at is null and classification_type='analytic' for share;
    end if;
    if not found then
      raise exception using errcode='23514',message='Selecione um item analítico ativo e compatível com a empresa no rateio de '||label||'.';
    end if;
    total:=total+pct;
    result:=result||jsonb_build_array(jsonb_build_object('item_id',item_id,'percentage',pct,'code',item_code,'name',item_name));
  end loop;
  if total<>100 then
    raise exception using errcode='23514',message='A soma dos percentuais de '||label||' deve ser 100% (atual: '||total||'%).';
  end if;
  return result;
end $_$;


ALTER FUNCTION apticket_finance_private.normalize_contract_allocation(p_items jsonb, p_dimension text, p_tenant uuid, p_company uuid, p_direction text) OWNER TO supabase_admin;

--
-- Name: normalize_fixed_payload(uuid, uuid, jsonb); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.normalize_fixed_payload(p_tenant uuid, p_company uuid, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_supplier apticket.suppliers; v_type uuid:=(p_payload->>'document_type_id')::uuid;
  v_amount numeric:=(p_payload->>'total_amount')::numeric; v_categories jsonb; v_centers jsonb;
begin
  if jsonb_typeof(p_payload) is distinct from 'object' or length(btrim(coalesce(p_payload->>'description',''))) not between 2 and 500
    or v_amount is null or v_amount::text in ('NaN','Infinity','-Infinity') or v_amount<=0 or v_amount>999999999.99 or v_amount<>round(v_amount,2)
    or length(coalesce(p_payload->>'notes',''))>4000 then
    raise exception using errcode='22023',message='Revise fornecedor, descrição, valor e observações.';
  end if;
  perform 1 from apticket.operating_companies where id=p_company and tenant_id=p_tenant and is_active and deleted_at is null for share;
  if not found then raise exception using errcode='23514',message='Empresa operadora inativa ou indisponível.'; end if;
  select * into v_supplier from apticket.suppliers where id=(p_payload->>'supplier_id')::uuid and tenant_id=p_tenant and is_active and deleted_at is null for share;
  if not found then raise exception using errcode='23514',message='Selecione um fornecedor ativo desta organização.'; end if;
  perform 1 from apticket.financial_document_types where id=v_type and tenant_id=p_tenant and is_active and deleted_at is null and availability in ('payable','both') for share;
  if not found then raise exception using errcode='23514',message='Selecione um tipo de documento ativo para contas a pagar.'; end if;
  v_categories:=apticket_finance_private.normalize_contract_allocation(p_payload->'category_allocations','category',p_tenant,p_company,'outflow');
  v_centers:=apticket_finance_private.normalize_contract_allocation(p_payload->'cost_center_allocations','cost_center',p_tenant,p_company,'outflow');
  return p_payload||jsonb_build_object('supplier_name',coalesce(v_supplier.trade_name,v_supplier.legal_name),
    'category_allocations',v_categories,'cost_center_allocations',v_centers,'description',btrim(p_payload->>'description'),'notes',nullif(btrim(p_payload->>'notes'),''));
end $$;


ALTER FUNCTION apticket_finance_private.normalize_fixed_payload(p_tenant uuid, p_company uuid, p_payload jsonb) OWNER TO supabase_admin;

--
-- Name: normalize_inter_phone(text); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.normalize_inter_phone(value text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
declare
  raw_value text := btrim(coalesce(value, ''));
  digits text := regexp_replace(coalesce(value, ''), '[^0-9]', '', 'g');
begin
  -- Um prefixo internacional explícito nunca pode ser interpretado como DDD.
  if left(raw_value, 1) = '+' and left(digits, 2) <> '55' then
    return array[null::text, null::text];
  end if;

  if length(digits) in (12, 13) and left(digits, 2) = '55' then
    digits := substring(digits from 3);
  end if;

  if length(digits) in (10, 11) then
    return array[left(digits, 2), substring(digits from 3)];
  end if;

  return array[null::text, null::text];
end
$$;


ALTER FUNCTION apticket_finance_private.normalize_inter_phone(value text) OWNER TO postgres;

