--
-- Name: prepare_contract_allocations(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_contract_allocations() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op='UPDATE' then
    -- Suspension/cancellation and archiving must keep working on historical
    -- contracts, including ones whose dimensions were subsequently archived.
    if (new.status is distinct from old.status or new.deleted_at is distinct from old.deleted_at)
      and (to_jsonb(new)-array['status','is_active','deleted_at','updated_at','updated_by'])
        is not distinct from (to_jsonb(old)-array['status','is_active','deleted_at','updated_at','updated_by']) then
      return new;
    end if;
    if auth.uid() is null and old.category_allocations is null and old.cost_center_allocations is null
      and new.category_allocations is null and new.cost_center_allocations is null
      and new.financial_category_id is null and new.cost_center_id is null then
      return new;
    end if;
  end if;
  -- Old API: changed scalar fields replace just the corresponding allocation with 100%.
  if tg_op='INSERT' then
    if new.category_allocations is null and new.financial_category_id is not null then
      new.category_allocations:=jsonb_build_array(jsonb_build_object('item_id',new.financial_category_id,'percentage',100));
    end if;
    if new.cost_center_allocations is null and new.cost_center_id is not null then
      new.cost_center_allocations:=jsonb_build_array(jsonb_build_object('item_id',new.cost_center_id,'percentage',100));
    end if;
  else
    if new.category_allocations is not distinct from old.category_allocations
      and new.financial_category_id is distinct from old.financial_category_id then
      new.category_allocations:=case when new.financial_category_id is null then '[]'::jsonb else
        jsonb_build_array(jsonb_build_object('item_id',new.financial_category_id,'percentage',100)) end;
    end if;
    if new.cost_center_allocations is not distinct from old.cost_center_allocations
      and new.cost_center_id is distinct from old.cost_center_id then
      new.cost_center_allocations:=case when new.cost_center_id is null then '[]'::jsonb else
        jsonb_build_array(jsonb_build_object('item_id',new.cost_center_id,'percentage',100)) end;
    end if;
  end if;
  new.category_allocations:=apticket_finance_private.normalize_contract_allocation(new.category_allocations,'category',new.tenant_id,new.operating_company_id,tg_argv[0]);
  new.cost_center_allocations:=apticket_finance_private.normalize_contract_allocation(new.cost_center_allocations,'cost_center',new.tenant_id,new.operating_company_id,tg_argv[0]);
  select (value->>'item_id')::uuid into new.financial_category_id from jsonb_array_elements(new.category_allocations)
    order by (value->>'percentage')::numeric desc,value->>'item_id' limit 1;
  select (value->>'item_id')::uuid into new.cost_center_id from jsonb_array_elements(new.cost_center_allocations)
    order by (value->>'percentage')::numeric desc,value->>'item_id' limit 1;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.prepare_contract_allocations() OWNER TO supabase_admin;

--
-- Name: prepare_inter_charge(uuid, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.prepare_inter_charge(p_receivable uuid, p_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  r apticket.contas_receber;
  existing apticket.inter_charge_requests;
  actor uuid := auth.uid();
  source_is_valid boolean;
begin
  if not apticket.has_permission(actor, 'financeiro_contas_receber', 'edit') then
    raise exception using errcode = '42501', message = 'Sem permissão para esta operação financeira.';
  end if;
  if actor is null then
    raise exception using errcode = '42501', message = 'Sessão obrigatória.';
  end if;
  if p_environment is null or p_environment not in ('sandbox', 'production') then
    raise exception using errcode = '22023', message = 'Ambiente inválido.';
  end if;

  select * into r
  from apticket.contas_receber
  where id = p_receivable and tenant_id = apticket.current_tenant_id()
  for update;

  if not found then
    raise exception using errcode = '42501', message = 'Recebível indisponível.';
  end if;
  if not apticket.has_financial_scope(r.tenant_id, r.operating_company_id, true) then
    raise exception using errcode = '42501', message = 'Sem acesso financeiro à empresa operadora.';
  end if;

  source_is_valid := (
    r.origin_type = 'recurring'
    and exists (
      select 1 from apticket.billing_cycles cycle
      where cycle.id = r.billing_cycle_id and cycle.contract_id = r.contrato_id
        and cycle.tenant_id = r.tenant_id
        and cycle.operating_company_id = r.operating_company_id
        and cycle.deleted_at is null
    )
  ) or (
    r.origin_type = 'measurement'
    and exists (
      select 1 from apticket.medicoes_contrato measurement
      where measurement.id = r.medicao_id and measurement.contrato_id = r.contrato_id
        and measurement.tenant_id = r.tenant_id and measurement.status = 'aprovada'
        and measurement.deleted_at is null
    )
  ) or r.origin_type = 'manual';

  if r.deleted_at is not null or r.status_cobranca <> 'a_faturar'
    or r.valor_aberto <= 0 or r.valor_aberto <> r.valor_original
    or not source_is_valid
    or not exists (
      select 1 from apticket.operating_companies operator
      where operator.id = r.operating_company_id and operator.tenant_id = r.tenant_id
        and operator.deleted_at is null and operator.is_active
    ) then
    raise exception using errcode = '23514', message = 'Recebível não elegível para preparação.';
  end if;

  select * into existing
  from apticket.inter_charge_requests
  where receivable_id = r.id and environment = p_environment;

  if found then
    if existing.deleted_at is not null or existing.amount <> r.valor_aberto
      or existing.due_date <> r.vencimento_em then
      raise exception using errcode = '40001',
        message = 'Recebível alterado após a preparação. Solicite revisão antes da emissão.';
    end if;
    return jsonb_build_object('id', existing.id, 'status', existing.status, 'reused', true);
  end if;

  insert into apticket.inter_charge_requests(
    tenant_id, operating_company_id, receivable_id, environment,
    amount, due_date, created_by
  ) values (
    r.tenant_id, r.operating_company_id, r.id, p_environment,
    r.valor_aberto, r.vencimento_em, actor
  ) returning * into existing;

  return jsonb_build_object('id', existing.id, 'status', existing.status, 'reused', false);
end
$$;


ALTER FUNCTION apticket_finance_private.prepare_inter_charge(p_receivable uuid, p_environment text) OWNER TO postgres;

--
-- Name: prepare_inter_charge_dispatch(uuid, boolean, boolean); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_inter_charge_dispatch(p_request uuid, p_confirmed boolean, p_production_confirmed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  req apticket.inter_charge_requests;
  snap apticket.inter_payer_snapshots;
  attempt apticket.inter_charge_dispatch_attempts;
  actor uuid:=auth.uid();
  payer_review jsonb;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if actor is null then
    raise exception using errcode='42501',message='Sessão obrigatória.';
  end if;
  if p_confirmed is distinct from true then
    raise exception using errcode='22023',message='Confirmação explícita obrigatória.';
  end if;
  select * into req from apticket.inter_charge_requests
    where id=p_request and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found or not apticket.has_financial_scope(req.tenant_id,req.operating_company_id,true)
    or not exists(
      select 1 from apticket.user_roles ur join apticket.roles r
        on r.id=ur.role_id and r.tenant_id=ur.tenant_id
      where ur.user_id=actor and ur.tenant_id=req.tenant_id and r.name in ('Admin','Financeiro')
    ) then
    raise exception using errcode='42501',message='Exige perfil Admin ou Financeiro e acesso financeiro de escrita.';
  end if;
  if req.environment='production' and p_production_confirmed is distinct from true then
    raise exception using errcode='22023',message='Confirmação específica do ambiente oficial obrigatória.';
  end if;
  if req.environment='production' and not exists(
    select 1 from apticket.tenant_inter_configurations cfg
    where cfg.tenant_id=req.tenant_id and cfg.operating_company_id=req.operating_company_id and cfg.environment='production'
      and cfg.is_active and cfg.webhook_status='active'
      and cfg.webhook_secret_id is not null and cfg.certificate_expires_at>now()
  ) then
    raise exception using errcode='P0001',
      message='Ative a configuração oficial e registre o webhook antes da primeira emissão.';
  end if;
  if req.status='submitted' then
    return jsonb_build_object('state','submitted','request_id',req.id,'bank_request_id',req.bank_request_id,'reused',true);
  end if;
  if req.status='uncertain' then
    return jsonb_build_object('state','uncertain','request_id',req.id,'bank_request_id',req.bank_request_id,'reused',true);
  end if;
  if req.status='dispatching' then
    select * into attempt from apticket.inter_charge_dispatch_attempts
      where request_id=req.id and status='claimed' order by attempt_number desc limit 1;
    if found and attempt.started_at>clock_timestamp()-interval '2 minutes' then
      return jsonb_build_object('state','dispatching','request_id',req.id,'attempt_id',attempt.id,
        'actor_id',attempt.created_by,'reused',true);
    end if;
    if found then
      update apticket.inter_charge_dispatch_attempts set status='uncertain',finished_at=clock_timestamp(),
        error_code='LEASE_EXPIRED',error_message='A execução perdeu a confirmação do resultado bancário.' where id=attempt.id;
    end if;
    update apticket.inter_charge_requests set status='uncertain',updated_at=now(),
      last_error_code='LEASE_EXPIRED',last_error_message='Resultado bancário incerto; o POST não será repetido.' where id=req.id;
    return jsonb_build_object('state','uncertain','request_id',req.id,'reused',true);
  end if;
  if req.dispatch_attempts>=5 then
    raise exception using errcode='54000',message='Limite de tentativas atingido.';
  end if;
  if exists(select 1 from apticket.inter_charge_dispatch_attempts where request_id=req.id
    and started_at>clock_timestamp()-interval '1 minute') then
    raise exception using errcode='54000',message='Aguarde antes de tentar novamente.';
  end if;
  payer_review:=apticket_finance_private.review_inter_payer(req.id);
  if payer_review->>'state'<>'confirmed' then
    raise exception using errcode='23514',message='O pagador ou vínculo precisa ser confirmado novamente.';
  end if;
  select * into snap from apticket.inter_payer_snapshots
    where request_id=req.id and deleted_at is null for update;
  if not found then
    raise exception using errcode='23514',message='Snapshot do pagador indisponível.';
  end if;
  insert into apticket.inter_charge_dispatch_attempts(
    tenant_id,operating_company_id,request_id,snapshot_id,binding_id,environment,
    attempt_number,created_by,production_confirmed_at
  ) values(
    req.tenant_id,req.operating_company_id,req.id,snap.id,snap.binding_id,req.environment,
    req.dispatch_attempts+1,actor,
    case when req.environment='production' then clock_timestamp() end
  ) returning * into attempt;
  update apticket.inter_charge_requests set status='dispatching',dispatch_attempts=dispatch_attempts+1,
    dispatch_started_at=attempt.started_at,updated_at=now(),last_error_code=null,last_error_message=null where id=req.id;
  return jsonb_build_object('state','dispatching','request_id',req.id,'attempt_id',attempt.id,
    'actor_id',actor,'environment',req.environment,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.prepare_inter_charge_dispatch(p_request uuid, p_confirmed boolean, p_production_confirmed boolean) OWNER TO supabase_admin;

--
-- Name: prepare_inter_charge_sync(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.prepare_inter_charge_sync(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  req apticket.inter_charge_requests;
  attempt apticket.inter_charge_sync_attempts;
  actor uuid:=auth.uid();
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if actor is null then
    raise exception using errcode='42501',message='Sessão obrigatória.';
  end if;
  select * into req from apticket.inter_charge_requests
    where id=p_request and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found or not apticket.has_financial_scope(req.tenant_id,req.operating_company_id,true)
    or not exists(
      select 1 from apticket.user_roles ur join apticket.roles r
        on r.id=ur.role_id and r.tenant_id=ur.tenant_id
      where ur.user_id=actor and ur.tenant_id=req.tenant_id and r.name in ('Admin','Financeiro')
    ) then
    raise exception using errcode='42501',message='Exige perfil Admin ou Financeiro e acesso financeiro de escrita.';
  end if;
  if req.environment<>'sandbox' or req.status<>'submitted' or req.bank_request_id is null then
    raise exception using errcode='22023',message='Somente uma cobrança aceita no sandbox pode ser consultada.';
  end if;
  select * into attempt from apticket.inter_charge_sync_attempts
    where request_id=req.id and status='claimed' order by started_at desc limit 1;
  if found and attempt.started_at>clock_timestamp()-interval '2 minutes' then
    return jsonb_build_object('state','syncing','attempt_id',attempt.id,'actor_id',attempt.created_by,'reused',true);
  end if;
  if found then
    update apticket.inter_charge_sync_attempts set status='failed',finished_at=clock_timestamp(),
      error_code='LEASE_EXPIRED',error_message='A consulta bancária anterior não foi concluída.' where id=attempt.id;
  end if;
  if req.bank_synced_at is not null and req.bank_synced_at>clock_timestamp()-interval '15 seconds' then
    return jsonb_build_object('state','synced','request_id',req.id,'bank_status',req.bank_status,'reused',true);
  end if;
  insert into apticket.inter_charge_sync_attempts(
    tenant_id,operating_company_id,request_id,environment,created_by
  ) values(req.tenant_id,req.operating_company_id,req.id,'sandbox',actor)
  returning * into attempt;
  return jsonb_build_object('state','syncing','attempt_id',attempt.id,'actor_id',actor,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.prepare_inter_charge_sync(p_request uuid) OWNER TO postgres;

--
-- Name: prepare_inter_charge_sync_from_webhook(uuid, uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.prepare_inter_charge_sync_from_webhook(p_request uuid, p_event uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  req apticket.inter_charge_requests;
  event apticket.inter_charge_webhook_events;
  attempt apticket.inter_charge_sync_attempts;
  cfg apticket.tenant_inter_configurations;
  actor uuid;
begin
  select * into event from apticket.inter_charge_webhook_events
    where id=p_event and request_id=p_request for update;
  if not found then raise exception using errcode='42501',message='Evento de webhook indisponivel.'; end if;
  if event.status='verified' then
    return jsonb_build_object('state','synced','request_id',p_request,'reused',true);
  end if;
  if event.attempt_count>=20 then
    raise exception using errcode='54000',message='Limite de reconciliacoes do evento atingido.';
  end if;
  select * into req from apticket.inter_charge_requests
    where id=p_request and tenant_id=event.tenant_id and environment=event.environment
      and bank_request_id=event.bank_request_id and status='submitted' and deleted_at is null for update;
  if not found then raise exception using errcode='22023',message='Cobranca do webhook indisponivel.'; end if;
  select * into cfg from apticket.tenant_inter_configurations
    where tenant_id=req.tenant_id and operating_company_id=req.operating_company_id and environment=req.environment;
  if not found or cfg.webhook_status<>'active' then
    raise exception using errcode='22023',message='Webhook deixou de estar ativo.';
  end if;
  actor:=cfg.updated_by;
  select * into attempt from apticket.inter_charge_sync_attempts
    where request_id=req.id and status='claimed' order by started_at desc limit 1;
  if found and attempt.started_at>clock_timestamp()-interval '2 minutes' then
    return jsonb_build_object('state','syncing','attempt_id',attempt.id,'actor_id',attempt.created_by,'reused',true);
  end if;
  if found then
    update apticket.inter_charge_sync_attempts set status='failed',finished_at=clock_timestamp(),
      error_code='LEASE_EXPIRED',error_message='A consulta bancaria anterior nao foi concluida.' where id=attempt.id;
  end if;
  if req.bank_synced_at is not null and req.bank_synced_at>clock_timestamp()-interval '15 seconds' then
    update apticket.inter_charge_webhook_events set status='verified',processed_at=clock_timestamp(),
      error_code=null,error_message=null where id=event.id;
    return jsonb_build_object('state','synced','request_id',req.id,'bank_status',req.bank_status,'reused',true);
  end if;
  insert into apticket.inter_charge_sync_attempts(
    tenant_id,operating_company_id,request_id,environment,created_by,initiation_source,source_event_id
  ) values(req.tenant_id,req.operating_company_id,req.id,req.environment,actor,'webhook',event.id)
  returning * into attempt;
  update apticket.inter_charge_webhook_events set status='verifying',attempt_count=attempt_count+1,
    error_code=null,error_message=null,processed_at=null where id=event.id;
  return jsonb_build_object('state','syncing','attempt_id',attempt.id,'actor_id',actor,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.prepare_inter_charge_sync_from_webhook(p_request uuid, p_event uuid) OWNER TO postgres;

--
-- Name: prepare_inter_sandbox_dispatch(uuid, boolean); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.prepare_inter_sandbox_dispatch(p_request uuid, p_confirmed boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  req apticket.inter_charge_requests;
  snap apticket.inter_payer_snapshots;
  attempt apticket.inter_charge_dispatch_attempts;
  actor uuid:=auth.uid();
  payer_review jsonb;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if actor is null then
    raise exception using errcode='42501',message='Sessão obrigatória.';
  end if;
  if p_confirmed is distinct from true then
    raise exception using errcode='22023',message='Confirmação explícita obrigatória.';
  end if;
  select * into req from apticket.inter_charge_requests
    where id=p_request and tenant_id=apticket.current_tenant_id() and deleted_at is null for update;
  if not found or not apticket.has_financial_scope(req.tenant_id,req.operating_company_id,true)
    or not exists(
      select 1 from apticket.user_roles ur join apticket.roles r
        on r.id=ur.role_id and r.tenant_id=ur.tenant_id
      where ur.user_id=actor and ur.tenant_id=req.tenant_id and r.name in ('Admin','Financeiro')
    ) then
    raise exception using errcode='42501',message='Exige perfil Admin ou Financeiro e acesso financeiro de escrita.';
  end if;
  if req.environment<>'sandbox' then
    raise exception using errcode='0A000',message='Emissão em produção permanece bloqueada.';
  end if;
  if req.status='submitted' then
    return jsonb_build_object('state','submitted','request_id',req.id,'bank_request_id',req.bank_request_id,'reused',true);
  end if;
  if req.status='uncertain' then
    return jsonb_build_object('state','uncertain','request_id',req.id,'bank_request_id',req.bank_request_id,'reused',true);
  end if;
  if req.status='dispatching' then
    select * into attempt from apticket.inter_charge_dispatch_attempts
      where request_id=req.id and status='claimed' order by attempt_number desc limit 1;
    if found and attempt.started_at>clock_timestamp()-interval '2 minutes' then
      return jsonb_build_object('state','dispatching','request_id',req.id,'attempt_id',attempt.id,
        'actor_id',attempt.created_by,'reused',true);
    end if;
    if found then
      update apticket.inter_charge_dispatch_attempts set status='uncertain',finished_at=clock_timestamp(),
        error_code='LEASE_EXPIRED',error_message='A execução perdeu a confirmação do resultado bancário.' where id=attempt.id;
    end if;
    update apticket.inter_charge_requests set status='uncertain',updated_at=now(),
      last_error_code='LEASE_EXPIRED',last_error_message='Resultado bancário incerto; o POST não será repetido.' where id=req.id;
    return jsonb_build_object('state','uncertain','request_id',req.id,'reused',true);
  end if;
  if req.dispatch_attempts>=5 then
    raise exception using errcode='54000',message='Limite de tentativas atingido.';
  end if;
  if exists(select 1 from apticket.inter_charge_dispatch_attempts where request_id=req.id
    and started_at>clock_timestamp()-interval '1 minute') then
    raise exception using errcode='54000',message='Aguarde antes de tentar novamente.';
  end if;
  payer_review:=apticket_finance_private.review_inter_payer(req.id);
  if payer_review->>'state'<>'confirmed' then
    raise exception using errcode='23514',message='O pagador ou vínculo precisa ser confirmado novamente.';
  end if;
  select * into snap from apticket.inter_payer_snapshots
    where request_id=req.id and deleted_at is null for update;
  if not found then
    raise exception using errcode='23514',message='Snapshot do pagador indisponível.';
  end if;
  insert into apticket.inter_charge_dispatch_attempts(
    tenant_id,operating_company_id,request_id,snapshot_id,binding_id,environment,attempt_number,created_by
  ) values(req.tenant_id,req.operating_company_id,req.id,snap.id,snap.binding_id,'sandbox',req.dispatch_attempts+1,actor)
  returning * into attempt;
  update apticket.inter_charge_requests set status='dispatching',dispatch_attempts=dispatch_attempts+1,
    dispatch_started_at=attempt.started_at,updated_at=now(),last_error_code=null,last_error_message=null where id=req.id;
  return jsonb_build_object('state','dispatching','request_id',req.id,'attempt_id',attempt.id,
    'actor_id',actor,'reused',false);
end $$;


ALTER FUNCTION apticket_finance_private.prepare_inter_sandbox_dispatch(p_request uuid, p_confirmed boolean) OWNER TO postgres;

--
-- Name: prepare_inter_webhook_registration(uuid, uuid, uuid, text, integer, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_inter_webhook_registration(p_actor uuid, p_tenant uuid, p_company uuid, p_environment text, p_version integer, p_callback_base_url text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare cfg apticket.tenant_inter_configurations; attempt apticket.inter_webhook_registration_attempts;
  credentials jsonb; candidate_token text; candidate_hash text;
begin
  if not exists(select 1 from apticket.profiles where id=p_actor and tenant_id=p_tenant and is_active)
    or not apticket_finance_private.actor_has_permission(p_actor,p_tenant,'empresa_operadora','edit') or not apticket_finance_private.actor_has_permission(p_actor,p_tenant,'financeiro_bancos','edit')
    or not exists(select 1 from apticket.user_roles ur join apticket.roles r on r.id=ur.role_id and r.tenant_id=ur.tenant_id
      where ur.user_id=p_actor and ur.tenant_id=p_tenant and r.name in ('Admin','Financeiro')) then
    raise exception using errcode='42501',message='Exige perfil Admin ou Financeiro.';
  end if;
  if p_environment not in ('sandbox','production') or p_version<1 or p_callback_base_url is null
    or length(p_callback_base_url)>500 or p_callback_base_url !~ '^https://[^?#]+$' then
    raise exception using errcode='22023',message='Ambiente ou URL publica invalida.';
  end if;
  select * into cfg from apticket.tenant_inter_configurations where tenant_id=p_tenant
    and operating_company_id=p_company and environment=p_environment for update;
  if not found then raise exception using errcode='P0002',message='Configuracao bancaria nao encontrada.'; end if;
  if cfg.version<>p_version then raise exception using errcode='40001',message='Configuracao alterada.'; end if;
  if cfg.certificate_expires_at<=now() then raise exception using errcode='22023',message='Certificado vencido.'; end if;
  select * into attempt from apticket.inter_webhook_registration_attempts where tenant_id=p_tenant
    and operating_company_id=p_company and environment=p_environment and status='claimed'
    order by started_at desc limit 1;
  if found and attempt.started_at>clock_timestamp()-interval '2 minutes' then
    raise exception using errcode='54000',message='Ja existe uma configuracao em andamento.';
  end if;
  if found then update apticket.inter_webhook_registration_attempts set status='failed',finished_at=clock_timestamp(),
    error_code='LEASE_EXPIRED',error_message='A configuracao anterior nao foi concluida.' where id=attempt.id; end if;
  select decrypted_secret::jsonb into credentials from vault.decrypted_secrets where id=cfg.secret_id;
  if credentials is null or exists(select 1 from unnest(array['client_id','client_secret','certificate','private_key']) k
    where jsonb_typeof(credentials->k) is distinct from 'string' or length(btrim(credentials->>k))=0) then
    raise exception using errcode='22023',message='Credenciais bancarias incompletas.';
  end if;
  candidate_token:=encode(extensions.gen_random_bytes(32),'hex');
  candidate_hash:=encode(extensions.digest(candidate_token,'sha256'),'hex');
  insert into apticket.inter_webhook_registration_attempts(
    tenant_id,operating_company_id,environment,configuration_version,callback_base_url,candidate_secret_hash,created_by
  ) values(p_tenant,p_company,p_environment,p_version,p_callback_base_url,candidate_hash,p_actor) returning * into attempt;
  update apticket.tenant_inter_configurations set webhook_status='configuring',webhook_updated_at=clock_timestamp(),
    webhook_last_error_code=null,webhook_last_error_message=null where tenant_id=p_tenant
      and operating_company_id=p_company and environment=p_environment;
  return jsonb_build_object('attempt_id',attempt.id,'environment',p_environment,'account',cfg.account,
    'callback_url',p_callback_base_url||'?token='||candidate_token,'candidate_token',candidate_token,
    'token_cache_key',p_tenant||':'||p_company||':'||p_environment||':'||cfg.version||':'||cfg.certificate_fingerprint,
    'credentials',credentials);
end $_$;


ALTER FUNCTION apticket_finance_private.prepare_inter_webhook_registration(p_actor uuid, p_tenant uuid, p_company uuid, p_environment text, p_version integer, p_callback_base_url text) OWNER TO supabase_admin;

--
-- Name: prepare_operating_company(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_operating_company() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_op='INSERT' then
    new.created_by:=auth.uid();
    new.created_at:=clock_timestamp();
  elsif new.id is distinct from old.id or new.tenant_id is distinct from old.tenant_id
    or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception using errcode='23514',message='A identidade da empresa operadora nao pode ser alterada.';
  end if;
  if tg_op='UPDATE' and old.deleted_at is null and new.deleted_at is not null then
    new.is_active:=false;
  elsif tg_op='UPDATE' and old.deleted_at is not null then
    raise exception using errcode='23514',message='Uma empresa operadora arquivada nao pode ser alterada.';
  end if;
  new.legal_name:=btrim(new.legal_name);
  new.trade_name:=nullif(btrim(new.trade_name),'');
  new.tax_id:=nullif(regexp_replace(coalesce(new.tax_id,''),'[^0-9]','','g'),'');
  new.state_registration:=nullif(btrim(new.state_registration),'');
  new.municipal_registration:=nullif(btrim(new.municipal_registration),'');
  new.email:=nullif(lower(btrim(new.email)),'');
  new.phone:=nullif(btrim(new.phone),'');
  new.website:=nullif(btrim(new.website),'');
  new.zip_code:=nullif(regexp_replace(coalesce(new.zip_code,''),'[^0-9]','','g'),'');
  new.address_street:=nullif(btrim(new.address_street),'');
  new.address_number:=nullif(btrim(new.address_number),'');
  new.address_complement:=nullif(btrim(new.address_complement),'');
  new.address_district:=nullif(btrim(new.address_district),'');
  new.address_city:=nullif(btrim(new.address_city),'');
  new.address_state:=nullif(upper(btrim(new.address_state)),'');
  new.address_country:=coalesce(nullif(upper(btrim(new.address_country)),''),'BR');
  new.cnaes:=coalesce(new.cnaes,'[]'::jsonb);
  new.updated_by:=auth.uid();
  new.updated_at:=clock_timestamp();
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.prepare_operating_company() OWNER TO supabase_admin;

--
-- Name: supplier_payables; Type: TABLE; Schema: apticket; Owner: supabase_admin
--

CREATE TABLE apticket.supplier_payables (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    operating_company_id uuid NOT NULL,
    supplier_id uuid NOT NULL,
    supplier_contract_id uuid,
    document_number text NOT NULL,
    description text NOT NULL,
    cycle_start date NOT NULL,
    cycle_end date NOT NULL,
    due_date date NOT NULL,
    billing_unit text NOT NULL,
    measured_quantity numeric(18,6) DEFAULT 0 NOT NULL,
    unit_price numeric(18,6) DEFAULT 0 NOT NULL,
    total_amount numeric(14,2) NOT NULL,
    allocation_status text NOT NULL,
    status text DEFAULT 'scheduled'::text NOT NULL,
    terms_snapshot jsonb NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    deleted_at timestamp with time zone,
    origin_type text GENERATED ALWAYS AS (
CASE
    WHEN (supplier_contract_id IS NULL) THEN 'manual'::text
    ELSE 'contract'::text
END) STORED NOT NULL,
    document_type_id uuid,
    manual_entry_group_id uuid,
    installment_number smallint,
    installment_count smallint,
    document_base_number text,
    revision integer DEFAULT 0 NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp(),
    updated_by uuid,
    last_change_reason text,
    CONSTRAINT supplier_payable_installment_metadata_check CHECK ((((manual_entry_group_id IS NULL) AND (installment_number IS NULL) AND (installment_count IS NULL) AND (document_base_number IS NULL)) OR ((manual_entry_group_id IS NOT NULL) AND ((installment_number >= 1) AND (installment_number <= installment_count)) AND ((installment_count >= 1) AND (installment_count <= 120)) AND ((length(btrim(document_base_number)) >= 2) AND (length(btrim(document_base_number)) <= 80)) AND (origin_type = 'manual'::text)))),
    CONSTRAINT supplier_payables_allocation_status_check CHECK ((allocation_status = ANY (ARRAY['pending_rule'::text, 'complete'::text]))),
    CONSTRAINT supplier_payables_billing_unit_check CHECK ((billing_unit = ANY (ARRAY['fixed'::text, 'active_users'::text, 'devices'::text]))),
    CONSTRAINT supplier_payables_check CHECK ((cycle_end > cycle_start)),
    CONSTRAINT supplier_payables_description_check CHECK (((length(btrim(description)) >= 2) AND (length(btrim(description)) <= 500))),
    CONSTRAINT supplier_payables_document_number_check CHECK (((length(btrim(document_number)) >= 5) AND (length(btrim(document_number)) <= 80))),
    CONSTRAINT supplier_payables_last_change_reason_check CHECK (((last_change_reason IS NULL) OR ((length(btrim(last_change_reason)) >= 3) AND (length(btrim(last_change_reason)) <= 1000)))),
    CONSTRAINT supplier_payables_measured_quantity_check CHECK ((measured_quantity >= (0)::numeric)),
    CONSTRAINT supplier_payables_origin_type_check CHECK ((origin_type = ANY (ARRAY['contract'::text, 'manual'::text, 'employee'::text]))),
    CONSTRAINT supplier_payables_revision_check CHECK ((revision >= 0)),
    CONSTRAINT supplier_payables_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'awaiting_approval'::text, 'approved'::text, 'paid'::text, 'overdue'::text, 'cancelled'::text]))),
    CONSTRAINT supplier_payables_terms_snapshot_check CHECK ((jsonb_typeof(terms_snapshot) = 'object'::text)),
    CONSTRAINT supplier_payables_total_amount_check CHECK ((total_amount >= (0)::numeric)),
    CONSTRAINT supplier_payables_unit_price_check CHECK ((unit_price >= (0)::numeric))
);


ALTER TABLE apticket.supplier_payables OWNER TO supabase_admin;

--
-- Name: TABLE supplier_payables; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON TABLE apticket.supplier_payables IS 'Lancamentos recorrentes de fornecedores com termos e totais congelados.';


--
-- Name: COLUMN supplier_payables.manual_entry_group_id; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON COLUMN apticket.supplier_payables.manual_entry_group_id IS 'Matriz do documento manual que originou a parcela.';


--
-- Name: prepare_payable_mutation(uuid, integer); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_payable_mutation(p_id uuid, p_expected_revision integer) RETURNS apticket.supplier_payables
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare p apticket.supplier_payables; v_tenant uuid:=apticket.current_tenant_id();
begin
  if auth.uid() is null or v_tenant is null
    or not apticket.has_permission(auth.uid(),'financeiro_contas_pagar','edit')
    or not exists(select 1 from apticket.profiles where id=auth.uid() and tenant_id=v_tenant and is_active) then
    raise exception using errcode='42501',message='Sem permissão para alterar ou excluir contas a pagar.';
  end if;
  select * into p from apticket.supplier_payables where id=p_id and tenant_id=v_tenant and deleted_at is null;
  if not found then raise exception using errcode='P0002',message='Lançamento não encontrado.'; end if;
  if not apticket.has_financial_scope(p.tenant_id,p.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem acesso financeiro de escrita nesta empresa.';
  end if;
  -- Mesma ordem usada pelas decisões de aprovação: solicitação, depois lançamento.
  perform 1 from apticket.supplier_payable_approval_requests where supplier_payable_id=p_id
    and status in ('pending','approved') order by id for update;
  select * into p from apticket.supplier_payables where id=p_id for update;
  if p_expected_revision is null or p.revision<>p_expected_revision then
    raise exception using errcode='40001',message='Este lançamento foi atualizado por outra operação. Reabra a tela antes de continuar.';
  end if;
  if p.deleted_at is not null or p.status in ('paid','cancelled') then
    raise exception using errcode='P0001',message='Lançamentos pagos, cancelados ou excluídos não podem ser alterados ou excluídos.';
  end if;
  if exists(select 1 from apticket.supplier_payments where supplier_payable_id=p.id and status in ('scheduled','paid')) then
    raise exception using errcode='P0001',message='Cancele a programação do pagamento antes de alterar ou excluir este lançamento.';
  end if;
  return p;
end $$;


ALTER FUNCTION apticket_finance_private.prepare_payable_mutation(p_id uuid, p_expected_revision integer) OWNER TO supabase_admin;

--
-- Name: prepare_supplier(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_supplier() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare v_actor uuid:=auth.uid();
begin
  if tg_op='INSERT' then
    if new.tenant_id is distinct from apticket.current_tenant_id() then
      raise exception using errcode='42501',message='O fornecedor deve pertencer a tenant ativa.';
    end if;
    new.created_by:=v_actor; new.created_at:=clock_timestamp();
  elsif new.id is distinct from old.id or new.tenant_id is distinct from old.tenant_id
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception using errcode='23514',message='A identidade do fornecedor nao pode ser alterada.';
  elsif old.deleted_at is not null then
    raise exception using errcode='23514',message='Um fornecedor arquivado nao pode ser alterado.';
  end if;
  if tg_op='UPDATE' and old.deleted_at is null and new.deleted_at is not null
     and exists(select 1 from apticket.supplier_contracts c
       where c.supplier_id=old.id and c.deleted_at is null and c.is_active) then
    raise exception using errcode='23514',message='Arquive os contratos ativos antes de arquivar o fornecedor.';
  end if;
  new.legal_name:=btrim(new.legal_name);
  new.trade_name:=nullif(btrim(new.trade_name),'');
  new.tax_id:=nullif(regexp_replace(coalesce(new.tax_id,''),'[^0-9]','','g'),'');
  new.contact_name:=nullif(btrim(new.contact_name),'');
  new.email:=nullif(lower(btrim(new.email)),'');
  new.phone:=nullif(btrim(new.phone),'');
  new.website:=nullif(btrim(new.website),'');
  new.address_zip:=nullif(regexp_replace(coalesce(new.address_zip,''),'[^0-9]','','g'),'');
  new.address_street:=nullif(btrim(new.address_street),'');
  new.address_number:=nullif(btrim(new.address_number),'');
  new.address_complement:=nullif(btrim(new.address_complement),'');
  new.address_neighborhood:=nullif(btrim(new.address_neighborhood),'');
  new.address_city:=nullif(btrim(new.address_city),'');
  new.address_state:=nullif(upper(btrim(new.address_state)),'');
  new.cnaes:=coalesce(new.cnaes,'[]'::jsonb);
  new.notes:=nullif(btrim(new.notes),'');
  new.updated_by:=v_actor; new.updated_at:=clock_timestamp();
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.prepare_supplier() OWNER TO supabase_admin;

--
-- Name: prepare_supplier_contract(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.prepare_supplier_contract() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare v_actor uuid:=auth.uid();
begin
  if tg_op='INSERT' then
    if new.tenant_id is distinct from apticket.current_tenant_id() then
      raise exception using errcode='42501',message='O contrato deve pertencer a tenant ativa.';
    end if;
    new.created_by:=v_actor; new.created_at:=clock_timestamp();
  elsif new.id is distinct from old.id or new.tenant_id is distinct from old.tenant_id
     or new.operating_company_id is distinct from old.operating_company_id
     or new.supplier_id is distinct from old.supplier_id
     or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then
    raise exception using errcode='23514',message='A identidade e os vinculos do contrato nao podem ser alterados.';
  elsif old.deleted_at is not null then
    raise exception using errcode='23514',message='Um contrato arquivado nao pode ser alterado.';
  end if;
  new.description:=btrim(new.description);
  new.notes:=nullif(btrim(new.notes),'');
  new.updated_by:=v_actor; new.updated_at:=clock_timestamp();
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.prepare_supplier_contract() OWNER TO supabase_admin;

--
-- Name: process_contract_financial_events(integer, date); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.process_contract_financial_events(p_limit integer DEFAULT 100, p_as_of date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_event apticket.financial_domain_events;
  v_receivable apticket.contas_receber;
  v_contract apticket.contracts;
  v_hold apticket.contract_financial_holds;
  v_has_financial_hold boolean;
  v_suspended integer:=0;
  v_released integer:=0;
  v_ignored integer:=0;
  v_failed integer:=0;
  v_resulting_status text;
begin
  if coalesce(current_setting('request.jwt.claim.role',true),'')<>'service_role' then
    raise exception using errcode='42501',message='O processamento de contratos exige credencial de servico.';
  end if;
  if p_limit not between 1 and 500 or p_as_of is null or p_as_of>current_date then
    raise exception using errcode='22023',message='Limite ou data de processamento invalida.';
  end if;

  update apticket.financial_domain_events
     set status='failed',last_error='Processamento interrompido antes da confirmacao.',
         next_attempt_at=clock_timestamp(),processed_at=clock_timestamp()
   where event_type='contract.suspended_for_delinquency'
     and status='processing'
     and processed_at<clock_timestamp()-interval '30 minutes';

  for v_event in
    select e.* from apticket.financial_domain_events e
     where e.event_type='contract.suspended_for_delinquency'
       and e.status in ('pending','failed') and e.attempt_count<5
       and apticket_finance_private.financial_feature_enabled(e.tenant_id,'collection_rules')
       and e.next_attempt_at is not null and e.next_attempt_at<=clock_timestamp()
     order by e.occurred_at,e.id
     for update skip locked limit p_limit
  loop
    begin
      update apticket.financial_domain_events
         set status='processing',attempt_count=attempt_count+1,
             last_error=null,processed_at=clock_timestamp()
       where id=v_event.id;

      select * into strict v_receivable from apticket.contas_receber
       where id=v_event.source_id and tenant_id=v_event.tenant_id
         and operating_company_id=v_event.operating_company_id for update;

      if v_receivable.deleted_at is not null
         or v_receivable.status_cobranca<>'vencido'
         or v_receivable.valor_aberto<=0 then
        update apticket.financial_domain_events
           set status='cancelled',last_error='Titulo sem inadimplencia ativa.',
               next_attempt_at=null,processed_at=clock_timestamp()
         where id=v_event.id;
        v_ignored:=v_ignored+1;
        continue;
      end if;

      select * into strict v_contract from apticket.contracts
       where id=v_event.aggregate_id and tenant_id=v_event.tenant_id for update;
      select exists(select 1 from apticket.contract_financial_holds h
        where h.contract_id=v_contract.id and h.status='active') into v_has_financial_hold;

      if v_contract.status='active' and v_contract.starts_at<=p_as_of
         and v_contract.ends_at>=p_as_of then
        insert into apticket.contract_financial_holds(
          tenant_id,operating_company_id,contract_id,event_id,receivable_id,
          status,changed_contract_status,previous_contract_status
        ) values (
          v_event.tenant_id,v_event.operating_company_id,v_contract.id,v_event.id,
          v_receivable.id,'active',true,v_contract.status
        );
        perform set_config('apticket.financial_event_processing','on',true);
        update apticket.contracts set status='suspended' where id=v_contract.id;
        v_suspended:=v_suspended+1;
      elsif v_contract.status='suspended' and v_has_financial_hold then
        insert into apticket.contract_financial_holds(
          tenant_id,operating_company_id,contract_id,event_id,receivable_id,
          status,changed_contract_status,previous_contract_status
        ) values (
          v_event.tenant_id,v_event.operating_company_id,v_contract.id,v_event.id,
          v_receivable.id,'active',false,v_contract.status
        );
      else
        insert into apticket.contract_financial_holds(
          tenant_id,operating_company_id,contract_id,event_id,receivable_id,
          status,changed_contract_status,previous_contract_status,release_reason,released_at
        ) values (
          v_event.tenant_id,v_event.operating_company_id,v_contract.id,v_event.id,
          v_receivable.id,'ignored',false,v_contract.status,
          case when v_contract.status='suspended' then 'preexisting_suspension'
               else 'contract_not_eligible' end,clock_timestamp()
        );
        v_ignored:=v_ignored+1;
      end if;

      update apticket.financial_domain_events
         set status='processed',last_error=null,next_attempt_at=null,
             processed_at=clock_timestamp()
       where id=v_event.id;
    exception when others then
      update apticket.financial_domain_events
         set status='failed',attempt_count=least(attempt_count+1,20),
             last_error=left(sqlerrm,2000),
             next_attempt_at=case when attempt_count+1<5 then
               clock_timestamp()+make_interval(mins=>least(1440,15*(2^greatest(attempt_count,0))::integer)) end,
             processed_at=clock_timestamp()
       where id=v_event.id;
      v_failed:=v_failed+1;
    end;
  end loop;

  for v_hold in
    select h.* from apticket.contract_financial_holds h
    join apticket.contas_receber r on r.id=h.receivable_id
     where h.status='active'
       and (r.deleted_at is not null or r.status_cobranca<>'vencido' or r.valor_aberto<=0)
     order by h.applied_at,h.id for update of h skip locked limit p_limit
  loop
    update apticket.contract_financial_holds
       set status='released',released_at=clock_timestamp(),release_reason='payment_settled'
     where id=v_hold.id;
  end loop;

  for v_hold in
    select h.* from apticket.contract_financial_holds h
     where h.status='released' and h.changed_contract_status and h.restored_at is null
       and not exists(select 1 from apticket.contract_financial_holds active_hold
         where active_hold.contract_id=h.contract_id and active_hold.status='active')
     order by h.released_at,h.id for update of h skip locked limit p_limit
  loop
    select * into strict v_contract from apticket.contracts
     where id=v_hold.contract_id and tenant_id=v_hold.tenant_id for update;
    v_resulting_status:=v_contract.status::text;
    if v_contract.status='suspended' then
      v_resulting_status:=case when v_contract.ends_at<p_as_of then 'expired' else 'active' end;
      perform set_config('apticket.financial_event_processing','on',true);
      update apticket.contracts
         set status=v_resulting_status::apticket.contract_status
       where id=v_contract.id;
      v_released:=v_released+1;
    end if;
    update apticket.contract_financial_holds
       set restored_at=clock_timestamp() where id=v_hold.id;
    insert into apticket.financial_domain_events(
      tenant_id,operating_company_id,aggregate_type,aggregate_id,event_type,
      source_id,payload,status,attempt_count,next_attempt_at,processed_at
    ) values (
      v_hold.tenant_id,v_hold.operating_company_id,'contract',v_hold.contract_id,
      'contract.financial_suspension_released',v_hold.receivable_id,
      jsonb_build_object('hold_id',v_hold.id,'resulting_status',v_resulting_status,
        'release_reason',v_hold.release_reason),
      'processed',1,null,clock_timestamp()
    ) on conflict(event_type,source_id) do nothing;
  end loop;

  return jsonb_build_object(
    'suspended_contracts',v_suspended,
    'released_contracts',v_released,
    'ignored_events',v_ignored,
    'failed_events',v_failed
  );
end $$;


ALTER FUNCTION apticket_finance_private.process_contract_financial_events(p_limit integer, p_as_of date) OWNER TO supabase_admin;

--
-- Name: protect_billed_sources(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.protect_billed_sources() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  -- Executa antes dos validadores da fatia 1: adquirir o lock ANTES de
  -- consultar ciclos evita corrida entre fechamento e reajuste/exclusão.
  if tg_table_name <> 'contract_financial_terms' then
    perform 1 from apticket.contract_financial_terms where contract_id=new.contract_id for update;
  end if;
  if tg_table_name='contract_financial_terms' then
    if row(new.billing_anchor_month,new.billing_interval_months,new.cutoff_day)
      is distinct from row(old.billing_anchor_month,old.billing_interval_months,old.cutoff_day)
      and exists(select 1 from apticket.billing_cycles where contract_id=new.contract_id) then
      raise exception using errcode='23514', message='O calendário de um contrato já faturado não pode ser reescrito.';
    end if;
  elsif tg_op='INSERT' and tg_table_name='consumption_snapshots' then
    if exists(select 1 from apticket.billing_cycles b where b.contract_id=new.contract_id
      and b.service_start<new.cycle_end and b.service_end>new.cycle_start) then
      raise exception using errcode='23514', message='Não é permitido adicionar consumo a um ciclo fechado.';
    end if;
  elsif tg_op='INSERT' then
    if exists(select 1 from apticket.billing_cycles b where b.contract_id=new.contract_id
      and b.service_end > new.effective_from) then
      raise exception using errcode='23514', message='O reajuste não pode alterar um ciclo já faturado.';
    end if;
  elsif new.deleted_at is distinct from old.deleted_at then
    if (tg_table_name='contract_value_versions' and exists(select 1 from apticket.billing_cycle_items where value_version_id=new.id))
      or (tg_table_name='consumption_snapshots' and exists(select 1 from apticket.billing_cycle_items where consumption_snapshot_id=new.id)) then
      raise exception using errcode='23514', message='Uma fonte já faturada não pode ser excluída.';
    end if;
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.protect_billed_sources() OWNER TO postgres;

--
-- Name: protect_contract_operator(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.protect_contract_operator() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.operating_company_id is distinct from old.operating_company_id and (
    exists(select 1 from apticket.medicoes_contrato where contrato_id=old.id)
    or exists(select 1 from apticket.contract_financial_terms where contract_id=old.id)
  ) then
    raise exception using errcode='23514',
      message='A empresa operadora nao pode ser alterada depois que o contrato possui medicao ou configuracao financeira.';
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.protect_contract_operator() OWNER TO supabase_admin;

--
-- Name: protect_supplier_contract_number(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.protect_supplier_contract_number() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if new.numero_contrato is distinct from old.numero_contrato then
    raise exception using errcode='23514',message='O numero do contrato de fornecedor nao pode ser alterado.';
  end if;
  return new;
end
$$;


ALTER FUNCTION apticket_finance_private.protect_supplier_contract_number() OWNER TO supabase_admin;

--
-- Name: protect_supplier_payable_sources(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.protect_supplier_payable_sources() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if tg_table_name='supplier_contracts' then
    if row(new.billing_unit,new.billing_interval_months,new.base_amount,new.unit_price,new.due_day,new.starts_at)
      is distinct from
      row(old.billing_unit,old.billing_interval_months,old.base_amount,old.unit_price,old.due_day,old.starts_at)
      and exists(select 1 from apticket.supplier_payables p
        where p.supplier_contract_id=old.id and p.deleted_at is null) then
      raise exception using errcode='23514',message='As condicoes de um contrato com lancamentos gerados nao podem ser alteradas.';
    end if;
  elsif new.deleted_at is distinct from old.deleted_at
    and exists(select 1 from apticket.supplier_payable_allocations a
      where a.consumption_snapshot_id=old.id and a.deleted_at is null) then
    raise exception using errcode='23514',message='Um consumo utilizado no rateio nao pode ser arquivado.';
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.protect_supplier_payable_sources() OWNER TO supabase_admin;

--
-- Name: refresh_statement_import(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.refresh_statement_import(p_import_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
declare v_review integer; v_matched integer; begin
  select count(*) filter(where reconciliation_status='pending_review'),
    count(*) filter(where reconciliation_status in ('matched_auto','matched_manual'))
    into v_review,v_matched
  from apticket.bank_statement_transactions where import_id=p_import_id and deleted_at is null;
  update apticket.bank_statement_imports set review_count=v_review,auto_matched_count=v_matched,
    status=case when v_review=0 then 'processed' else 'needs_review' end,
    processed_at=clock_timestamp() where id=p_import_id;
end $$;


ALTER FUNCTION apticket_finance_private.refresh_statement_import(p_import_id uuid) OWNER TO supabase_admin;

--
-- Name: release_hold_on_manual_contract_change(); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.release_hold_on_manual_contract_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
begin
  if old.status is distinct from new.status
     and coalesce(current_setting('apticket.financial_event_processing', true),'') <> 'on' then
    update apticket.contract_financial_holds
       set status=case when status='active' then 'released' else status end,
           changed_contract_status=false,
           released_at=coalesce(released_at,clock_timestamp()),
           release_reason='manual_override'
     where contract_id=new.id and tenant_id=new.tenant_id
       and restored_at is null and (status='active' or changed_contract_status);
  end if;
  return new;
end $$;


ALTER FUNCTION apticket_finance_private.release_hold_on_manual_contract_change() OWNER TO supabase_admin;

--
-- Name: reopen_financial_period_internal(uuid, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.reopen_financial_period_internal(p_closure_id uuid, p_reason text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare closure apticket.financial_period_closures; v_actor_name text; begin
  if not apticket.has_permission(auth.uid(),'financeiro_fechamento','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  select * into closure from apticket.financial_period_closures current_closure
    where current_closure.id=p_closure_id and current_closure.status='closed' for update;
  if not found then
    raise exception using errcode='P0002',message='Fechamento ativo não encontrado.';
  end if;
  if auth.uid() is null
    or not apticket.has_financial_scope(closure.tenant_id,closure.operating_company_id,true) then
    raise exception using errcode='42501',message='Sem permissão financeira para reabrir esta competência.';
  end if;
  if length(btrim(coalesce(p_reason,''))) not between 10 and 1000 then
    raise exception using errcode='23514',message='Informe uma justificativa com pelo menos 10 caracteres.';
  end if;
  select profile.name into v_actor_name from apticket.profiles profile
    where profile.id=auth.uid() and profile.tenant_id=closure.tenant_id and profile.is_active;
  if v_actor_name is null then
    raise exception using errcode='42501',message='Usuário responsável não está ativo.';
  end if;
  update apticket.financial_period_closures set status='reopened',reopened_by=auth.uid(),
    reopened_by_name=v_actor_name,reopen_reason=btrim(p_reason),reopened_at=clock_timestamp()
  where id=closure.id;
  return true;
end $$;


ALTER FUNCTION apticket_finance_private.reopen_financial_period_internal(p_closure_id uuid, p_reason text) OWNER TO supabase_admin;

--
-- Name: require_fixed_access(uuid, uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.require_fixed_access(p_tenant uuid, p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ begin
  if auth.uid() is null or p_tenant is distinct from apticket.current_tenant_id()
    or not apticket.has_permission(auth.uid(),'financeiro_contas_fixas','edit')
    or not apticket.has_financial_scope(p_tenant,p_company,true)
    or not exists(select 1 from apticket.profiles where id=auth.uid() and tenant_id=p_tenant and is_active)
  then raise exception using errcode='42501',message='Sem permissão para gerir contas fixas nesta empresa.'; end if;
end $$;


ALTER FUNCTION apticket_finance_private.require_fixed_access(p_tenant uuid, p_company uuid) OWNER TO supabase_admin;

--
-- Name: review_inter_binding(uuid, text); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.review_inter_binding(p_company uuid, p_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  c apticket.operating_companies; cfg apticket.tenant_inter_configurations;
  b apticket.operating_company_inter_bindings; tenant_tax text; reason text;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_bancos','view') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null then raise exception using errcode='42501',message='Sessão obrigatória.'; end if;
  select * into c from apticket.operating_companies where id=p_company
    and tenant_id=apticket.current_tenant_id() and deleted_at is null;
  if not found or not apticket.has_financial_scope(c.tenant_id,c.id) then
    raise exception using errcode='42501',message='Empresa indisponível ou sem acesso financeiro.';
  end if;
  if p_environment is null or p_environment not in ('sandbox','production') then
    raise exception using errcode='22023',message='Ambiente inválido.';
  end if;
  select regexp_replace(cnpj,'[^0-9]','','g') into tenant_tax from apticket.tenants where id=c.tenant_id;
  select * into cfg from apticket.tenant_inter_configurations where tenant_id=c.tenant_id and operating_company_id=c.id and environment=p_environment;
  select * into b from apticket.operating_company_inter_bindings where tenant_id=c.tenant_id and operating_company_id=c.id
    and environment=p_environment and deleted_at is null;
  reason := case
    when c.tax_id is null then 'company_tax_mismatch'
    when cfg.tenant_id is null then 'configuration_missing'
    when cfg.certificate_expires_at<=now() then 'certificate_expired'
    when b.id is null then 'confirmation_required'
    when b.operating_company_id<>c.id then 'bound_to_another_company'
    when b.configuration_version<>cfg.version or b.company_tax_id<>c.tax_id then 'confirmation_outdated'
    else 'confirmed' end;
  return jsonb_build_object('environment',p_environment,'state',reason,
    'configuration_version',cfg.version,'account_last_four',right(cfg.account,4),
    'certificate_expires_at',cfg.certificate_expires_at,
    'binding_id',case when b.operating_company_id=c.id then b.id end,
    'confirmed_at',case when b.operating_company_id=c.id then b.created_at end,
    'bank_ownership_verified',false,'dispatch_enabled',false);
end $$;


ALTER FUNCTION apticket_finance_private.review_inter_binding(p_company uuid, p_environment text) OWNER TO postgres;

--
-- Name: review_inter_payer(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.review_inter_payer(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
declare
  req apticket.inter_charge_requests;
  rec apticket.contas_receber;
  customer apticket.companies;
  cfg apticket.tenant_inter_configurations;
  binding apticket.operating_company_inter_bindings;
  snap apticket.inter_payer_snapshots;
  missing text[] := '{}';
  tax text;
  zip text;
  phone_parts text[];
  ddd text;
  local_phone text;
  canonical_phone text;
  number_code text;
  state text;
  fingerprint text;
  result_state text;
  binding_review jsonb;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','view') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'Sessão obrigatória.';
  end if;

  select * into req
  from apticket.inter_charge_requests
  where id = p_request
    and tenant_id = apticket.current_tenant_id()
    and deleted_at is null;

  if not found or not apticket.has_financial_scope(req.tenant_id, req.operating_company_id) then
    raise exception using errcode = '42501',
      message = 'Solicitação indisponível ou sem acesso à empresa.';
  end if;

  select * into rec
  from apticket.contas_receber
  where id = req.receivable_id
    and tenant_id = req.tenant_id
    and operating_company_id = req.operating_company_id
    and deleted_at is null;
  if not found then
    raise exception using errcode = '23514', message = 'Recebível da solicitação indisponível.';
  end if;

  select * into customer
  from apticket.companies
  where id = rec.company_id and tenant_id = req.tenant_id;
  if not found then
    raise exception using errcode = '23514', message = 'Cliente da solicitação indisponível.';
  end if;

  select * into cfg
  from apticket.tenant_inter_configurations
  where tenant_id = req.tenant_id and operating_company_id = req.operating_company_id and environment = req.environment;
  select * into binding
  from apticket.operating_company_inter_bindings
  where tenant_id = req.tenant_id
    and operating_company_id = req.operating_company_id
    and environment = req.environment
    and deleted_at is null;
  binding_review := apticket_finance_private.review_inter_binding(
    req.operating_company_id,
    req.environment
  );
  select * into snap
  from apticket.inter_payer_snapshots
  where request_id = req.id and deleted_at is null;

  tax := regexp_replace(coalesce(customer.cnpj, ''), '[^0-9]', '', 'g');
  zip := regexp_replace(coalesce(customer.address_zip, ''), '[^0-9]', '', 'g');
  phone_parts := apticket_finance_private.normalize_inter_phone(customer.phone);
  ddd := phone_parts[1];
  local_phone := phone_parts[2];
  canonical_phone := coalesce(ddd, '') || coalesce(local_phone, '');
  state := upper(btrim(coalesce(customer.address_state, '')));
  number_code := 'AP' || upper(left(replace(req.id::text, '-', ''), 13));
  fingerprint := md5(concat_ws(chr(31),
    btrim(coalesce(customer.name, '')), tax, canonical_phone,
    btrim(coalesce(customer.address_street, '')),
    btrim(coalesce(customer.address_number, '')),
    btrim(coalesce(customer.address_complement, '')),
    btrim(coalesce(customer.address_neighborhood, '')),
    btrim(coalesce(customer.address_city, '')), state, zip
  ));

  if length(btrim(coalesce(customer.name, ''))) not between 1 and 100 then
    missing := array_append(missing, 'name');
  end if;
  if not apticket_finance_private.is_valid_cnpj(tax) then
    missing := array_append(missing, 'tax_id');
  end if;
  if length(btrim(coalesce(customer.address_street, ''))) not between 1 and 200 then
    missing := array_append(missing, 'street');
  end if;
  if length(btrim(coalesce(customer.address_number, ''))) not between 1 and 20 then
    missing := array_append(missing, 'number');
  end if;
  if length(btrim(coalesce(customer.address_neighborhood, ''))) not between 1 and 120 then
    missing := array_append(missing, 'district');
  end if;
  if length(btrim(coalesce(customer.address_city, ''))) not between 1 and 100 then
    missing := array_append(missing, 'city');
  end if;
  if not state = any(array[
    'AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB',
    'PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO'
  ]) then
    missing := array_append(missing, 'state');
  end if;
  if zip !~ '^[0-9]{8}$' then missing := array_append(missing, 'zip'); end if;
  if btrim(coalesce(customer.phone, '')) <> '' and local_phone is null then
    missing := array_append(missing, 'phone');
  end if;
  if req.amount not between 2.50 and 99999999.99 then
    missing := array_append(missing, 'amount');
  end if;
  if req.due_date < current_date then missing := array_append(missing, 'due_date'); end if;
  if rec.status_cobranca <> 'a_faturar'
    or rec.valor_aberto <> rec.valor_original
    or req.amount <> rec.valor_aberto
    or req.due_date <> rec.vencimento_em then
    missing := array_append(missing, 'receivable');
  end if;

  result_state := case
    when cardinality(missing) > 0 then 'missing_data'
    when cfg.tenant_id is null or binding.id is null
      or binding.configuration_version <> cfg.version
      or binding_review ->> 'state' <> 'confirmed' then 'binding_required'
    when snap.id is null then 'confirmation_required'
    when snap.binding_id <> binding.id or snap.source_fingerprint <> fingerprint
      or snap.amount <> req.amount or snap.due_date <> req.due_date then 'confirmation_outdated'
    else 'confirmed'
  end;

  return jsonb_build_object(
    'state', result_state,
    'missing_fields', to_jsonb(missing),
    'request_id', req.id,
    'environment', req.environment,
    'binding_id', binding.id,
    'snapshot_id', snap.id,
    'confirmed_at', snap.created_at,
    'source_updated_at', customer.updated_at,
    'source_fingerprint', fingerprint,
    'seu_numero', number_code,
    'amount', req.amount,
    'due_date', req.due_date,
    'payer', jsonb_build_object(
      'name', btrim(customer.name),
      'tax_id', nullif(tax, ''),
      'type', 'JURIDICA',
      'email', null,
      'ddd', ddd,
      'phone', local_phone,
      'street', nullif(btrim(customer.address_street), ''),
      'number', nullif(btrim(customer.address_number), ''),
      'complement', nullif(btrim(customer.address_complement), ''),
      'district', nullif(btrim(customer.address_neighborhood), ''),
      'city', nullif(btrim(customer.address_city), ''),
      'state', nullif(state, ''),
      'zip', nullif(zip, '')
    ),
    'dispatch_enabled', false
  );
end
$_$;


ALTER FUNCTION apticket_finance_private.review_inter_payer(p_request uuid) OWNER TO postgres;

--
-- Name: review_inter_payer_display(uuid); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.review_inter_payer_display(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  req apticket.inter_charge_requests;
  snap apticket.inter_payer_snapshots;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','view') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if auth.uid() is null then
    raise exception using errcode = '42501', message = 'Sessao obrigatoria.';
  end if;

  select * into req
  from apticket.inter_charge_requests
  where id = p_request
    and tenant_id = apticket.current_tenant_id()
    and deleted_at is null;

  if not found or not apticket.has_financial_scope(req.tenant_id, req.operating_company_id) then
    raise exception using errcode = '42501',
      message = 'Solicitacao indisponivel ou sem acesso a empresa.';
  end if;

  if req.status not in ('submitted', 'uncertain') then
    return apticket_finance_private.review_inter_payer(p_request);
  end if;

  select * into snap
  from apticket.inter_payer_snapshots
  where request_id = req.id and deleted_at is null;

  if not found then
    raise exception using errcode = '23514',
      message = 'Snapshot confirmado do pagador indisponivel.';
  end if;

  return jsonb_build_object(
    'state', 'confirmed',
    'missing_fields', '[]'::jsonb,
    'request_id', req.id,
    'environment', req.environment,
    'binding_id', snap.binding_id,
    'snapshot_id', snap.id,
    'confirmed_at', snap.created_at,
    'source_updated_at', snap.source_updated_at,
    'source_fingerprint', snap.source_fingerprint,
    'seu_numero', snap.seu_numero,
    'amount', snap.amount,
    'due_date', snap.due_date,
    'payer', jsonb_build_object(
      'name', snap.payer_name,
      'tax_id', snap.payer_tax_id,
      'type', snap.payer_type,
      'email', snap.payer_email,
      'ddd', snap.payer_ddd,
      'phone', snap.payer_phone,
      'street', snap.payer_street,
      'number', snap.payer_number,
      'complement', snap.payer_complement,
      'district', snap.payer_district,
      'city', snap.payer_city,
      'state', snap.payer_state,
      'zip', snap.payer_zip
    ),
    'dispatch_enabled', false
  );
end
$$;


ALTER FUNCTION apticket_finance_private.review_inter_payer_display(p_request uuid) OWNER TO supabase_admin;

--
-- Name: save_collection_policy(uuid, boolean, integer, jsonb); Type: FUNCTION; Schema: apticket_finance_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_finance_private.save_collection_policy(p_company uuid, p_enabled boolean, p_suspend_after_days integer, p_steps jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare v_tenant uuid:=apticket.current_tenant_id(); v_actor uuid:=auth.uid(); v_policy uuid; v_step jsonb; v_pos int:=0;
begin
  if not apticket.has_permission(auth.uid(),'financeiro_contas_receber','edit') then
    raise exception using errcode='42501',message='Sem permissao para esta operacao financeira.';
  end if;
  if v_actor is null or v_tenant is null or not apticket.has_financial_scope(v_tenant,p_company,true) then
    raise exception using errcode='42501',message='Você não possui permissão para configurar a régua de cobrança.';
  end if;
  if p_suspend_after_days is not null and p_suspend_after_days not between 1 and 365 then
    raise exception using errcode='22023',message='O prazo de suspensão deve ficar entre 1 e 365 dias.';
  end if;
  if jsonb_typeof(p_steps)<>'array' or jsonb_array_length(p_steps)>10 then
    raise exception using errcode='22023',message='Informe uma lista com até 10 etapas de cobrança.';
  end if;
  insert into apticket.collection_policies(tenant_id,operating_company_id,enabled,suspend_after_days,created_by,updated_by)
  values(v_tenant,p_company,p_enabled,p_suspend_after_days,v_actor,v_actor)
  on conflict(tenant_id,operating_company_id) do update set enabled=excluded.enabled,
    suspend_after_days=excluded.suspend_after_days,updated_by=v_actor,updated_at=clock_timestamp(),deleted_at=null
  returning id into v_policy;
  for v_step in select value from jsonb_array_elements(p_steps) loop
    v_pos:=v_pos+1;
    if coalesce((v_step->>'channel'),'') not in ('email','whatsapp','sms')
       or (v_step->>'days_after_due')::int not between -30 and 365
       or length(btrim(coalesce(v_step->>'message_template',''))) not between 1 and 4000 then
      raise exception using errcode='22023',message='Uma etapa da régua possui canal, prazo ou mensagem inválida.';
    end if;
    insert into apticket.collection_policy_steps(tenant_id,operating_company_id,policy_id,position,
      days_after_due,channel,subject,message_template,enabled)
    values(v_tenant,p_company,v_policy,v_pos,(v_step->>'days_after_due')::int,v_step->>'channel',
      nullif(btrim(v_step->>'subject'),''),btrim(v_step->>'message_template'),coalesce((v_step->>'enabled')::boolean,true))
    on conflict(policy_id,position) do update set days_after_due=excluded.days_after_due,
      channel=excluded.channel,subject=excluded.subject,message_template=excluded.message_template,
      enabled=excluded.enabled,deleted_at=null;
  end loop;
  update apticket.collection_policy_steps set deleted_at=clock_timestamp()
    where policy_id=v_policy and position>v_pos and deleted_at is null;
  return v_policy;
end $$;


ALTER FUNCTION apticket_finance_private.save_collection_policy(p_company uuid, p_enabled boolean, p_suspend_after_days integer, p_steps jsonb) OWNER TO supabase_admin;

--
-- Name: schedule_cycle_closure(); Type: FUNCTION; Schema: apticket_finance_private; Owner: postgres
--

CREATE FUNCTION apticket_finance_private.schedule_cycle_closure() RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
declare v_job bigint;
begin
  if not exists(select 1 from vault.decrypted_secrets where name='apticket_internal_functions_url')
    or not exists(select 1 from vault.decrypted_secrets where name='apticket_edge_service_role_key') then
    raise exception 'Configure os segredos do agendamento no Vault.';
  end if;
  select cron.schedule('apticket-fechar-ciclos-financeiros','10 * * * *', $cron$
    select net.http_post(
      url:=(select decrypted_secret from vault.decrypted_secrets where name='apticket_internal_functions_url')||'/functions/v1/fechar-ciclos-financeiros',
      headers:=jsonb_build_object('Content-Type','application/json',
        'apikey',(select decrypted_secret from vault.decrypted_secrets where name='apticket_edge_service_role_key'),
        'Authorization','Bearer '||(select decrypted_secret from vault.decrypted_secrets where name='apticket_edge_service_role_key')),
      body:='{"limit":50}'::jsonb,timeout_milliseconds:=50000);
  $cron$) into v_job;
  return v_job;
end $_$;


ALTER FUNCTION apticket_finance_private.schedule_cycle_closure() OWNER TO postgres;

