end
$$;


ALTER FUNCTION apticket_hr_private.normalize_employee_emails() OWNER TO supabase_admin;

--
-- Name: prepare_employee(); Type: FUNCTION; Schema: apticket_hr_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_hr_private.prepare_employee() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  next_number integer;
begin
  new.cpf := nullif(regexp_replace(coalesce(new.cpf, ''), '\D', '', 'g'), '');
  new.pis_pasep := nullif(regexp_replace(coalesce(new.pis_pasep, ''), '\D', '', 'g'), '');

  if new.cpf is not null and not apticket_hr_private.validate_cpf(new.cpf) then
    raise exception using errcode = '23514', message = 'CPF inválido.';
  end if;

  new.ctps_numero := nullif(btrim(new.ctps_numero), '');
  new.ctps_serie := nullif(btrim(new.ctps_serie), '');

  if nullif(btrim(new.matricula), '') is null then
    perform pg_advisory_xact_lock(hashtextextended(new.tenant_id::text, 78431));
    select coalesce(max(nullif(regexp_replace(matricula, '\D', '', 'g'), '')::integer), 0) + 1
    into next_number
    from apticket.funcionarios
    where tenant_id = new.tenant_id;
    new.matricula := 'FUN-' || lpad(next_number::text, 6, '0');
  end if;

  new.updated_at := clock_timestamp();
  new.updated_by := coalesce(auth.uid(), new.updated_by);
  return new;
end
$$;


ALTER FUNCTION apticket_hr_private.prepare_employee() OWNER TO supabase_admin;

--
-- Name: FUNCTION prepare_employee(); Type: COMMENT; Schema: apticket_hr_private; Owner: supabase_admin
--

COMMENT ON FUNCTION apticket_hr_private.prepare_employee() IS 'Normaliza e valida funcionarios em trigger; executa como owner para acessar validadores privados.';


--
-- Name: prepare_employee_document(); Type: FUNCTION; Schema: apticket_hr_private; Owner: supabase_admin
--

CREATE FUNCTION apticket_hr_private.prepare_employee_document() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$ declare validity integer; begin
  select validade_em_dias into validity from apticket.funcionario_tipos_documento where id=new.tipo_documento_id and deleted_at is null;
  if new.data_validade is null and new.data_emissao is not null and validity is not null then new.data_validade:=new.data_emissao+validity; end if;
  if new.data_validade is not null and new.data_validade<current_date then new.status:='vencido'; end if;
  new.updated_at:=clock_timestamp(); return new;
end $$;


