    period_start date NOT NULL,
    period_end date NOT NULL,
    status text NOT NULL,
    transaction_count integer NOT NULL,
    auto_matched_count integer DEFAULT 0 NOT NULL,
    review_count integer DEFAULT 0 NOT NULL,
    imported_by uuid,
    imported_by_name text NOT NULL,
    imported_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    processed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT bank_statement_imports_auto_matched_count_check CHECK ((auto_matched_count >= 0)),
    CONSTRAINT bank_statement_imports_check CHECK ((period_end >= period_start)),
    CONSTRAINT bank_statement_imports_check1 CHECK (((auto_matched_count + review_count) <= transaction_count)),
    CONSTRAINT bank_statement_imports_file_hash_check CHECK ((file_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT bank_statement_imports_review_count_check CHECK ((review_count >= 0)),
    CONSTRAINT bank_statement_imports_source_type_check CHECK ((source_type = ANY (ARRAY['ofx'::text, 'bank_api'::text]))),
    CONSTRAINT bank_statement_imports_status_check CHECK ((status = ANY (ARRAY['processed'::text, 'needs_review'::text]))),
    CONSTRAINT bank_statement_imports_transaction_count_check CHECK (((transaction_count >= 1) AND (transaction_count <= 5000)))
);


