--
-- Name: bank_statement_transactions; Type: TABLE; Schema: apticket; Owner: supabase_admin
--

CREATE TABLE apticket.bank_statement_transactions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    import_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    operating_company_id uuid NOT NULL,
    bank_account_id uuid NOT NULL,
    fit_id text NOT NULL,
    posted_at date NOT NULL,
    amount numeric(14,2) NOT NULL,
    transaction_type text,
    document_number text,
    memo text NOT NULL,
    reconciliation_status text DEFAULT 'pending_review'::text NOT NULL,
    match_source_type text,
    match_source_id uuid,
    match_document_number text,
    match_counterparty_name text,
    matched_amount numeric(14,2),
    difference_amount numeric(14,2),
    confidence_percent numeric(5,2),
    reconciled_by uuid,
    reconciled_by_name text,
    reconciled_at timestamp with time zone,
    resolution_notes text,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT bank_statement_transactions_amount_check CHECK ((amount <> (0)::numeric)),
    CONSTRAINT bank_statement_transactions_check CHECK ((((reconciliation_status = 'pending_review'::text) AND (match_source_type IS NULL) AND (match_source_id IS NULL) AND (reconciled_at IS NULL)) OR ((reconciliation_status = ANY (ARRAY['matched_auto'::text, 'matched_manual'::text])) AND (match_source_type IS NOT NULL) AND (match_source_id IS NOT NULL) AND (matched_amount IS NOT NULL) AND (difference_amount IS NOT NULL) AND (reconciled_at IS NOT NULL)) OR ((reconciliation_status = 'ignored'::text) AND (match_source_type IS NULL) AND (match_source_id IS NULL) AND (reconciled_at IS NOT NULL) AND (resolution_notes IS NOT NULL)))),
    CONSTRAINT bank_statement_transactions_confidence_percent_check CHECK (((confidence_percent IS NULL) OR ((confidence_percent >= (0)::numeric) AND (confidence_percent <= (100)::numeric)))),
    CONSTRAINT bank_statement_transactions_fit_id_check CHECK (((length(btrim(fit_id)) >= 1) AND (length(btrim(fit_id)) <= 150))),
    CONSTRAINT bank_statement_transactions_match_source_type_check CHECK (((match_source_type IS NULL) OR (match_source_type = ANY (ARRAY['measurement_receivable'::text, 'recurring_receivable'::text, 'manual_receivable'::text, 'supplier_payment'::text])))),
    CONSTRAINT bank_statement_transactions_memo_check CHECK (((length(btrim(memo)) >= 1) AND (length(btrim(memo)) <= 500))),
    CONSTRAINT bank_statement_transactions_reconciliation_status_check CHECK ((reconciliation_status = ANY (ARRAY['pending_review'::text, 'matched_auto'::text, 'matched_manual'::text, 'ignored'::text]))),
