--

CREATE TABLE apticket.contas_receber (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    medicao_id uuid,
    contrato_id uuid,
    company_id uuid NOT NULL,
    cliente_nome text NOT NULL,
    documento_referencia text NOT NULL,
    descricao text NOT NULL,
    competencia date NOT NULL,
    valor_original numeric(14,2) NOT NULL,
    valor_aberto numeric(14,2) NOT NULL,
    vencimento_em date NOT NULL,
    status_cobranca apticket.status_cobranca_avulsa DEFAULT 'a_faturar'::apticket.status_cobranca_avulsa NOT NULL,
    observacoes text,
    aprovado_em timestamp with time zone NOT NULL,
    aprovado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    billing_cycle_id uuid,
    operating_company_id uuid NOT NULL,
    origin_type text GENERATED ALWAYS AS (
CASE
    WHEN (medicao_id IS NOT NULL) THEN 'measurement'::text
    WHEN (billing_cycle_id IS NOT NULL) THEN 'recurring'::text
    ELSE 'manual'::text
END) STORED NOT NULL,
    document_type_id uuid,
    manual_entry_group_id uuid,
    installment_number smallint,
    installment_count smallint,
    document_base_number text,
    CONSTRAINT contas_receber_competencia_primeiro_dia_check CHECK ((competencia = (date_trunc('month'::text, (competencia)::timestamp with time zone))::date)),
    CONSTRAINT contas_receber_valor_aberto_check CHECK ((valor_aberto >= (0)::numeric)),
    CONSTRAINT contas_receber_valor_original_check CHECK ((valor_original >= (0)::numeric)),
    CONSTRAINT receivable_installment_metadata_check CHECK ((((manual_entry_group_id IS NULL) AND (installment_number IS NULL) AND (installment_count IS NULL) AND (document_base_number IS NULL)) OR ((manual_entry_group_id IS NOT NULL) AND ((installment_number >= 1) AND (installment_number <= installment_count)) AND ((installment_count >= 1) AND (installment_count <= 120)) AND ((length(btrim(document_base_number)) >= 2) AND (length(btrim(document_base_number)) <= 80)) AND (origin_type = 'manual'::text)))),
    CONSTRAINT receivable_origin_check CHECK ((((medicao_id IS NOT NULL) AND (billing_cycle_id IS NULL) AND (contrato_id IS NOT NULL)) OR ((medicao_id IS NULL) AND (billing_cycle_id IS NOT NULL) AND (contrato_id IS NOT NULL)) OR ((medicao_id IS NULL) AND (billing_cycle_id IS NULL) AND (contrato_id IS NULL))))
);


