    CONSTRAINT supplier_payments_bank_snapshot_check CHECK ((jsonb_typeof(bank_snapshot) = 'object'::text)),
    CONSTRAINT supplier_payments_cancellation_reason_check CHECK (((cancellation_reason IS NULL) OR ((length(btrim(cancellation_reason)) >= 3) AND (length(btrim(cancellation_reason)) <= 1000)))),
    CONSTRAINT supplier_payments_check CHECK ((((status = 'scheduled'::text) AND (paid_at IS NULL) AND (paid_amount IS NULL) AND (settled_by IS NULL) AND (reconciliation_status = 'pending'::text) AND (difference_amount IS NULL) AND (cancelled_at IS NULL)) OR ((status = 'paid'::text) AND (paid_at IS NOT NULL) AND (paid_amount IS NOT NULL) AND (settled_by IS NOT NULL) AND (settled_by_name IS NOT NULL) AND (reconciliation_status = ANY (ARRAY['matched'::text, 'difference'::text])) AND (difference_amount IS NOT NULL) AND (receipt_bucket = 'supplier-payment-receipts'::text) AND (receipt_path IS NOT NULL) AND (receipt_file_name IS NOT NULL) AND (receipt_mime_type IS NOT NULL) AND (receipt_size IS NOT NULL) AND (cancelled_at IS NULL)) OR ((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL) AND (cancelled_by IS NOT NULL) AND (cancelled_by_name IS NOT NULL) AND (cancellation_reason IS NOT NULL) AND (paid_at IS NULL)))),
    CONSTRAINT supplier_payments_paid_amount_check CHECK (((paid_amount IS NULL) OR (paid_amount > (0)::numeric))),
    CONSTRAINT supplier_payments_payment_method_check CHECK ((payment_method = ANY (ARRAY['pix'::text, 'bank_transfer'::text, 'boleto'::text, 'other'::text]))),
    CONSTRAINT supplier_payments_receipt_size_check CHECK (((receipt_size IS NULL) OR ((receipt_size >= 1) AND (receipt_size <= 10485760)))),
    CONSTRAINT supplier_payments_reconciliation_status_check CHECK ((reconciliation_status = ANY (ARRAY['pending'::text, 'matched'::text, 'difference'::text]))),
    CONSTRAINT supplier_payments_scheduled_amount_check CHECK ((scheduled_amount > (0)::numeric)),
    CONSTRAINT supplier_payments_scheduling_notes_check CHECK (((scheduling_notes IS NULL) OR ((length(btrim(scheduling_notes)) >= 1) AND (length(btrim(scheduling_notes)) <= 1000)))),
    CONSTRAINT supplier_payments_settlement_notes_check CHECK (((settlement_notes IS NULL) OR ((length(btrim(settlement_notes)) >= 1) AND (length(btrim(settlement_notes)) <= 1000)))),
    CONSTRAINT supplier_payments_status_check CHECK ((status = ANY (ARRAY['scheduled'::text, 'paid'::text, 'cancelled'::text]))),
    CONSTRAINT supplier_payments_transaction_reference_check CHECK (((transaction_reference IS NULL) OR ((length(btrim(transaction_reference)) >= 2) AND (length(btrim(transaction_reference)) <= 150))))
);


