--
-- Name: cash_flow_entries; Type: VIEW; Schema: apticket; Owner: supabase_admin
--

CREATE VIEW apticket.cash_flow_entries WITH (security_invoker='true') AS
 SELECT receivable.tenant_id,
    receivable.operating_company_id,
    'inflow'::text AS direction,
        CASE receivable.origin_type
            WHEN 'measurement'::text THEN 'measurement_receivable'::text
            WHEN 'manual'::text THEN 'manual_receivable'::text
            ELSE 'recurring_receivable'::text
        END AS source_type,
    receivable.id AS source_id,
    receivable.documento_referencia AS document_number,
    receivable.cliente_nome AS counterparty_name,
    receivable.descricao AS description,
    receivable.competencia AS competence,
    receivable.vencimento_em AS planned_date,
        CASE
            WHEN (receivable.valor_aberto < receivable.valor_original) THEN (receivable.updated_at)::date
            ELSE NULL::date
        END AS realized_date,
    receivable.valor_original AS planned_amount,
    receivable.valor_aberto AS open_amount,
    ((receivable.valor_original - receivable.valor_aberto))::numeric(14,2) AS realized_amount,
        CASE
            WHEN (receivable.status_cobranca = 'cancelado'::apticket.status_cobranca_avulsa) THEN 'cancelled'::text
            WHEN ((receivable.valor_aberto = (0)::numeric) OR (receivable.status_cobranca = 'recebido'::apticket.status_cobranca_avulsa)) THEN 'realized'::text
            WHEN (receivable.vencimento_em < CURRENT_DATE) THEN 'overdue'::text
            ELSE 'pending'::text
        END AS cash_status,
    (receivable.status_cobranca)::text AS source_status,
    NULL::text AS reconciliation_status,
    NULL::numeric(14,2) AS difference_amount,
    receivable.created_at,
    receivable.updated_at,
    classification.id AS classification_id,
    classification.financial_category_id,
    classification.financial_category_code,
    classification.financial_category_name,
    classification.cost_center_id,
    classification.cost_center_code,
    classification.cost_center_name
   FROM (apticket.contas_receber receivable
     LEFT JOIN apticket.financial_entry_classifications classification ON (((classification.source_id = receivable.id) AND (classification.source_type =
        CASE receivable.origin_type
            WHEN 'measurement'::text THEN 'measurement_receivable'::text
            WHEN 'manual'::text THEN 'manual_receivable'::text
            ELSE 'recurring_receivable'::text
        END) AND (classification.replaced_at IS NULL))))
  WHERE ((receivable.deleted_at IS NULL) AND (receivable.operating_company_id IS NOT NULL))
UNION ALL
 SELECT payable.tenant_id,
    payable.operating_company_id,
    'outflow'::text AS direction,
    'supplier_payable'::text AS source_type,
    payable.id AS source_id,
    payable.document_number,
    COALESCE((payable.terms_snapshot ->> 'supplier_name'::text), 'Fornecedor'::text) AS counterparty_name,
    payable.description,
    payable.cycle_start AS competence,
    COALESCE(payment.scheduled_date, payable.due_date) AS planned_date,
    (payment.paid_at)::date AS realized_date,
    payable.total_amount AS planned_amount,
    (
        CASE
            WHEN (payable.status = 'paid'::text) THEN (0)::numeric
            ELSE payable.total_amount
        END)::numeric(14,2) AS open_amount,
    (COALESCE(payment.paid_amount, (0)::numeric))::numeric(14,2) AS realized_amount,
        CASE
            WHEN (payable.status = 'cancelled'::text) THEN 'cancelled'::text
            WHEN (payable.status = 'paid'::text) THEN 'realized'::text
            WHEN (COALESCE(payment.scheduled_date, payable.due_date) < CURRENT_DATE) THEN 'overdue'::text
            ELSE 'pending'::text
        END AS cash_status,
    payable.status AS source_status,
    payment.reconciliation_status,
    payment.difference_amount,
    payable.created_at,
    GREATEST(payment.updated_at, payable.updated_at, payable.created_at) AS updated_at,
    classification.id AS classification_id,
    classification.financial_category_id,
    classification.financial_category_code,
    classification.financial_category_name,
    classification.cost_center_id,
    classification.cost_center_code,
    classification.cost_center_name
   FROM ((apticket.supplier_payables payable
     LEFT JOIN LATERAL ( SELECT candidate.scheduled_date,
            candidate.paid_at,
            candidate.paid_amount,
            candidate.reconciliation_status,
            candidate.difference_amount,
            candidate.updated_at
           FROM apticket.supplier_payments candidate
          WHERE ((candidate.supplier_payable_id = payable.id) AND (candidate.status = ANY (ARRAY['scheduled'::text, 'paid'::text])))
         LIMIT 1) payment ON (true))
     LEFT JOIN apticket.financial_entry_classifications classification ON (((classification.source_id = payable.id) AND (classification.source_type = 'supplier_payable'::text) AND (classification.replaced_at IS NULL))))
  WHERE (payable.deleted_at IS NULL);


ALTER VIEW apticket.cash_flow_entries OWNER TO supabase_admin;

--
-- Name: VIEW cash_flow_entries; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON VIEW apticket.cash_flow_entries IS 'Fluxo de caixa consolidado de recebiveis contratuais e pagamentos de fornecedores.';


--
-- Name: cash_flow_allocation_entries; Type: VIEW; Schema: apticket; Owner: supabase_admin
--

CREATE VIEW apticket.cash_flow_allocation_entries WITH (security_invoker='true') AS
 SELECT raw.tenant_id,
    raw.operating_company_id,
    raw.direction,
    raw.source_type,
    raw.source_id,
    raw.document_number,
    raw.counterparty_name,
    raw.description,
    raw.competence,
    raw.planned_date,
    raw.realized_date,
    (COALESCE(planned.amount, raw.planned_amount))::numeric(14,2) AS planned_amount,
    (COALESCE(opened.amount, raw.open_amount))::numeric(14,2) AS open_amount,
    (COALESCE(realized.amount, raw.realized_amount))::numeric(14,2) AS realized_amount,
    raw.cash_status,
    raw.source_status,
    raw.reconciliation_status,
    (
        CASE
            WHEN (raw.difference_amount IS NULL) THEN NULL::numeric
            ELSE COALESCE(difference.amount, raw.difference_amount)
        END)::numeric(14,2) AS difference_amount,
    raw.created_at,
    raw.updated_at,
    raw.classification_id,
    COALESCE(planned.category_id, raw.financial_category_id) AS financial_category_id,
    COALESCE(planned.category_code, raw.financial_category_code) AS financial_category_code,
    COALESCE(planned.category_name, raw.financial_category_name) AS financial_category_name,
    COALESCE(planned.center_id, raw.cost_center_id) AS cost_center_id,
    COALESCE(planned.center_code, raw.cost_center_code) AS cost_center_code,
    COALESCE(planned.center_name, raw.cost_center_name) AS cost_center_name,
    snapshot.category_allocations,
    snapshot.cost_center_allocations
   FROM (((((apticket.cash_flow_entries raw
     LEFT JOIN apticket.financial_entry_classifications snapshot ON ((snapshot.id = raw.classification_id)))
     LEFT JOIN LATERAL apticket.allocate_financial_amount(raw.planned_amount, snapshot.category_allocations, snapshot.cost_center_allocations) planned(category_id, category_code, category_name, center_id, center_code, center_name, amount) ON (true))
     LEFT JOIN LATERAL apticket.allocate_financial_amount(raw.open_amount, snapshot.category_allocations, snapshot.cost_center_allocations) opened(category_id, category_code, category_name, center_id, center_code, center_name, amount) ON (((opened.category_id = planned.category_id) AND (opened.center_id = planned.center_id))))
     LEFT JOIN LATERAL apticket.allocate_financial_amount(raw.realized_amount, snapshot.category_allocations, snapshot.cost_center_allocations) realized(category_id, category_code, category_name, center_id, center_code, center_name, amount) ON (((realized.category_id = planned.category_id) AND (realized.center_id = planned.center_id))))
     LEFT JOIN LATERAL apticket.allocate_financial_amount(raw.difference_amount, snapshot.category_allocations, snapshot.cost_center_allocations) difference(category_id, category_code, category_name, center_id, center_code, center_name, amount) ON (((difference.category_id = planned.category_id) AND (difference.center_id = planned.center_id))));


ALTER VIEW apticket.cash_flow_allocation_entries OWNER TO supabase_admin;

--
-- Name: VIEW cash_flow_allocation_entries; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON VIEW apticket.cash_flow_allocation_entries IS 'Rateios contábeis por categoria e centro. source_id pode repetir; cash_flow_entries mantém um registro por documento.';


