--
-- Name: contract_mrr_projection; Type: VIEW; Schema: apticket; Owner: supabase_admin
--

CREATE VIEW apticket.contract_mrr_projection WITH (security_invoker='true') AS
 SELECT terms.tenant_id,
    terms.operating_company_id,
    operator.legal_name AS operating_company_name,
    terms.contract_id,
    contract.company_id AS customer_id,
    company.name AS customer_name,
    contract.numero_contrato AS contract_number,
    month.period_month,
    (round((value.base_amount / (terms.billing_interval_months)::numeric), 2))::numeric(14,2) AS baseline_mrr,
    terms.billing_interval_months,
    contract.ends_at,
        CASE
            WHEN (value.id IS NULL) THEN true
            ELSE false
        END AS missing_value_version
   FROM (((((apticket.contract_financial_terms terms
     JOIN apticket.contracts contract ON (((contract.id = terms.contract_id) AND (contract.tenant_id = terms.tenant_id))))
     JOIN apticket.companies company ON (((company.id = contract.company_id) AND (company.tenant_id = contract.tenant_id))))
     JOIN apticket.operating_companies operator ON (((operator.id = terms.operating_company_id) AND (operator.tenant_id = terms.tenant_id))))
     CROSS JOIN LATERAL ( SELECT (generate_series(((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone))::date)::timestamp with time zone, (((date_trunc('month'::text, (CURRENT_DATE)::timestamp with time zone) + '11 mons'::interval))::date)::timestamp with time zone, '1 mon'::interval))::date AS period_month) month)
     LEFT JOIN LATERAL ( SELECT version.id,
            version.base_amount
           FROM apticket.contract_value_versions version
          WHERE ((version.contract_id = terms.contract_id) AND (version.tenant_id = terms.tenant_id) AND (version.operating_company_id = terms.operating_company_id) AND (version.deleted_at IS NULL) AND (version.effective_from <= month.period_month))
          ORDER BY version.effective_from DESC
         LIMIT 1) value ON (true))
  WHERE ((terms.deleted_at IS NULL) AND terms.billing_enabled AND (contract.status = 'active'::apticket.contract_status) AND (contract.starts_at < ((month.period_month + '1 mon'::interval))::date) AND (contract.ends_at >= month.period_month));


ALTER VIEW apticket.contract_mrr_projection OWNER TO supabase_admin;

--
-- Name: VIEW contract_mrr_projection; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON VIEW apticket.contract_mrr_projection IS 'MRR contratual normalizado para os proximos doze meses, antes de cenarios de estresse.';


