    CONSTRAINT supplier_payable_allocations_contract_number_check CHECK (((length(btrim(contract_number)) >= 1) AND (length(btrim(contract_number)) <= 80))),
    CONSTRAINT supplier_payable_allocations_customer_name_check CHECK (((length(btrim(customer_name)) >= 1) AND (length(btrim(customer_name)) <= 250))),
    CONSTRAINT supplier_payable_allocations_metric_check CHECK ((metric = ANY (ARRAY['active_users'::text, 'devices'::text]))),
