--
-- Name: contract_profitability; Type: VIEW; Schema: apticket; Owner: supabase_admin
--

CREATE VIEW apticket.contract_profitability WITH (security_invoker='true') AS
 WITH revenue AS (
         SELECT receivable.tenant_id,
            receivable.operating_company_id,
            receivable.contrato_id AS contract_id,
            (date_trunc('month'::text, (receivable.competencia)::timestamp with time zone))::date AS period_month,
            (sum(receivable.valor_original))::numeric(14,2) AS gross_revenue,
            (sum((receivable.valor_original - receivable.valor_aberto)))::numeric(14,2) AS realized_revenue
           FROM apticket.contas_receber receivable
          WHERE ((receivable.deleted_at IS NULL) AND (receivable.operating_company_id IS NOT NULL) AND (receivable.status_cobranca <> 'cancelado'::apticket.status_cobranca_avulsa))
          GROUP BY receivable.tenant_id, receivable.operating_company_id, receivable.contrato_id, ((date_trunc('month'::text, (receivable.competencia)::timestamp with time zone))::date)
        ), allocated_cost AS (
         SELECT allocation.tenant_id,
            allocation.operating_company_id,
            allocation.customer_contract_id AS contract_id,
            (date_trunc('month'::text, (payable.cycle_start)::timestamp with time zone))::date AS period_month,
            (sum(allocation.amount))::numeric(14,2) AS allocated_cost
           FROM (apticket.supplier_payable_allocations allocation
             JOIN apticket.supplier_payables payable ON (((payable.id = allocation.supplier_payable_id) AND (payable.tenant_id = allocation.tenant_id) AND (payable.operating_company_id = allocation.operating_company_id))))
          WHERE ((allocation.deleted_at IS NULL) AND (payable.deleted_at IS NULL) AND (payable.status <> 'cancelled'::text))
          GROUP BY allocation.tenant_id, allocation.operating_company_id, allocation.customer_contract_id, ((date_trunc('month'::text, (payable.cycle_start)::timestamp with time zone))::date)
        ), keys AS (
         SELECT revenue_1.tenant_id,
            revenue_1.operating_company_id,
            revenue_1.contract_id,
            revenue_1.period_month
           FROM revenue revenue_1
        UNION
         SELECT allocated_cost_1.tenant_id,
            allocated_cost_1.operating_company_id,
            allocated_cost_1.contract_id,
            allocated_cost_1.period_month
           FROM allocated_cost allocated_cost_1
        )
 SELECT keys.tenant_id,
    keys.operating_company_id,
    operator.legal_name AS operating_company_name,
    keys.contract_id,
    contract.company_id AS customer_id,
    company.name AS customer_name,
    contract.numero_contrato AS contract_number,
    keys.period_month,
    (COALESCE(revenue.gross_revenue, (0)::numeric))::numeric(14,2) AS gross_revenue,
    (COALESCE(revenue.realized_revenue, (0)::numeric))::numeric(14,2) AS realized_revenue,
    (COALESCE(allocated_cost.allocated_cost, (0)::numeric))::numeric(14,2) AS allocated_cost,
    ((COALESCE(revenue.gross_revenue, (0)::numeric) - COALESCE(allocated_cost.allocated_cost, (0)::numeric)))::numeric(14,2) AS gross_profit,
        CASE
            WHEN (COALESCE(revenue.gross_revenue, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE round((((COALESCE(revenue.gross_revenue, (0)::numeric) - COALESCE(allocated_cost.allocated_cost, (0)::numeric)) / revenue.gross_revenue) * (100)::numeric), 2)
        END AS gross_margin_percent
   FROM (((((keys
     JOIN apticket.contracts contract ON (((contract.id = keys.contract_id) AND (contract.tenant_id = keys.tenant_id))))
     JOIN apticket.companies company ON (((company.id = contract.company_id) AND (company.tenant_id = contract.tenant_id))))
     JOIN apticket.operating_companies operator ON (((operator.id = keys.operating_company_id) AND (operator.tenant_id = keys.tenant_id))))
     LEFT JOIN revenue ON (((revenue.tenant_id = keys.tenant_id) AND (revenue.operating_company_id = keys.operating_company_id) AND (revenue.contract_id = keys.contract_id) AND (revenue.period_month = keys.period_month))))
     LEFT JOIN allocated_cost ON (((allocated_cost.tenant_id = keys.tenant_id) AND (allocated_cost.operating_company_id = keys.operating_company_id) AND (allocated_cost.contract_id = keys.contract_id) AND (allocated_cost.period_month = keys.period_month))));


ALTER VIEW apticket.contract_profitability OWNER TO supabase_admin;

