--
-- Name: financial_budget_variance; Type: VIEW; Schema: apticket; Owner: supabase_admin
--

CREATE VIEW apticket.financial_budget_variance WITH (security_invoker='true') AS
 WITH budget AS (
         SELECT financial_budget_entries.tenant_id,
            financial_budget_entries.operating_company_id,
            financial_budget_entries.period_month,
            financial_budget_entries.direction,
            financial_budget_entries.financial_category_id,
            financial_budget_entries.financial_category_code,
            financial_budget_entries.financial_category_name,
            financial_budget_entries.cost_center_id,
            financial_budget_entries.cost_center_code,
            financial_budget_entries.cost_center_name,
            financial_budget_entries.id AS budget_entry_id,
            financial_budget_entries.budgeted_amount,
            financial_budget_entries.revision,
            financial_budget_entries.created_by_name,
            financial_budget_entries.created_at
           FROM apticket.financial_budget_entries
          WHERE (financial_budget_entries.replaced_at IS NULL)
        ), planned AS (
         SELECT cash_flow_allocation_entries.tenant_id,
            cash_flow_allocation_entries.operating_company_id,
            (date_trunc('month'::text, (cash_flow_allocation_entries.planned_date)::timestamp with time zone))::date AS period_month,
            cash_flow_allocation_entries.direction,
            cash_flow_allocation_entries.financial_category_id,
            max(cash_flow_allocation_entries.financial_category_code) AS financial_category_code,
            max(cash_flow_allocation_entries.financial_category_name) AS financial_category_name,
            cash_flow_allocation_entries.cost_center_id,
            max(cash_flow_allocation_entries.cost_center_code) AS cost_center_code,
            max(cash_flow_allocation_entries.cost_center_name) AS cost_center_name,
            (sum(cash_flow_allocation_entries.planned_amount))::numeric(14,2) AS planned_amount
           FROM apticket.cash_flow_allocation_entries
          WHERE (cash_flow_allocation_entries.cash_status <> 'cancelled'::text)
          GROUP BY cash_flow_allocation_entries.tenant_id, cash_flow_allocation_entries.operating_company_id, ((date_trunc('month'::text, (cash_flow_allocation_entries.planned_date)::timestamp with time zone))::date), cash_flow_allocation_entries.direction, cash_flow_allocation_entries.financial_category_id, cash_flow_allocation_entries.cost_center_id
        ), realized AS (
         SELECT cash_flow_allocation_entries.tenant_id,
            cash_flow_allocation_entries.operating_company_id,
            (date_trunc('month'::text, (cash_flow_allocation_entries.realized_date)::timestamp with time zone))::date AS period_month,
            cash_flow_allocation_entries.direction,
            cash_flow_allocation_entries.financial_category_id,
            max(cash_flow_allocation_entries.financial_category_code) AS financial_category_code,
            max(cash_flow_allocation_entries.financial_category_name) AS financial_category_name,
            cash_flow_allocation_entries.cost_center_id,
            max(cash_flow_allocation_entries.cost_center_code) AS cost_center_code,
            max(cash_flow_allocation_entries.cost_center_name) AS cost_center_name,
            (sum(cash_flow_allocation_entries.realized_amount))::numeric(14,2) AS realized_amount
           FROM apticket.cash_flow_allocation_entries
          WHERE ((cash_flow_allocation_entries.realized_date IS NOT NULL) AND (cash_flow_allocation_entries.realized_amount <> (0)::numeric) AND (cash_flow_allocation_entries.cash_status <> 'cancelled'::text))
          GROUP BY cash_flow_allocation_entries.tenant_id, cash_flow_allocation_entries.operating_company_id, ((date_trunc('month'::text, (cash_flow_allocation_entries.realized_date)::timestamp with time zone))::date), cash_flow_allocation_entries.direction, cash_flow_allocation_entries.financial_category_id, cash_flow_allocation_entries.cost_center_id
        ), keys AS (
         SELECT budget_1.tenant_id,
            budget_1.operating_company_id,
            budget_1.period_month,
            budget_1.direction,
            budget_1.financial_category_id,
            budget_1.cost_center_id
           FROM budget budget_1
        UNION
         SELECT planned_1.tenant_id,
            planned_1.operating_company_id,
            planned_1.period_month,
            planned_1.direction,
            planned_1.financial_category_id,
            planned_1.cost_center_id
           FROM planned planned_1
        UNION
         SELECT realized_1.tenant_id,
            realized_1.operating_company_id,
            realized_1.period_month,
            realized_1.direction,
            realized_1.financial_category_id,
            realized_1.cost_center_id
           FROM realized realized_1
        )
 SELECT keys.tenant_id,
    keys.operating_company_id,
    keys.period_month,
    keys.direction,
    keys.financial_category_id,
    COALESCE(budget.financial_category_code, planned.financial_category_code, realized.financial_category_code) AS financial_category_code,
    COALESCE(budget.financial_category_name, planned.financial_category_name, realized.financial_category_name) AS financial_category_name,
    keys.cost_center_id,
    COALESCE(budget.cost_center_code, planned.cost_center_code, realized.cost_center_code) AS cost_center_code,
    COALESCE(budget.cost_center_name, planned.cost_center_name, realized.cost_center_name) AS cost_center_name,
    budget.budget_entry_id,
    (COALESCE(budget.budgeted_amount, (0)::numeric))::numeric(14,2) AS budgeted_amount,
    (COALESCE(planned.planned_amount, (0)::numeric))::numeric(14,2) AS planned_amount,
    (COALESCE(realized.realized_amount, (0)::numeric))::numeric(14,2) AS realized_amount,
    ((COALESCE(realized.realized_amount, (0)::numeric) - COALESCE(budget.budgeted_amount, (0)::numeric)))::numeric(14,2) AS variance_amount,
        CASE
            WHEN (COALESCE(budget.budgeted_amount, (0)::numeric) = (0)::numeric) THEN NULL::numeric
            ELSE round((((COALESCE(realized.realized_amount, (0)::numeric) - budget.budgeted_amount) / budget.budgeted_amount) * (100)::numeric), 2)
        END AS variance_percent,
    budget.revision,
    budget.created_by_name,
    budget.created_at
   FROM (((keys
     LEFT JOIN budget ON (((budget.tenant_id = keys.tenant_id) AND (budget.operating_company_id = keys.operating_company_id) AND (budget.period_month = keys.period_month) AND (budget.direction = keys.direction) AND (NOT (budget.financial_category_id IS DISTINCT FROM keys.financial_category_id)) AND (NOT (budget.cost_center_id IS DISTINCT FROM keys.cost_center_id)))))
     LEFT JOIN planned ON (((planned.tenant_id = keys.tenant_id) AND (planned.operating_company_id = keys.operating_company_id) AND (planned.period_month = keys.period_month) AND (planned.direction = keys.direction) AND (NOT (planned.financial_category_id IS DISTINCT FROM keys.financial_category_id)) AND (NOT (planned.cost_center_id IS DISTINCT FROM keys.cost_center_id)))))
     LEFT JOIN realized ON (((realized.tenant_id = keys.tenant_id) AND (realized.operating_company_id = keys.operating_company_id) AND (realized.period_month = keys.period_month) AND (realized.direction = keys.direction) AND (NOT (realized.financial_category_id IS DISTINCT FROM keys.financial_category_id)) AND (NOT (realized.cost_center_id IS DISTINCT FROM keys.cost_center_id)))));


ALTER VIEW apticket.financial_budget_variance OWNER TO supabase_admin;

--
-- Name: VIEW financial_budget_variance; Type: COMMENT; Schema: apticket; Owner: supabase_admin
--

COMMENT ON VIEW apticket.financial_budget_variance IS 'Comparativo mensal entre orcado, previsto e realizado, respeitando o escopo financeiro.';


