    aggregate_id uuid NOT NULL,
    event_type text NOT NULL,
    source_id uuid NOT NULL,
    payload jsonb NOT NULL,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt_count smallint DEFAULT 0 NOT NULL,
    last_error text,
    occurred_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    processed_at timestamp with time zone,
    next_attempt_at timestamp with time zone DEFAULT clock_timestamp(),
    CONSTRAINT financial_domain_events_aggregate_type_check CHECK ((aggregate_type = 'contract'::text)),
    CONSTRAINT financial_domain_events_attempt_count_check CHECK (((attempt_count >= 0) AND (attempt_count <= 20))),
    CONSTRAINT financial_domain_events_event_type_check CHECK ((event_type = ANY (ARRAY['contract.suspended_for_delinquency'::text, 'contract.financial_suspension_released'::text]))),
    CONSTRAINT financial_domain_events_payload_check CHECK ((jsonb_typeof(payload) = 'object'::text)),
    CONSTRAINT financial_domain_events_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'processing'::text, 'processed'::text, 'failed'::text, 'cancelled'::text])))
);


