    CONSTRAINT financial_period_closures_close_notes_check CHECK (((close_notes IS NULL) OR ((length(btrim(close_notes)) >= 1) AND (length(btrim(close_notes)) <= 1000)))),
    CONSTRAINT financial_period_closures_period_month_check CHECK ((period_month = (date_trunc('month'::text, (period_month)::timestamp with time zone))::date)),
    CONSTRAINT financial_period_closures_revision_check CHECK ((revision > 0)),
    CONSTRAINT financial_period_closures_snapshot_line_count_check CHECK ((snapshot_line_count >= 0)),
