--
-- Name: financial_management_statement; Type: VIEW; Schema: apticket; Owner: supabase_admin
--

CREATE VIEW apticket.financial_management_statement WITH (security_invoker='true') AS
 WITH current_lines AS (
         SELECT variance.tenant_id,
            variance.operating_company_id,
            variance.period_month,
            variance.direction,
            variance.financial_category_id,
            variance.financial_category_code,
            variance.financial_category_name,
            variance.cost_center_id,
            variance.cost_center_code,
            variance.cost_center_name,
            variance.budget_entry_id,
            variance.budgeted_amount,
            variance.planned_amount,
            variance.realized_amount,
            (
                CASE
                    WHEN (variance.direction = 'inflow'::text) THEN (variance.realized_amount - variance.budgeted_amount)
                    ELSE (variance.budgeted_amount - variance.realized_amount)
                END)::numeric(14,2) AS favorable_variance_amount,
                CASE
                    WHEN (variance.budgeted_amount = (0)::numeric) THEN NULL::numeric
                    WHEN (variance.direction = 'inflow'::text) THEN round((((variance.realized_amount - variance.budgeted_amount) / variance.budgeted_amount) * (100)::numeric), 2)
                    ELSE round((((variance.budgeted_amount - variance.realized_amount) / variance.budgeted_amount) * (100)::numeric), 2)
                END AS favorable_variance_percent,
            variance.revision,
            variance.created_by_name,
            variance.created_at,
            NULL::uuid AS period_closure_id,
            NULL::timestamp with time zone AS period_closed_at
           FROM apticket.financial_budget_variance variance
          WHERE (NOT (EXISTS ( SELECT 1
                   FROM apticket.financial_period_closures closure
                  WHERE ((closure.tenant_id = variance.tenant_id) AND (closure.operating_company_id = variance.operating_company_id) AND (closure.period_month = variance.period_month) AND (closure.status = 'closed'::text)))))
        ), closed_lines AS (
         SELECT line.tenant_id,
            line.operating_company_id,
            line.period_month,
            line.direction,
            line.financial_category_id,
            line.financial_category_code,
            line.financial_category_name,
            line.cost_center_id,
            line.cost_center_code,
            line.cost_center_name,
            line.budget_entry_id,
            line.budgeted_amount,
            line.planned_amount,
            line.realized_amount,
            line.favorable_variance_amount,
            line.favorable_variance_percent,
            line.budget_revision AS revision,
            line.budget_created_by_name AS created_by_name,
            line.budget_created_at AS created_at,
            closure.id AS period_closure_id,
            closure.closed_at AS period_closed_at
           FROM (apticket.financial_period_snapshot_lines line
             JOIN apticket.financial_period_closures closure ON (((closure.id = line.closure_id) AND (closure.tenant_id = line.tenant_id) AND (closure.operating_company_id = line.operating_company_id) AND (closure.status = 'closed'::text))))
        ), lines AS (
         SELECT current_lines.tenant_id,
            current_lines.operating_company_id,
            current_lines.period_month,
            current_lines.direction,
            current_lines.financial_category_id,
            current_lines.financial_category_code,
            current_lines.financial_category_name,
            current_lines.cost_center_id,
            current_lines.cost_center_code,
            current_lines.cost_center_name,
            current_lines.budget_entry_id,
            current_lines.budgeted_amount,
            current_lines.planned_amount,
            current_lines.realized_amount,
            current_lines.favorable_variance_amount,
            current_lines.favorable_variance_percent,
            current_lines.revision,
            current_lines.created_by_name,
            current_lines.created_at,
            current_lines.period_closure_id,
            current_lines.period_closed_at
           FROM current_lines
        UNION ALL
         SELECT closed_lines.tenant_id,
            closed_lines.operating_company_id,
            closed_lines.period_month,
            closed_lines.direction,
            closed_lines.financial_category_id,
            closed_lines.financial_category_code,
            closed_lines.financial_category_name,
            closed_lines.cost_center_id,
            closed_lines.cost_center_code,
            closed_lines.cost_center_name,
            closed_lines.budget_entry_id,
            closed_lines.budgeted_amount,
            closed_lines.planned_amount,
            closed_lines.realized_amount,
            closed_lines.favorable_variance_amount,
            closed_lines.favorable_variance_percent,
            closed_lines.revision,
            closed_lines.created_by_name,
            closed_lines.created_at,
            closed_lines.period_closure_id,
            closed_lines.period_closed_at
           FROM closed_lines
        )
 SELECT tenant_id,
    operating_company_id,
    (EXTRACT(year FROM period_month))::integer AS fiscal_year,
    (EXTRACT(month FROM period_month))::integer AS fiscal_month,
    period_month,
        CASE
            WHEN (direction = 'inflow'::text) THEN 'revenue'::text
            ELSE 'expense'::text
        END AS result_group,
    direction,
    financial_category_id,
    financial_category_code,
    financial_category_name,
    cost_center_id,
    cost_center_code,
    cost_center_name,
    budget_entry_id,
    budgeted_amount,
    planned_amount,
    realized_amount,
    (
        CASE
            WHEN (direction = 'inflow'::text) THEN budgeted_amount
            ELSE (- budgeted_amount)
        END)::numeric(14,2) AS budgeted_result_amount,
    (
        CASE
            WHEN (direction = 'inflow'::text) THEN planned_amount
            ELSE (- planned_amount)
        END)::numeric(14,2) AS planned_result_amount,
    (
        CASE
            WHEN (direction = 'inflow'::text) THEN realized_amount
            ELSE (- realized_amount)
        END)::numeric(14,2) AS realized_result_amount,
    favorable_variance_amount,
    favorable_variance_percent,
    revision,
    created_by_name,
    created_at,
    period_closure_id,
    period_closed_at
   FROM lines;


ALTER VIEW apticket.financial_management_statement OWNER TO supabase_admin;

