    CONSTRAINT inter_payer_snapshots_payer_email_check CHECK (((payer_email IS NULL) OR ((length(payer_email) >= 3) AND (length(payer_email) <= 100)))),
    CONSTRAINT inter_payer_snapshots_payer_name_check CHECK (((length(btrim(payer_name)) >= 1) AND (length(btrim(payer_name)) <= 100))),
    CONSTRAINT inter_payer_snapshots_payer_number_check CHECK (((length(btrim(payer_number)) >= 1) AND (length(btrim(payer_number)) <= 20))),
