    CONSTRAINT inter_payer_snapshots_payer_zip_check CHECK ((payer_zip ~ '^[0-9]{8}$'::text)),
    CONSTRAINT inter_payer_snapshots_seu_numero_check CHECK ((seu_numero ~ '^[A-Z0-9]{1,15}$'::text)),
