    CONSTRAINT inter_webhook_registration_attempts_candidate_secret_hash_check CHECK ((candidate_secret_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT inter_webhook_registration_attempts_check CHECK ((((status = 'claimed'::text) AND (finished_at IS NULL)) OR ((status <> 'claimed'::text) AND (finished_at IS NOT NULL)))),
    CONSTRAINT inter_webhook_registration_attempts_configuration_version_check CHECK ((configuration_version > 0)),
    CONSTRAINT inter_webhook_registration_attempts_environment_check CHECK ((environment = ANY (ARRAY['sandbox'::text, 'production'::text]))),
    CONSTRAINT inter_webhook_registration_attempts_error_code_check CHECK (((error_code IS NULL) OR (length(error_code) <= 60))),
    CONSTRAINT inter_webhook_registration_attempts_error_message_check CHECK (((error_message IS NULL) OR (length(error_message) <= 300))),
    CONSTRAINT inter_webhook_registration_attempts_http_status_check CHECK (((http_status IS NULL) OR ((http_status >= 100) AND (http_status <= 599)))),
    CONSTRAINT inter_webhook_registration_attempts_status_check CHECK ((status = ANY (ARRAY['claimed'::text, 'registered'::text, 'failed'::text])))
);


