    CONSTRAINT supplier_contract_number_format_check CHECK (((numero_contrato IS NULL) OR (numero_contrato ~ '^[0-9]{6}/[0-9]{4}$'::text))),
    CONSTRAINT supplier_contract_price_check CHECK ((((billing_unit = 'fixed'::text) AND (base_amount > (0)::numeric) AND (unit_price = (0)::numeric)) OR ((billing_unit <> 'fixed'::text) AND (unit_price > (0)::numeric)))),
    CONSTRAINT supplier_contract_status_check CHECK ((status = ANY (ARRAY['active'::text, 'suspended'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT supplier_contracts_base_amount_check CHECK ((base_amount >= (0)::numeric)),
    CONSTRAINT supplier_contracts_billing_interval_months_check CHECK ((billing_interval_months = ANY (ARRAY[1, 3, 6, 12]))),
    CONSTRAINT supplier_contracts_billing_unit_check CHECK ((billing_unit = ANY (ARRAY['fixed'::text, 'active_users'::text, 'devices'::text]))),
    CONSTRAINT supplier_contracts_description_check CHECK (((length(btrim(description)) >= 2) AND (length(btrim(description)) <= 250))),
    CONSTRAINT supplier_contracts_due_day_check CHECK (((due_day >= 1) AND (due_day <= 31))),
    CONSTRAINT supplier_contracts_financial_dimensions_pair_check CHECK (((financial_category_id IS NULL) = (cost_center_id IS NULL))),
    CONSTRAINT supplier_contracts_notes_check CHECK (((notes IS NULL) OR (length(notes) <= 4000))),
    CONSTRAINT supplier_contracts_unit_price_check CHECK ((unit_price >= (0)::numeric))
);


