--
-- Name: tickets; Type: TABLE; Schema: apticket; Owner: postgres
--

CREATE TABLE apticket.tickets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    tenant_id uuid NOT NULL,
    number bigint NOT NULL,
    subject text NOT NULL,
    status apticket.ticket_status DEFAULT 'new'::apticket.ticket_status NOT NULL,
    priority apticket.ticket_priority DEFAULT 'medium'::apticket.ticket_priority NOT NULL,
    channel apticket.ticket_channel DEFAULT 'manual'::apticket.ticket_channel NOT NULL,
    department_id uuid,
    assigned_to uuid,
    contact_id uuid,
    company_id uuid,
    contract_id uuid,
    sla_policy_id uuid,
    sla_first_response_due_at timestamp with time zone,
    sla_resolution_due_at timestamp with time zone,
    sla_breached boolean DEFAULT false NOT NULL,
    first_responded_at timestamp with time zone,
    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    equipment_id uuid,
    pending_type text,
    resolution_summary text,
    resolution_diagnosis text,
    sla_paused_at timestamp with time zone,
    total_sla_paused_seconds bigint DEFAULT 0 NOT NULL,
    tipo_atendimento apticket.tipo_atendimento DEFAULT 'contratual'::apticket.tipo_atendimento NOT NULL,
    motivo_avulso apticket.motivo_avulso,
    CONSTRAINT tickets_motivo_avulso_consistente CHECK ((((tipo_atendimento = 'contratual'::apticket.tipo_atendimento) AND (motivo_avulso IS NULL)) OR ((tipo_atendimento = 'avulso'::apticket.tipo_atendimento) AND (motivo_avulso IS NOT NULL)))),
    CONSTRAINT tickets_pending_type_check CHECK (((pending_type IS NULL) OR (pending_type = ANY (ARRAY['awaiting_tech'::text, 'awaiting_customer'::text, 'tech_response'::text, 'in_progress'::text])))),
    CONSTRAINT tickets_resolution_required_check CHECK (((status <> ALL (ARRAY['resolved'::apticket.ticket_status, 'closed'::apticket.ticket_status])) OR ((resolution_summary IS NOT NULL) AND (btrim(resolution_summary) <> ''::text) AND (resolution_diagnosis IS NOT NULL) AND (btrim(resolution_diagnosis) <> ''::text))))
);


ALTER TABLE apticket.tickets OWNER TO postgres;

--
-- Name: tickets_cobranca_avulsa; Type: TABLE; Schema: apticket; Owner: postgres
--

CREATE TABLE apticket.tickets_cobranca_avulsa (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    tabela_preco_id uuid,
    limite_valor_fixo_minutos integer DEFAULT 90 NOT NULL,
    valor_fixo_snapshot numeric(12,2) DEFAULT 0 NOT NULL,
    valor_hora_snapshot numeric(12,2) DEFAULT 0 NOT NULL,
    minutos_apurados integer DEFAULT 0 NOT NULL,
    valor_base numeric(12,2) DEFAULT 0 NOT NULL,
    valor_final numeric(12,2) DEFAULT 0 NOT NULL,
    valor_ajustado_manualmente boolean DEFAULT false NOT NULL,
    justificativa_ajuste text,
    status_cobranca apticket.status_cobranca_avulsa DEFAULT 'a_faturar'::apticket.status_cobranca_avulsa NOT NULL,
    vencimento_em date,
    observacoes text,
    revisado_em timestamp with time zone,
    revisado_por uuid,
    criado_por uuid,
    atualizado_por uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    CONSTRAINT cobranca_avulsa_ajuste_justificado CHECK (((NOT valor_ajustado_manualmente) OR (NULLIF(TRIM(BOTH FROM COALESCE(justificativa_ajuste, ''::text)), ''::text) IS NOT NULL))),
    CONSTRAINT tickets_cobranca_avulsa_minutos_apurados_check CHECK ((minutos_apurados >= 0)),
    CONSTRAINT tickets_cobranca_avulsa_valor_base_check CHECK ((valor_base >= (0)::numeric)),
    CONSTRAINT tickets_cobranca_avulsa_valor_final_check CHECK ((valor_final >= (0)::numeric))
);


ALTER TABLE apticket.tickets_cobranca_avulsa OWNER TO postgres;

