--
-- Name: profiles admin deletes profile; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY "admin deletes profile" ON apticket.profiles FOR DELETE TO authenticated USING ((apticket.has_permission(auth.uid(), 'usuarios'::text, 'delete'::text) AND (tenant_id = apticket.current_tenant_id())));


--
-- Name: profiles admin inserts profile; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY "admin inserts profile" ON apticket.profiles FOR INSERT TO authenticated WITH CHECK ((apticket.has_permission(auth.uid(), 'usuarios'::text, 'create'::text) AND (tenant_id = apticket.current_tenant_id())));


--
-- Name: user_roles admin manages roles; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY "admin manages roles" ON apticket.user_roles TO authenticated USING (((tenant_id = apticket.current_tenant_id()) AND (user_id <> ( SELECT auth.uid() AS uid)) AND apticket.has_permission(auth.uid(), 'usuarios'::text, 'edit'::text) AND (NOT (EXISTS ( SELECT 1
   FROM (apticket.role_permissions rp
     JOIN apticket.permissions p ON ((p.id = rp.permission_id)))
  WHERE ((rp.role_id = user_roles.role_id) AND (NOT apticket.has_permission(auth.uid(), p.module, p.action)))))))) WITH CHECK (((tenant_id = apticket.current_tenant_id()) AND (user_id <> ( SELECT auth.uid() AS uid)) AND apticket.has_permission(auth.uid(), 'usuarios'::text, 'edit'::text) AND (NOT (EXISTS ( SELECT 1
   FROM (apticket.role_permissions rp
     JOIN apticket.permissions p ON ((p.id = rp.permission_id)))
  WHERE ((rp.role_id = user_roles.role_id) AND (NOT apticket.has_permission(auth.uid(), p.module, p.action))))))));


--
-- Name: tenants admins update tenant; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY "admins update tenant" ON apticket.tenants FOR UPDATE TO authenticated USING (((id = apticket.current_tenant_id()) AND apticket.has_permission(auth.uid(), 'empresa'::text, 'edit'::text))) WITH CHECK ((id = apticket.current_tenant_id()));


