--
-- Name: contracts financial_contract_analytics_read; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY financial_contract_analytics_read ON apticket.contracts FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM apticket.contract_financial_terms terms
  WHERE ((terms.contract_id = contracts.id) AND (terms.tenant_id = contracts.tenant_id) AND (terms.deleted_at IS NULL) AND apticket.has_financial_scope(terms.tenant_id, terms.operating_company_id)))));


--
-- Name: financial_cost_centers; Type: ROW SECURITY; Schema: apticket; Owner: supabase_admin
--

ALTER TABLE apticket.financial_cost_centers ENABLE ROW LEVEL SECURITY;

--
-- Name: companies financial_customer_analytics_read; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY financial_customer_analytics_read ON apticket.companies FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM (apticket.contracts contract
     JOIN apticket.contract_financial_terms terms ON (((terms.contract_id = contract.id) AND (terms.tenant_id = contract.tenant_id) AND (terms.deleted_at IS NULL))))
  WHERE ((contract.company_id = companies.id) AND (contract.tenant_id = companies.tenant_id) AND apticket.has_financial_scope(terms.tenant_id, terms.operating_company_id)))));


