--
-- Name: role_permissions role_permissions manage; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY "role_permissions manage" ON apticket.role_permissions TO authenticated USING (((EXISTS ( SELECT 1
   FROM apticket.roles r
  WHERE ((r.id = role_permissions.role_id) AND (r.tenant_id = apticket.current_tenant_id())))) AND apticket.has_permission(auth.uid(), 'papeis'::text, 'edit'::text) AND (EXISTS ( SELECT 1
   FROM apticket.permissions p
  WHERE ((p.id = role_permissions.permission_id) AND apticket.has_permission(auth.uid(), p.module, p.action)))))) WITH CHECK (((EXISTS ( SELECT 1
   FROM apticket.roles r
  WHERE ((r.id = role_permissions.role_id) AND (r.tenant_id = apticket.current_tenant_id())))) AND apticket.has_permission(auth.uid(), 'papeis'::text, 'edit'::text) AND (EXISTS ( SELECT 1
   FROM apticket.permissions p
  WHERE ((p.id = role_permissions.permission_id) AND apticket.has_permission(auth.uid(), p.module, p.action))))));


--
-- Name: role_permissions role_permissions read tenant; Type: POLICY; Schema: apticket; Owner: postgres
--

CREATE POLICY "role_permissions read tenant" ON apticket.role_permissions FOR SELECT TO authenticated USING ((EXISTS ( SELECT 1
   FROM apticket.roles r
  WHERE ((r.id = role_permissions.role_id) AND (r.tenant_id = apticket.current_tenant_id())))));


