   FROM apticket.permissions p
  WHERE ((p.id = user_permissions.permission_id) AND apticket.has_permission(auth.uid(), p.module, p.action)))))) WITH CHECK (((tenant_id = apticket.current_tenant_id()) AND (user_id <> ( SELECT auth.uid() AS uid)) AND (created_by = ( SELECT auth.uid() AS uid)) AND apticket.has_permission(auth.uid(), 'permissoes'::text, 'edit'::text) AND (EXISTS ( SELECT 1
   FROM apticket.permissions p
  WHERE ((p.id = user_permissions.permission_id) AND apticket.has_permission(auth.uid(), p.module, p.action))))));


