CREATE POLICY supplier_payment_receipt_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (((bucket_id = 'supplier-payment-receipts'::text) AND (EXISTS ( SELECT 1
   FROM apticket.supplier_payments pay
  WHERE (((pay.id)::text = (storage.foldername(objects.name))[3]) AND (pay.status = 'scheduled'::text) AND ((pay.tenant_id)::text = (storage.foldername(objects.name))[1]) AND ((pay.operating_company_id)::text = (storage.foldername(objects.name))[2]) AND apticket.has_financial_scope(pay.tenant_id, pay.operating_company_id, true))))));


--
-- Name: objects supplier_payment_receipt_read; Type: POLICY; Schema: storage; Owner: supabase_storage_admin
--

CREATE POLICY supplier_payment_receipt_read ON storage.objects FOR SELECT TO authenticated USING (((bucket_id = 'supplier-payment-receipts'::text) AND (EXISTS ( SELECT 1
   FROM apticket.supplier_payments pay
  WHERE (((pay.id)::text = (storage.foldername(objects.name))[3]) AND ((pay.tenant_id)::text = (storage.foldername(objects.name))[1]) AND ((pay.operating_company_id)::text = (storage.foldername(objects.name))[2]) AND apticket.has_financial_scope(pay.tenant_id, pay.operating_company_id))))));


